window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_010"]={"n":"范梈","dyn":"元","poems":[{"t":"上元日","f":"曲","c":["蓬莱宫阙峙青天，后内看灯记往年。","谁念东篱山下路，再逢春月向人圆。"]},{"t":"送张鍊师归武当山","f":"曲","c":["张君瀛洲人，来作武当客。","始来武当时，祇著谢公屐。","弟子百数辈，稍稍来服役。","诛茅立万柱，空中现金碧。","辛苦三十年，夜卧不侧席。","以之律鬼神，故亦如矩墨。","元年踰冬旱，失火烧四国。","野谷方焦熬，六月畿甸赤。","朝廷亦不爱，牺牲与圭璧。","僵巫暨惫史，歌舞无消息。","君时待诏来，公卿初不识。","一朝传天语，问以济旱策。","君云臣鄙愚，造化非所测。","阴阳有开闭，此实智者责。","公卿复致辞，物生今孔棘。","已敕京兆尹，取足输粟帛。","此如解倒悬，祀事惟所择。","君闻犹固让，心实内忧惕。","飞章白玉阙，沥胆殚悃愊。","臣实才浅鲜，臣实学迮塞。","臣有一寸心，愿辅后皇德。","后皇本爱民，民今旱为厄。","或者罪有由，皇亦重开释。","祈谢各有方，咒禁各有式。","上堂荐明水，下堂考金石。","夜分请命既，昧爽大施设。","为坛东市门，经纪法灵册。","庭中玄武旗，飘飘墨黍黑。","君临一挥手，怒发上霄直。","指麾东方龙，卷水东海侧。","指麾西方龙，卷水略西极。","北南暨中央，各以方率职。","某日某甲子，漏下五十刻。","我在坛上伺，不得忤区画。","丰隆与飞廉，列缺与辟历。","汝将汝风驰，汝遣汝雷击。","汝云冯勿漓，汝雨必三尺。","汝不从誓言，不畏上帝敕。","至期果响答，动荡七日泽。","常时人所难，君若不以力。","公卿奏天子，是必有褒锡。","可以宠号名，可以蕃服裼。","君曰天子圣，卿从诚所格。","臣敢贪天功，况乃归计迫。","昨得山中书，至自青溪宅。","向来百弟子，迟归在朝夕。","暾时冬序半，霜下木叶积。","明当课斩伐，结构西岩壁。","山田晚报熟，芝朮及采摘。","狝猿长如人，夜夜盗柿栗。","堤防苟不豫，六气尽蟊贼。","公家事既已，私事容弃掷。","方知用世士，遗世等糠籺。","所过如虚空，焉知去留迹。","我持一瓢酒，欲以赠远色。","岁暮不见君，怅望空中翮。"]},{"t":"奉同元学士以落月满屋梁犹疑照颜色为韵赋赠邓提举之官江浙一首","f":"曲","c":["青天青如石，星辰何磊落。","适见北斗高，忽复滞郊郭。","感此流电惊，行迈孰为乐。","况值杪秋令，清商动凉幕。","芳燕候朋亲，驱车背河朔。","登高望四野，下田毕新穫。","于时不同赏，惆怅睇云岳。","古人有云然，末契重交托。","托契自有初，相晞在结发。","请持交龙镜，比似空际月。","昔月三五盈，今夜三五缺。","月盈自有时，徯君采薇蕨。","采薇陟崇冈，空筐不易满。","季女怀朝饥，日下光纂纂。","岂无机杼思，十旬义一浣。","含悽就经纬，意长丝绪短。","路逢相识亲，要入鲛人馆。","泣下仍成珠，更苦哀歌缓。","缓歌浮云停，急歌流水促。","水流亦有宗，云散复成族。","踽踽行路子，离居振群肃。","会合宁无期，载感时运速。","晨风怀菀林，玄鸟辞华屋。","明发念飞蓬，秋声浙江曲。","浙河名山水，在昔最馀杭。","浩浩负海区，地绝川无梁。","执玉夸禹会，带甲宣吴疆。","慨彼仁义都，风俗殊兴亡。","末代缀繁会，周衢沸丝簧。","闻之虚庙閟，断雨生蛩螀。","幸及九域一，四民乐时康。","游历须慎重，勿用多殒伤。","矧兹握新命，出布尧文章。","虽当日月远，足昭云汉光。","凄其金气厉，嘉实方敛藏。","杨柳卧枉浦，蒹葭委严霜。","物情各有归，我独不得将。","仰视云中雁，肃肃俱南翔。","云雁鸣天中，回首顾齐州。","沙屿重绵互，竟复少迟留。","欲知鸣雁心，黍稻非终谋。","视彼群飞者，矢心良不犹。","不犹将谓何？","岂复不如兹。","明年择圣蹈，既往无复疑。","譬之騉蹄驹，昂藏养云姿。","下乘岁百驾，逸足诚归谁。","伯乐偶并世，当受知者知。","长鸣待俦侣，首路复安之。","所之在东南，断水列风峤。","至人遗吏隐，出处惠兼妙。","干莫居匣中，千年逸神耀。","一朝持入手，未言心相照。","照之千里外，如在咫尺间。","明夜梦见君，怡怡越河关。","惜去不须臾，念来亦循环。","古时岐路人，何用涕潸潸。","景岩草木断，虎豹啼空山。","方冰先春水，野饭维清湾。","买觞斮鱼鲜，甫谢金銮班。","此行竟遂媾，亦慰亲友颜。","天目扫烟岫，日夕飞禽还。","山中桂树多，庶为故人攀。","攀花贻远道，洵美道中轭。","若复无相忘，报之双白璧。","美人如芙蓉，隔浦无相识。","旧交日已违，新交当日得。","各自有殷勤，初不在容色。","俯水愧游鳞，仰空惭飞翼。","眷言执手地，岁暮霜霰迫。","踟蹰复踟蹰，悽恻重悽恻。"]},{"t":"寄谢周文学","f":"曲","c":["周子雅孝友，声价动江隅。","有德斯有言，新诗敷道腴。","示余以咏叹，累日不知劬。","雅亡风亦衰，赖尔亦区区。","与子初识面，青春满洪都。","别来二十年，王事劳驰驱。","山泽念耆旧，风尘扬鬓须。","焉知离忧中？","乃得此长娱。","公园橘柚寒，骥鸣感修途。","发音咏隆施，重见能来无？"]},{"t":"赠冯炼师归岳阳","f":"曲","c":["王子吹笙侣，精神如九秋。","暂携碧山屐，遨啸帝王州。","江湖未识面，寄语旋鸣驺。","夏云逼幽涧，春鸟啼芳洲。","行色当及春，景气适惠柔。","眷眷将归客，胜日怀林丘。","何时谢燕阙？","亦得西南游。","洞庭木叶下，期尔岳阳楼。"]},{"t":"赠学正洙扶榇归真定","f":"曲","c":["朔风吹急水，哀雁绕天鸣。","送子川路远，浩荡扶神旌。","少年挟高艺，求仕入皇京。","祖父通籍家，蝉联及弟兄。","奈何抱长痛，鞠此霜霰情。","伯氏江外居，心殚慈母惊。","奉命持衰来，留连镇阳城。","会言襄祔事，各复东西行。","生养死当葬，若为好爵婴。","勖子泣血日，寡言收视营。","尚爱千金躯，以保百代贞。"]},{"t":"次韵古体二首 其一","f":"曲","c":["偶为淳朴语，即有希夷风。","在世能勿忤，聊以古为同。","大巧三代人，所拙辨伪工。","曲哉末学士，妄拟述作功。","至性苟能尽，焉得推盛隆？","先师予狂狷，盖愤失所中。","于时得依归，敢叹吾道穷？"]},{"t":"次韵古体二首 其二","f":"曲","c":["圣道缺已久，文不充其资。","自从夏殷来，因革当从谁？","中更鸣鸟闻，载叹德之衰。","寥寥大师乐，复得存那猗。","大音苟有托，不必稽其辞。","设有盈樽酒，日夕斟酌之。","乐杯当在手，自今不复疑。","胡为不复疑？","贤者当明知。"]},{"t":"和胡掾","f":"曲","c":["三违江海春，再见岁将夕。","开轩觞微风，忽近载阳节。","鸟鸣气适和，晨鹊亦稍集。","逮欢不犹今，万事已逾昔。","缅怀命世士，具为知所役。","翻知不贤名，可足济身策。","而我拙自藏，流动日月积。","达观良有余，仁者造其极。","播美明珠篇，时草当更碧。"]},{"t":"贻孛朮鲁翀编修","f":"曲","c":["悲风动日夜，游子绝河山。","一别十年流，四方几时还。","忆子旅江外，过余抚林鬝。","晓色竹晻霭，春容杏阑珊。","阳坡鸣赤鸡，阴馆来白鹇。","文义相剖析，宴歌亦循环。","吴星逐梦变，楚月带愁弯。","自来燕蓟中，相望汉沔间。","初传教下郡，或道钓清湾。","起居虽未悉，声闻已难攀。","明圣御八极，震惊折群奸。","登贤弥制断，进士严刊删。","倒泽起游泳，搜空集翻翾。","斯时麟见郊，绝世骥在闲。","岂期脱布衣，复得联朝班。","始疑迹异方，卒见意俱閒。","惟此冰雪壶，近当云雾关。","纪载竹帛藏，润色丝纶颁。","储才藏地閟，抽思刮天悭。","固当让俊逸，焉得委疏顽。","物化岂堪玩，仙栖庶可扳。","寤寐在灵岳，徬徨愧尘寰。","碧草蒙涧沚，青霞冠云鬟。","长生愿不负，竟往事无艰。","常闻羽人言，颇落俗士颜。","早伐九节杖，倚之听潺湲。"]},{"t":"蒙恩供奉翰林未行改佐闽幕自丰城便道取疾由抚过旴与郡守萨侯会约寻麻源不果明日别旰","f":"曲","c":["暂远云霞观，却希山水音。","珠星联极下，璧月动江浔。","始集宝气亭，复趋金晶岑。","马饮树连涧，猿啼风满林。","扬澜思汗漫，睇岭写嵚崟。","辍棹更垂钓，推书时弄琴。","石门生夕景，麻源笼晓阴。","是郡遇贤守，佳致契幽寻。","樽俎迫清好，弦歌彰古心。","郡中宜凤集，泓下或龙吟。","颇愧尘务逼，还为旅病侵。","一行混吏轨，千载负国琛。","既往事莫究，于兹念方深。","姑山如有意，遂许一登临。"]},{"t":"上巳日，文宣王庙陪祀毕，归西馆作，奉贻儒宫诸同志","f":"曲","c":["礼殿肃春荐，斋居清曙钟。","斜街星斗转，阿阁雾烟重。","久去金华直，暂依赤社封。","非才沾教育，希世念遭逢。","修风泄洙泗，治日舒黄农。","深恩曷效报？","彝典幸追踪。","粲粲金石列，锵锵珂佩从。","饮福婴多疾，高卧对千峰。"]},{"t":"昨夜书怀将行，且书且赋，因成十二韵","f":"曲","c":["钜海截上国，危星转清旻。","去来抵二极，俯仰适周晨。","往鹘无遗影，潜鱼有纵鳞。","劲风山叶碎，浓露草根匀。","卓彼赵李辈，郁为唐宋臣。","忤恩非弃置，知命有高屯。","妙句铿金石，荒台蔓蒸薪。","凭高重回首，怀古独伤神。","记别玉堂夜，来寻丹灶春。","常恐学仙侣，亦犹辟世民。","蓬莱虽异坞，即此是通津。"]},{"t":"上牛头石望海","f":"曲","c":["人谓此石险，我言兹境佳。","日兼山气动，雷与浪声偕。","平浦烟浩渺，高林雨参差。","游鱼依碧涧，飞鸟却丹崖。","饮浊逞孤坐，乘危费乱排。","稍知舒磊磈，初不近俳谐。","玄圃知何许？","蓬莱在所怀。","将寻白云侣，高处结茅斋。"]},{"t":"重五日至西峡渡邂逅闽帅王侯盛称山川之壮余谓可以为知矣亦复有赋渡近方山之下","f":"曲","c":["系马西峡间，朝曦射厓赤。","城中见方山，江上成乱石。","缘流感重险，揽势得钜敌。","不有歌咏怀，徒困驰骤役。","因之窃歔欷，美哉此叹息。","尊醑清屡注，盘荔朱新摘。","纷厖异方俗，卓荦同门客。","去去无久留，薰风荡南国。"]},{"t":"送樵隐侍亲之济南","f":"曲","c":["春晚川陆静，日高风雨收。","斑衣随授节，画鼓送行舟。","未知会面期，宁识离思忧？","崇旌殿归雁，柔橹答鸣鸥。","远去违四美，幽寻考三周。","芰荷生历下，烟浪际吴头。","设有来鱼使，因之寄旧游。"]},{"t":"西岩夜宿，怀雷州幕府同僚","f":"曲","c":["月出万籁静，岩宿紫烟深。","邂逅逢清景，飘萧澄素襟。","久辞蓬莱苑，复忆嵩高岑。","扫雪待白鹄，凌霄看翠禽。","如何较奇赏，而此事幽寻。","虽负简书畏，还希金玉音。","泾暗泉移涧，风疏星满林。","愿持千里意，空外写瑶琴。"]},{"t":"奉同陈应举月夜斋宿玉堂有赋五首 其一","f":"曲","c":["崇馆肃玄閟，虚扉敞彤碧。","词林何苍苍！","国器皆奕奕。","顾惟朴樕材，谬忝文字役。","尝僚负简陋，祇事深踧踖。","于焉严明享，况复在今夕。"]},{"t":"奉同陈应举月夜斋宿玉堂有赋五首 其二","f":"曲","c":["奉礼惭明信，敛诚资宴歇。","风露洒九天，星辰逼双阙。","屏听非效聪，规行殊改刖。","春容启华萼，宵影动林樾。","思君空中云，惠我席间月。"]},{"t":"奉同陈应举月夜斋宿玉堂有赋五首 其三","f":"曲","c":["幅员施广图，轮魄昭晬像。","三后犹照临，万代极瞻仰。","宝之在禁密，本以肃灵爽。","岂伊呈苾芬？","遂尔通肸蚃。","洞洞乎其忠，洋洋如在上。"]},{"t":"奉同陈应举月夜斋宿玉堂有赋五首 其四","f":"曲","c":["塞直慕南董，良明宪夔皋。","孰为非我事？","相命须其曹。","被褐骞寒素，奉璋参俊髦。","王戡载简册，臣职放牲牢。","忠敬道无二，笑谈谊弥高。"]},{"t":"奉同陈应举月夜斋宿玉堂有赋五首 其五","f":"曲","c":["烛暗曙钟远，诗成春漏沉。","古苔见隐约，幽桧响萧森。","白雪留寒色，青云延夙心。","在阙谅当补，唯贤庶可钦。","愿逐西蟾影，长栖丹凤林。"]},{"t":"袁州谒韩祠已宜春台晚眺","f":"曲","c":["乘月泛修渚，凌晨访崇台。","层甍匝地起，叠观凌云开。","时须炎夏首，斗柄从南回。","四周翠巘出，六合清风来。","王明犹日月，宪令若风雷。","惠泽绿郊树，陈踪苍涧苔。","鼓钟代寂寞，轮轸路徘徊。","闻兹守郡者，自昔何雄哉。","百鸟见孤凤，众星丽三台。","吏负钧石寄，法已豪分该。","云胡答临眺，远揖谢英才。"]},{"t":"八月十九日，城东辟喧，孤坐书怀","f":"曲","c":["始生值高秋，久客感流年。","眷兹琳宇閟，瞰彼沧海壖。","雾畜朝雨泄，云泛暑风还。","避人非绝俗，淹病实妨贤。","昉膺良辰会，适使中情宣。","静能驱百虑，生已慕孤鶱。","焚香礼碧草，种玉思蓝田。","焉得青鸟使？","驰归王母边。"]},{"t":"留赠黄明府","f":"曲","c":["黄甫古傲吏，而多清白心。","屈身试下位，载道发清音。","洗刷邑弊陋，宣畅民滞淫。","荒村无吠犬，秀陇有鸣禽。","渊明不醉酒，子贱自弹琴。","未必尽师古，何曾暂渝今？","裁诗俯碧涧，煮药玩虚岑。","清眠消白昼，高视抵黄金。","我本江海人，常联桑梓阴。","携持粤山酒，寤寐朔城砧。","鸿鹄岁月晚，鲲鲸烟浪深。","还为异乡别，举手一沾襟。"]},{"t":"由海昏入武宁道中","f":"曲","c":["登高势欲坠，踰险心始领。","戒想适其恒，经过何由骋。","泄云行崦杉，零露浥涧茗。","玄蝉振山凄，白鹭团沙整。","久盼归舟近，况怀垂钓永。","岂不畏严程，无因揽流景。","烟霞蕴至乐，岁月启深省。","百丈有幽期，眷兹心耿耿。"]},{"t":"过梅尉祠下","f":"曲","c":["梅尉清万古，许令腾八埏。","能官不必高，高者乃其贤。","真材储世用，遗蜕或如蝉。","尝疑说者谬，何独今不然？","斯人井灶处，往往在林泉。","还丹诚可学，但恐难为传。"]},{"t":"七月初二夜，洪州对月，怀伯丈亲舍","f":"曲","c":["初秋公府肃，明月到南轩。","开怀纳清辉，林影类溪园。","偶得尘气静，万籁此中存。","物生感气机，候虫噪四垣。","心虚无所入，起坐复何言？","犹云不如雁，飞逝抵高原。","和廉将军村居二章，"]},{"t":"七月初二夜，洪州对月，怀伯丈亲舍 其一","f":"曲","c":["居止简物竞，颇受岁月侵。","诚愿输昆仑，遐举遗浮沉。","时冬万物敛，野迥景载阴。","雉鸣穑在场，烟火村巷深。","儿女戏我前，有酒聊自斟。","自斟何足贵？","得饮胜千金。","圣哲去已远，六籍传其心。","受生敢不爱？","发愤摅长吟。"]},{"t":"七月初二夜，洪州对月，怀伯丈亲舍 其二","f":"曲","c":["念世居难终，忘世亦易度。","今旦庭树落，空明见飞雨。","沉痾从谁解？","采草时自炷。","万里无一归，愿得妙者悟。","寥寥宇宙间，舍此复奚慕？"]},{"t":"九日报熊敬舆","f":"曲","c":["羸疾卧江浒，承恩慰高秋。","木落坞渚净，天朗气暄柔。","便了晨光中，授我双蝤蛑。","呼童敬荐之，风味宜南州。","忆昔客燕蓟，白云从方舟。","于时见此物，千钱三十头。","打黄试新羹，烂醉天市楼。","一日食一百，更为明旦谋。","三日困暴下，传笑诸公侯。","此邦诚罕见，初出愈难求。","矧当浮萸日，倾道俗如流。","厚价得两螯，持之比琳球。","物有少为贵，感事重绸缪。","奈何雷同者，政复多优游。","欲折黄金花，报君向沧洲。","此花苦未发，少待岁寒酬。"]},{"t":"赠安西王提举别","f":"曲","c":["车声何轧轧，去我亦翩翩。","借问车中人，几时到秦川。","秦疆数千里，西与云栈连。","行人秣马过，猿啼上青天。","长安古帝州，宅土腴不偏。","闻君答平昔，宦游祇晏眠。","十龄涉文史，十五怀家毡。","二十学壮游，五十缀朝联。","奉常老掌故，今已二十年。","功业晚何就，萧萧发垂肩。","天子念逢掖，锡官颇静便。","紫衣绾墨绶，此是车中缘。","飘飖上都门，白马锦连乾。","举案招青山，孟光老犹贤。","大儿坐车轩，小儿调马鞭。","中儿又绝好，国语荷珠圆。","旦夕俟君至，买舍清渭壖。","此皆足慰意，日食官俸钱。","俸钱足养亲，亲自有圭田。","人生慕富贵，富贵翻受怜。","不有钟鼎食，亦无膏火煎。","前日三市事，目击心凛然。","当时气凌人，不得呵乌鸢。","观君浩荡去，万事当弃捐。","孔子不西行，及河轨再旋。","今君涉河流，西路方绵绵。","终南与嵩华，是中多神仙。","仙掌出浮云，上有三峰莲。","真人玉拄杖，挂在明月弦。","便当往从之，吸月升太玄。","金鼎交龙虎，使我神貌坚。","奈何二三月，百忧集离筵。","空花如锦机，野色相交鲜。","杨花乱愁思，万条散青烟。","我不酌美酒，敬让故人先。","搥碎琥珀杯，独洒春风前。","春风澹无言，徒以别虑牵。","别亦无所虑，所虑应当宣。","愿及相思时，中肠郁纠缠。","为吹双紫燕，衔书到君边。","矫矫萧徵君，珠贝藏龙渊。","一别如列星，随天夜移躔。","凤有五色瑞，时下岐山巅。","请君问起居，归来定何年。"]},{"t":"宿夏庄","f":"曲","c":["阴晴知何如，开户月满地。","主家种长榆，竟夕薰风至。","半生朝市踪，颇负山林意。","及兹登览馀，亦复缠世累。","疏篱临大道，嘶马骇童稚。","众卧复离披，踌躇独无寐。","江山转寥落，星斗亦联缀。","丈夫十载间，岂独铅椠事。"]},{"t":"夏日，奉酬汪使君","f":"曲","c":["浮云无时停，浮云有时停。","停云在何方？","乃值初雨星。","我亦毒炎伏，欢言酒盈瓶。","解带斟酌之，醉已万虑轻。","飘飘翼长风，便欲东南征。","林壑盖青天，上与霞雾争。","安得径至此？","念之触中情。","使君新诗来，陈义富且精。","私惭应涉浅，如畜不充籯。","忘已量须进，兹乃圣所营。","冰然内热解，始识道非名。"]},{"t":"赠方永叔往教重庆路","f":"曲","c":["汲水得明月，倒影上青天。","客行三十年，未识蜀月圆。","中宵梦巴蜀，秣马辞燕服。","成都虽云远，未到意已足。","远意不可期，宿夕宛见之。","云迷飞鸟道，雨急卧龙祠。","干戈何草草，祇说渝州好。","但得渝州官，甘就渝州老。","渝州古雄城，彭君旧建旌。","至今江石上，犹有古时名。","豪杰世已矣，空城俯流水。","复有江东人，来教渝州士。","方侯天机深，大雅托遗音。","沈潜万夫敌，脱略五湖心。","翩然别我往，长揖仙人掌。","疾风吹大旗，落日明斜舫。","即此少相知，相知长恨思。","巫山桂树发，折寄定何时？"]},{"t":"冬至日","f":"曲","c":["冬阴已解剥，天运旋其初。","晨兴理书策，盼望周太虚。","纤云无凝停，旭景亦已舒。","未知太史家，侦言复何如？","古来圣明世，不必征其余。","和气乃致祥，斯语端不疏。","大田黍稻滋，秋事在菑畲。","誓将理归楫，临江卜吾庐。"]},{"t":"天冠山","f":"曲","c":["江东有天冠，山翠郁嵯峨。","浮岚衍县郭，鸟啼若笙歌。","古来有真人，学仙云岩阿。","丹成脱之去，晞发临咸池。","年深化为石，石色切星河。","至今刚风吹，梁柱不偏颇。","羽人室其下，厌见顶婆娑。","朝阳夏影缩，秋月夜阴多。","吾欲敕五丁，掇之超沧波。","东挂扶桑枝，此心谅匪他。","宏彼日月光，不可将如何？","天寒岁又晏，云露滴烟萝。"]},{"t":"送吴真人持诏宁亲","f":"曲","c":["垂杨十二门，旦旦罗鸣驺。","千骑万骑中，孰是违世俦。","美哉吴夫子，脱洒住丹丘。","气涵群象动，思与万物周。","天马出名驹，逸态横九州。","自从下地走，但饮星河流。","明月落中江，倒影射斗牛。","飘然持玉节，去犯苍山稠。","紫凤把细华，逶迤仙岩陬。","遂经三茅岑，已登阁峰头。","还家拜封君，玉册珊瑚钩。","笑问游子衣，不独五色优。","门县朱雀旌，坐拥金明裘。","开筵浥芳醴，炰觞进庶羞。","承颜开淑训，慰尔道路修。","尔归奉天子，万岁更千秋。","番君大国寿，贺老清湖愁。","烟水三万顷，宫袍在扁舟。","荷花合古渡，此处不夷犹。","云锦双鸳鸯，悠悠戏汀洲。","东风长年来，扬我阑槛幽。","白马络金羁，奈此甚盛休。","侬家阁峰下，霞竹敷稻畴。","鹤集偃松雪，青云互绸缪。","自从干戈馀，川岳秋萧骚。","骨肉倚四海，风云扰吟讴。","闻君复此去，浩荡怀今游。","罢酒黄鹂鸣，高花艳城楼。","良辰难能别，嘉会易为酬。","至乐夫子行，子行无滞留。"]},{"t":"赠揭景哲茂才别","f":"曲","c":["司揭本楚官，子孙以官氏。","揭阳汉建侯，氏实出于史。","同源而异流，流各昧其源。","泛舟在中河，安得穷昆仑？","驱马燕山市，路逢子揭子。","为我述其先，本自司揭始。","及乎旴徙洪，着与揭阳通。","以兹究其源，濒海而南东。","南东烟涛恶，将身犯蛟鳄。","远拜故侯坟，遗踪尚如昨。","归来见翰林，赠以双南金。","集贤亦敬叹，高文留赏音。","二公天下士，子亦庭阶美。","胡不揽家毡？","黄朱耀闾里。","九万扶摇风，相看尚转蓬。","高楼有横笛，送雁上长空。"]},{"t":"赠李端朝别","f":"曲","c":["驱马别旧故，舟楫丽城隅。","欲复少款叙，子云不可须。","哀笳激长云，群飞灭霄衢。","孟冬犹温风，乡此川途迂。","贤良策上第，再命出南区。","沉沉大藩府，勤事以驰趋。","幸接江湖欢，岂期流次殊？","一朝遂西东，何以慰踟蹰？","高霞映列巘，宁不眷名都？","解组翕清誉，在德由丰输？","要当给余用，初终保瑾瑜。"]},{"t":"散步还南轩","f":"曲","c":["幸自尘鞅绝，起游欲何之？","江远夕气澄，开轩纳新诗。","莎鸡振阳砌，蟏蛸结阴池。","珊珊修木静，宛宛好风迟。","桃杏竞秋园，旋随时草萎。","宁不悦生植，肃杀乃其宜。","于斯见发育，及深霜露思。","嵇康本达节，竟受薄俗嗤。","快哉东方生，嘲唅得吾师。"]},{"t":"市汊水驿候邑吏不至，北亭书怀","f":"曲","c":["端坐息万虑，于此道心存。","江沱归雁集，杨柳落柴门。","刻符期邑吏，日晏已成昏。","相望不百里，曾莫思崩奔。","以为公家须，缓急义所敦。","尝抱慢令戒，空复婴忧烦。","藩芊蹂嘉蔬，颇伤主者恩。","虽非四邻物，祛除奚讨论？","小桥通北亭，涧涸青烟繁。","未明复来日，暂得辟尘喧。","尘喧不足辟，班马在丘樊。","远想高堂君，逝将反中园。"]},{"t":"发富州","f":"曲","c":["驽拙谬承乏，巡游至兹邦。","登危始出幽，历览见长江。","不与夷旷会，焉得壮心降？","力小而任重，民忧正纷庞。","斯须举隐慝，颓俗何由扛？","初下丰水船，爽气夕浮窗。","柔橹奏长风，中流鸣鹤双。","景晏川色净，岩际县渔矼。","行止钦圣则，胡能守株椿？"]},{"t":"寄刘掾","f":"曲","c":["往与魏卢亘，谈君在直庐。","会时春月和，省事重踟蹰。","闻子大夫掾，廉厉久犹初。","羁孤限驰驱，不能枉尺书。","建康古名都，自昔帝王居。","陈迹今具在，斯人定何如？","清吟足度日，羹饭可无鱼。","勿论爵禄事，于此自有余。","庙堂议贤宝，椟美常安舒？","峨峨惠文冠，四海将谁誉？"]},{"t":"嘉泽","f":"曲","c":["嘉泽遍群物，山郭余寒收。","日临公馆静，聊足散优游。","古松含晚秀，春桂吐新柔。","树声鸟语和，苔径蚓行周。","念彼农亩士，生涯托岩幽。","虽无岂弟贤，亦免旷鳏忧。","而我委素业，布衣以遨游。","谬通金闺籍，一志旅荒陬。","还归吏乡部，胡宁心不休？","深承采菲意，终负伐檀羞。","庭闱迩江外，何时溯扁舟？","谁能违天命？","且复尽人谋。"]},{"t":"度泽过关山","f":"曲","c":["单车度大泽，有似游梁山。","初飞雁鹜徒，辱在葭苇间。","季冬阴风盛，雨霰纷珊珊。","念我离大府，行役何时还。","朝临昌邑浦，夕指鄱阳湾。","冲泥赴农村，老屋夜不关。","然薪设供帐，风味犹百蛮。","蒸烘湿衣裳，徒御相回环。","极知道路难，犹念奔走艰。","传餐逮明烛，饥渴未容悭。","春和理税驾，且以慰衰颜。"]},{"t":"古干将","f":"曲","c":["畟畟古干将，经世不再见。","丰城匣已空，龙亦久当变。","百怪日夜出，思尔一断剸。","装佩美纷纷，不尔真百鍊。","又恐百怪飞，翻著他人身。","麒麟或失所，魍魉气益神。","不如且深藏，慎勿干星辰。","我歌干将行，庶为君子陈。"]},{"t":"须句曲","f":"曲","c":["朝望须句曲，青桑被原野。","牛马何茫茫！","尽在大堤下。","堤高容可隐，河水堤上流。","年去复年来，青蒲送行舟。","借问行舟里，谁是回乡客？","燕赵与东吴，憧憧竞晨夕。","山中有老人，白发不可量。","自不缘年寿，何因尔许长？"]},{"t":"溯漳水，有怀在京二三子","f":"曲","c":["晨发宜姑渚，迤逦溯黄流。","天清钲鼓和，樯橹随川浮。","南征卜利涉，阳晷适三周。","野花明远川，时鸟咏芳洲。","麦苗已含秀，芦笋亦吐柔。","一行被明命，岂不职思忧？","时物已具变，未得吾行休。","眷眷二三子，秉德聿宣犹。","崇高谅能淑，大业非人谋。","恶乎报终令，庶以答山丘。"]},{"t":"鹊来巢","f":"曲","c":["灵鹊空中至，栖我庭树枝。","树高不寻丈，下有弄丸儿。","朝骑庭树拊，暮仰树巢窥。","寄巢欲生子，值此将焉为？","是以舍巢去，拮据忍如遗。","青天覆上林，何息非所宜？","物情非有异，念亦顾其危。","倘逢爱护者，鹊有复来时。","鹊声但报喜，说似主人知。"]},{"t":"卢鸿","f":"曲","c":["在昔有志士，隐居嵩高峰。","行义矩四海，矫若人中龙。","天子念治具，诏书访孤踪。","既来亦竟往，去就何从容！","架岩结茅堂，虚砌蘼芜封。","身虽草土，间道为世所宗。","攀磴采石华，引手接云松。","朗揖谢污渎，长啸紫烟重。","不能谐圣君，岂徒愧万钟？","安得起斯人？","千载已相从。"]},{"t":"和答杨茂才","f":"曲","c":["始我南山居，与子共朝夕。","服事子尊君，德义蔼夙昔。","焉知二十载，万变如顷刻。","渔钓负平生，浩荡随所适。","进惭负官义，退愧寻幽迹。","而此山水间，时勤问消息。","夜深款岩扃，萝月在屋翼。","清言溢前闻，子学日有力。","世好将未忘，相资庶有得。"]},{"t":"春雁","f":"曲","c":["嗷嗷九春雁，整列向天端。","虽念洲渚幽，已违霜雪寒。","群行旅阳土，亦为稻粱难。","唼食曾未充，知时讵能安？","衔芦领孤雏，萧萧理羽翰。","明年还当宾，勿兴中路叹。"]},{"t":"韩山曲","f":"曲","c":["韩山白云下，遥见翠竹祠。","其祠何代人？","云是宋君时。","里中有周氏，子孝母深慈。","所以乐慈母，不吝千金资。","为母筑别馆，勾带好园池。","母曰我暇日，临眺良欢怡。","夹山为寿藏，死汝葬于斯。","及死如母言，攀恨无穷期。","即馆奉母容，洒泪松柏枝。","至今空涧阿，幽鸟鸣声悲。","故老更为语，母训犹父师。","子亡孙已贵，孙复昌书诗。","紫衣腰黄金，入侍白玉墀。","间岁万里至，展省甚光仪。","流水莫自急，浮云有余思。","谁能和此曲？","为继棘荆辞。"]},{"t":"二杏","f":"曲","c":["北邻杏一株，身作龙盘拿。","直上青天中，虚空高结花。","南邻杏更好，枝干相交加。","三月二月时，匝地堆红霞。","自我来京城，寄居诸公家。","其地僻且阻，茂树绕窗纱。","亦有桃与李，盛节争豪奢。","虽富无可人，纷纷乱如麻。","晚遇此二杏，突兀超尘沙。","尝时好客来，立旆遥咨嗟。","欲去复顾恋，往往至日斜。","我昔直词馆，羸马道路赊。","晨往昏黑归，无由领其嘉。","今我已投散，终日犹枯查。","朝暮出见之，百匝虚檐牙。","而我又将去，何由报繁葩。","誓将适南郡，辟地江之涯。","种此一万树，漫漫被荒遐。","花成实给食，收拾岁盈车。","此事亦易集，但恐君疑誇。"]},{"t":"赠别白忻州","f":"曲","c":["昔年上都门，送君作太守。","今年太守来，失喜狂欲走。","问知郡中治，称冤不容口。","强欲对酒歌，愁引杯去手。","古来选郡监，本为奸慝纠。","岂宜肆其私？","锻炼易妍丑。","幸逢贤执法，白日云雾剖。","快马归并汾，且以慰慈母。","失身落州县，兹事无不有。","君子善奉持，凡百淑尔后。","排难与解纷，吾愧鲁连友。","明年江之南，得寄消息否？"]},{"t":"检校菊吟","f":"曲","c":["百华已烂漫，虐雨更及晨。","疾风吹青空，好日丽芳邻。","自知园居僻，少与繁会亲。","编篱种黄菊，元不计秋春。","昨朝新芽吐，大叶已轮囷。","轩昂各有意，未谓非其神。","故庐陵云下，苦壤多荆榛。","孤芳久不见，贳酒问远人。"]},{"t":"雨后山庄图","f":"曲","c":["川容丽过雨，百谷会新流。","溪路凌高转，佳木鸟鸣幽。","我田横岫下，黍稷岁可收。","不谓有生意，乃复见将秋。","时从野老饮，欢语载道周。","宇宙无终极，此外更何求？"]},{"t":"道灵岩峡，宿吴都人家","f":"曲","c":["野饭寄峡寺，重过已三秋。","虽若陟降险，颇惟临眺幽。","风翻白练带，树响黄栗留。","旧宅有主人，无复识先猷。","向者之名园，老木阴相缪。","青山入坐席，白水抱门流。","自倾鸡黍载，感古心悠悠。"]},{"t":"谷口散暑","f":"曲","c":["谷口月未上，渔火出横塘。","门前面稻畦，蛙黾杂风篁。","童丱弄山墅，今兹白发长。","新归稍结构，日徯江海凉。","琴书散衡宇，药物布满床。","谢告未缘衰，以疾不得将。","维时仲夏半，织女当西堂。","常恐梧树落，莎鸡戒衣裳。","平生荷耒志，经岁失丰穰。","此行庶无负，海内膺时康。"]},{"t":"登石城驿亭","f":"曲","c":["南游未是谪，北行不当归。","今旦陟崇冈，飘飘风吹衣。","始我在京时，双阙凝秋晖。","别来守穷海，故国音书稀。","窃禄滋愧负，何时睹柴扉。","胡不依白日，去即能如飞。","驿楼俯平川，其下白云围。","雨馀足稻粱，可以信丰饥。","去去道路远，王事毋稽违。"]},{"t":"饶国吴氏晚香堂","f":"曲","c":["大江秋似练，楚树落清晓。","岩际不逢人，翩翩数归鸟。","饶君庭宇静，涧水黄花绕。","烂锦照天朗，繁钱承露小。","何当鶗鴂鸣，误识春事了。","焉知岁寒姿，独立西风表。","乾坤有清气，欲少未易少。","摇落暮春期，美人烟雾杳。"]},{"t":"立秋日，分司书怀","f":"曲","c":["清晨钟鼓鸣，海角金气应。","芳树哀蜩歇，凛节亦已征。","如何向亭午？","毒热尚吹甑。","是宜起居谬，不与安养称。","逝川无回波，驾马少返乘。","簪发耻虚名，丘园激高兴。","飘飘百年内，过者已蹭蹬。","强学而有成，庶以道自胜。"]},{"t":"将赴江浙大府校进士试会疾止建安驿上后山东眺郡城作十二韵","f":"曲","c":["青云建安郡，人物故钟秀。","承旭开芳树，凌虚列遥岫。","溪声涌夜长，石角吐秋瘦。","渔沙府图谶，仙室川浸溜。","征尘汩炎毒，服事弥奔奏。","淡淡鸿鹄举，苍苍鹰隼候。","山英茗在瀹，馆饭菰登豆。","勤渠相国谊，忝窃大夫后。","顾惟论贤能，奚取推寡陋。","吾欲敕五丁，雷电激宇宙。","疾飞移万壑，及此洗昏疚。","起为梅子真，南厓扫丹臼。"]},{"t":"送答里麻廉访使","f":"曲","c":["龙节猗皇皇，六辔忽如流。","圣主命大吏，出按东南州。","东南何所有？","榕荔蔽山丘。","深有险跋履，浅有佳遨游。","绣衣辟庭户，法署若瀛洲。","提封宪令行，霜日净高秋。","公来天为欢，公去海生愁。","渺渺众庶望，为我少淹留。","郊亭接乌石，杨柳荫清沟。","鸟哢方睍睆，花林复绸缪。","吾闻古君子，弗替进退忧。","昕朝正图旧，庶用慰忠谋。"]},{"t":"肇庆李知事会别，至峡上阻风，因以怀李","f":"曲","c":["取别非云暮，王事有程拘。","临流逢执手，复念野踟蹰。","季秋北风急，遥遥别方舻。","出峡江始放，迢迢波浪敷。","仰天觉形全，俯地会心娱。","暂得圭组解，乐与渔樵俱。","抚事悉邂逅，回翔且须臾。","满秩不受更，竟行谅非愚。"]},{"t":"赠李提举之官豫章","f":"曲","c":["公孙阁下士，多似鲁诸生。","昨者闻高谊，兹行起盛名。","文亭南斗近，征旆北风轻。","余亦怀乡郡，今犹滞帝城。","关河惊半面，雪霰念孤征。","芳宴丝簧咽，新诗锦绣成。","长途心果怯，令节眼增明。","渺渺饥鹰度，嗷嗷旅鹳鸣。","露凝秋浦白，云散夕堂清。","是物关流动，何阶计合并。","会须萦桂楫，相共啜莼羹。","徐孺亭前水，因之幸寄声。"]},{"t":"立春日和王翰林","f":"曲","c":["北斗红云上，西城皓雪边。","岁华今若此，宦味故依然。","节轥荒冬后，寒驱夹日先。","楼台通帝极，井落散人烟。","登眺临无际，欢娱信有年。","客情关外地，农事庾阴田。","只有伤弦促，那能效屐穿。","几时归栎社，尽日接芳筵。","宝鼎升平瑞，金幡淡荡妍。","逶迤朱凤集，潇洒白鸥眠。","远业嗟何就，高明赖必传。","道虽沾世用，意漫逐时迁。","顾遇烦频数，欣荣颇倍千。","江湖万里兴，烂熳百花前。"]},{"t":"寄福建杜廉访使君","f":"曲","c":["臬府群工表，言官百世公。","君王资稷契，台阁起黄龚。","吴越联闽服，蛮夷偃汉风。","九州诸道右，一柱众流中。","虎豹精神肃，豺狼道路通。","青冥行劲锐，白日贯精忠。","斧绣扬秋隼，泉阿达夜蛩。","壶冰元自洁，瘴雨不劳空。","贱子嗟何幸，微心誓尽躬。","望来方切切，告别匪匆匆。","祗为文科重，尤惭祖饯隆。","客魂消海鹄，病骨瘦溪虫。","谬敢辞王事，私尝泣老翁。","发缘思母白，颜每应人红。","傥使彝伦薄，其如禄养丰。","以兹三径抚，犹获二天蒙。","上幕刑虽简，沧洲道未穷。","且将心万叠，写入峄阳桐。"]},{"t":"赠翰林宅山水图","f":"曲","c":["敏绝丹青手，驱驰翰墨场。","力能移地轴，艺直破天荒。","素壁清风起，苍崖旭日光。","乔林支混沌，巨石偃沧浪。","鹤背芙蓉影，牛头薜荔香。","参差殊不谬，奔峭亦非常。","仙去遗真馆，人来倚钓航。","向知万里近，不费一生忙。","拟乞丹砂洞，长寻碧草乡。","松乔如可及，结友更何方？"]},{"t":"奉观百官迎香舆出南郊","f":"曲","c":["圣治尊皇极，天章达紫微。","礼宜崇报祀，时则重瞻依。","吉日初蠲策，圜丘肆太祈。","相君苍玉佩，卿士赤金围。","高管寒犹混，清鞭昼渐稀。","合芗来北阙，敷队出南畿。","夜雪侁侁过，晨烟阵阵飞。","难叨惟帝泽，独敬在天威。","礼乐宁无述？","歌声何有归？","从知尧德大，不外赞巍巍。"]},{"t":"和谢友人惠范君用笔","f":"曲","c":["毛君好伯仲，枉驾及东堂。","尽缚曾无笇，同行倍有光。","欲飞随燕上，未化学龙藏。","盛赐怀全璧，斯文托一芒。","姓名浑偶合，润色奈何当！","且效峨眉老，题诗西上阳。"]},{"t":"咏古","f":"曲","c":["五言在王国，安所雕琢工。","肇及苏李辈，犹复相冲融。","往还离别者，人情之所同。","正声始微茫，与世狎污隆。","遂令天地产，山川与云风。","鬼神百物怪，屈曲归磨砻。","组绘丽群巧，争以为长雄。","雅道日以晦，六义谁折衷？","后无述作者，仰止泣麟翁。"]},{"t":"赠别罗元友教授之应昌","f":"曲","c":["翩翩郡博士，骑马涉长道。","居庸关门北，仲夏绵茂草。","应昌信殊僻，宅近今丰镐。","虽当清冽乡，足以消热恼。","天家振文治，造士充国宝。","延揽必时髦，如何恋芹藻？","惊风吹过雨，川水白浩浩。","但祝慎驰驱，归来颜色好。"]},{"t":"感兴","f":"曲","c":["龙驾回层霄，阴冲伏照光。","圣人一万岁，有道过虞唐。","我与二三子，群佩争翱翔。","玉京陈义问，金匮发冥藏。","春容丽藻绘，晨色泫孤芳。","停思候物媚，沉思郁难当。","愿及西北风，驰之通建章。"]},{"t":"四月朔，经杨林作诗，奉命宣布郡县，值大水，蚕麦俱尽，深念民生","f":"曲","c":["吉日涉大川，单舟若鸿毛。","摇摇遇顺风，泛泛凌雄涛。","已过赤岸渚，复宿杨林皋。","棹师何心术？","在险益无劳。","受命未逾期，触目叹所遭。","蚕熟麦再空，万口声哀嗷。","年时有灾地，白屋皆滔滔。","不能补分寸，奚用征秋毫？","纶言本温厚，下布肃官曹。","奉宣吾职尔，庶用救萧骚。"]},{"t":"八月十五日公堂宴别作","f":"曲","c":["悠悠我行迈，去此粤山端。","迟明驻征车，爰尽公堂欢。","开颜俯城郭，箫鼓集仪鸾。","谓欲戒醉饮，重此良辰难。","关门集会府，僚友并征鞍。","更辞无别语，但祝长加餐。","役者四五人，相从出林峦。","亦复路傍泣，岂独殊肺肝。","况我离慈母，朝暮侦平安。","送行各如许，焉得不辛酸。"]},{"t":"秋日海康斋居","f":"曲","c":["吟事久已落，兹晨遇高秋。","泠泠空中籁，袭我书帷幽。","如何寒暑疾，径与大江流。","江流不复转，岁月已还周。","游子去京华，邈在天尽头。","胡雁不踰岭，眷眷非良谋。","排云挹飞观，金爵露光浮。","在远心所仰，胡为滞沧洲。","茅屋足花草，洵美难久留。","苟能一吾志，斯道将何忧。"]},{"t":"怀丹丘，奉寄元尚书","f":"曲","c":["举酒抚往日，酒尽得离愁。","初谓归心迫，海天今已秋。","虎豹守玉关，宫殿天上头。","青春白日和，麟凤俱来游。","广成摄四象，安期扶九州。","下视污浊世，漂转空烟浮。","仙人要我来，招我住丹丘。","岂非交不信？","景晏此淹留。","明日鼓桂楫，径泛星河流。","高楼有长笛，黄叶下沧洲。"]},{"t":"止酒","f":"曲","c":["大钧播群物，壤壤劳吾生。","得酒足痛饮，何用身后名？","所以戒饮酒，岂矫世俗情？","昨日足欢笑，今日愁思盈。","多见桃李花，语乱作棘荆。","反以饮召欢，何以忘亏成？","靡谷汉诏切，丧邦周诰明。","奚必宇宙内？","独有屈子平。"]},{"t":"晓出西郊","f":"曲","c":["自春已及夏，岁籥寝中更。","平旦西郊道，始闻啼鸟声。","川晴树气嘉，夕露枝条盈。","西峰近在眼，白云夹路生。","一从违夙昔，好怀郁难并。","未知高世意，忽复何以营。","屠狗与渔钓，俱足成大名。","卓哉箕颍客，使我抱深诚。"]},{"t":"登西山顶还方涧作","f":"曲","c":["弱质有贞向，依依在物表。","谬当城阙隘，放意穷昏晓。","晨兴理良辔，启途虑已悄。","白日满涧阿，林虚答鸣鸟。","幽寻晚适遇，颇觉知者扰。","俯仰古人迹，达生未为少。","缅彼高翔禽，凌空自鶱矫。"]},{"t":"秋江钓月","f":"曲","c":["秋江明似镜，月色静更好。","之子罢琴来，萝径初尚早。","众峰更灭没，横笛隔幽岛。","我船尔棹歌，丝纶荡浮藻。","潜鱼却寒饵，宿雁起夜缟。","离离不可招，白露下烟草。","高风桐庐士，俊业渭川老。","同是钓鱼人，那应不同道。","把酒酹清辉，如何答穹昊。"]},{"t":"郡中即事十二韵","f":"曲","c":["儋耳九州外，邈然在南荒。","周回数千里，大海以为疆。","古来非人居，禽兽相伏藏。","自从中世来，贡赋登明堂。","其或失抚驭，山薮更陆梁。","聚则成蜂蚁，散即驱牛羊。","高结舞大卤，上衣不备裳。","杀戮乃酬劝，诛之仁者伤。","吾尝七八月，持节泛沧浪。","一旬录郡狱，询事考纤芒。","问之守郡人，莫识为治方。","但见西风多，廨宇秋芜长。","圣哲戒忠信，勿谓不足行。","及兹蛮貊邦，始见斯道臧。"]},{"t":"出甘蔗州","f":"曲","c":["清雨气候变，移船孤石滩。","已行千里馀，始验初冬寒。","暂解雾露毒，稍知江山宽。","新人异言语，故事同忧欢。","思昔夏后氏，封建天南端。","伯业起句践，世远子孙殚。","无诸佐大业，遂作汉王官。","身受闽君策，白日海澄澜。","至今崇台上，列戟绚衣冠。","古来树名节，于此事常难。","惟有精英在，青霄明羽翰。"]},{"t":"晚登南楼眺乌石九仙方山诸峰","f":"曲","c":["自来闽中郡，侨寓公宇偏。","身病縻服饵，单居日如年。","宪署历三试，愚庸寡所宣。","兹行临辟道，黾勉以周旋。","日夕登高台，遥盼四山川。","山川亦云美，宜与万念捐。","慈帏隔江关，稚子目娟娟。","连夜梦新堂，嬉戏在我前。","禄食无寸补，远游何当还。","东风号阴泽，此土候气先。","草木相衰荣，已复争碧鲜。","思及方春时，买船向邵延。","长歌荡暄景，吹笛玉台烟。","行止钦圣训，义著艮象篇。","此岂不在人，虚心以勉旃。"]},{"t":"四月八日访闽粤王无诸古城遂至莲花峰下僧寺寺乃唐王审知祠","f":"曲","c":["维夏气清晏，原薮树茏葱。","上弦适休暇，游咏紫烟中。","石涧演新流，山苗含惠风。","肥苧肤隐白，崇榴叶张红。","抚节警代谢，未归忧心忡。","承官鲜政术，但觉禄养丰。","句稽困日月，始得如游骢。","观省职何补，庶望裨至公。","遗丘隐莎草，废刹在空濛。","而况尘境事，斯理固有终。"]},{"t":"数日毒热喜雨适立秋先三日也","f":"曲","c":["夏末始炎毒，沈忧坐匡床。","起行无所之，登高睇遐荒。","问昔西风归，飖飖向何方？","往还不可期，赖得天道常。","圣主御大历，故可稽明堂。","粲粲白骆驼，兹晨郊路长。","念我伏迁次，江海叶再黄。","旅怀抱焦火，思濯寒冰乡。","忽来浮苍雨，爽气吹衣裳。","稻田已就穫，晚种待新秧。","微躯亦易持，但愿蒸黎康。"]},{"t":"新雨阶除花药倍茂田里生意怀之欣然情至有述简诸作","f":"曲","c":["久旱埃雾集，閒居寡高情。","微雨夜来至，满庭花药生。","长年忧里术，退坐若无营。","偶携一榼酒，得唤故人倾。","念彼氓隶便，劳生在耦耕。","荐饥苟不熟，何以供王程。","幸天沛时泽，食息日已宁。","缮性衡门下，寒饥无足惊。"]},{"t":"苦热怀楚下","f":"曲","c":["苦热不可极，念此西南风。","谁云灏气远，乃在庭户中。","我家百丈下，井上双梧桐。","向夕集归鸟，未秋足鸣蛩。","自从别家来，江海信不通。","宛宛维桑思，愿从孤征鸿。","夜梦白发亲，欢笑携稚童。","倚门望子归，未归忧忡忡。","东皋无良田，何以待岁丰。","盛年将称意，无为学转蓬。"]},{"t":"观钱塘上人墨兰二首 其一","f":"曲","c":["兰以比君子，所贵者幽深。","黯然空谷中，远为人所钦。","志士秉美德，如玉复如金。","笃实而辉光，芳搴出乔林。","偶然为时出，节义凛森森。","下惬烝庶望，上当君王心。","功成无所累，宿好在云岑。"]},{"t":"观钱塘上人墨兰二首 其二","f":"曲","c":["翰墨者谁子？","妙年出江关。","剪须事浮屠，游戏在云山。","时将骚臣意，写入尺素间。","嗟彼为形士，长往不知还。","其心犹有慕，岂不薄茅菅？","学古宁为人？","诚念修已艰。","圣哲虽异代，讵云不可攀？"]},{"t":"明月几回满","f":"曲","c":["明月几回满，待君君未归。","中庭步芳草，蝴蝶上人衣。","谁念同袍者，閒居与愿违。"]},{"t":"苍山感秋","f":"曲","c":["苍山秋意长，池馆静而閟。","雨止修竹间，流萤夜深至。","皇羲世云远，雅颂日凋弊。","举手遏颓波，谁识作者志。","乌啼鲁东门，泗水不染袂。","后去三十年，直可肩圣知。","机关系风化，词语特细事。","月落闭虚帘，坐梦太古帝。","扬眉赪玉色，尽发养生秘。","勿谓仙学难，此道可立致。"]},{"t":"酬申屠子迪","f":"曲","c":["碧月出海底，挂在青天中。","美人如明珠，沧波思无穷。","身非千岁蓬，欲逐万里风。","愿因纨素衣，托向孤征鸿。"]},{"t":"筠州东都遇雨","f":"曲","c":["高林展夏绿，杲日转城冈。","四国金石流，忽见飞雨凉。","飘飘西北风，亦复至我傍。","我行初涉旬，去意已徬徨。","亲交苦滞留，川陆互阻长。","远行虽有命，期至讵能忘。","宵分睇南星，命仆戒川航。","岂无他方愿，且及顾旧乡。","旧乡宁非怀，吾生未渠央。"]},{"t":"赠宣掾蒲锳还静虚山房","f":"曲","c":["扫地谢尘鞅，坐诵圣贤书。","妙年陟府署，服食犹休居。","闻子进修地，花药罗斋庐。","惟静故能定，有容当在虚。","而虚乃非空，养之贵安舒。","苟能充至理，德业将有余。","子本西蜀珍，西南散簪裾。","问知其方俗，有若邻华胥。","教化本自然，匪学故有初。","况彼声教敷，封疆常晏如。","清秋武昌郊，氛雾夕开除。","谁能不重别？","执手以踟蹰。"]},{"t":"远游","f":"曲","c":["远游非吾志，偶堕天一角。","去就亦有期，宁能计今昨？","料理贫居士，守书负西郭。","清心见古初，德宅甘寂寞。","杜门坐春深，绿竹解寒箨。","虽无清时赏，幽意各有托。","千载非长生，松乔未足学。","焉知勾漏令？","不厌宦情薄。","山中归去来，朝霞可以酌。"]},{"t":"述古","f":"曲","c":["天下有大垣，人自隐多岐。","任理忘恩怨，何乃累吾私？","元气育万物，雨露丰悴之。","丰悴虽有恒，还复系其资。","强者固弗已，弱者自有期。","向者橐籥中，竟是谁设施？","美哉唐虞圣，至治以无为。"]},{"t":"泻露亭","f":"曲","c":["初秋白露降，爽气迫虚帏。","薄林方泥泥，洒汉复霏霏。","暗袭玉堂悄，斜飘金掌微。","鹤眠寒屡警，萤火湿犹飞。","叶垂知月朗，花艳怯阳晞。","兰饮畏朝坠，草沾伤夕归。","为霜当夙戒，去日漫增欷。","俜停吴宫女，三月采蔷薇。","挹彼枝上香，散入舞裳衣。","千岁亦不灭，但恐愿相违。","君子保世泽，在久愈光辉。"]},{"t":"顺昌道中","f":"曲","c":["冉冉秋序高，劳劳客程促。","如何霜霰交？","不见原野肃。","颠崖绚夕红，古涧漾寒绿。","非惟藤蔓敷，亦复芳气馥。","物生固有常，气候殊过续。","以兹羸疾身，动往居瘴毒。","念彼闽村人，田稀口如粟。","耕种上青云，妻孥力凉燠。","吁嗟公私弊，群需待其熟。","安得廉耻吏？","俾之食常足。","上以承恩光，下以厚风俗。","丹心映皓首，我何自拘束？"]},{"t":"玉台","f":"曲","c":["晓出玉台道，山川稍夷旷。","只愁滩石际，磊落更万状。","市楼倚崖岸，山顶列石障。","是中更有人，隐约葱倩上。","我愿从之游，长风涉玄阆。","还归保精路，高视神目王。","空濛飞鸟过，惨淡回波放。","由来心力疲，会意乃益壮。"]},{"t":"节妇王氏","f":"曲","c":["妾年四二三，始识月团团。","十二学女工，刺绣如鸳鸾。","十九嫁夫家，事姑施衿鞶。","夫婿良家儿，世籍为王官。","虽联朱紫贵，不习绮与纨。","过庭执诗礼，开口若惊湍。","风仪在一时，争作玉人看。","天地忽降毒，摧折青琅玕。","回首四十春，景光若流丸。","贞心守松柏，芳性轶芝兰。","落月帘帷曙，西风机杼寒。","沈思往昔事，泪下红阑干。","豪客至茅屋，举家窜林峦。","入房卫病姑，身死白刃攒。","相向义怜释，视死色无难。","亲知为叹息，保社为辛酸。","欲与上州府，为妾旌门阑。","妾实无所愿，所愿在所安。","妇人往从人，阿母涕汍澜。","送行遗之语，敬顺无违欢。","匹偶固有时，宁知忧患端。","辛苦蹈物变，岂羡身独完。","殷勤谢旧故，闻者摧肺肝。"]},{"t":"赠海康举进士者","f":"曲","c":["圣主征儒用文学，翩翩五士起海角。","元戎虎帐飞荐鹗，泮水成材玉新琢。","吉日举饯钟鼓作，皇华大夫绣朱襮。","快马凿蹄轮脱斫，相送西风出郊郭。","问君此行事何若，于菟要是赤手缚。","候雁南飞不逾岳，洞庭山秋木叶落。","词场先锋夺霜锷，万里青山上黄鹤。","明光宫中问礼乐，董生策有经济略。","一朝声名动河朔，往取青紫如六博。","前年礼闱开峻擢，明当接武丝纶阁。","归来锦衣照丘壑，人生无如进士乐。","呜呼，人生无如进士乐，勖尔高步翔寥廓。"]},{"t":"奉新县楼对月，望浮云山李八百洞，超然有怀","f":"曲","c":["白露浥宵桂，月满浮云山。","遥想山中人，与我身俱闲。","少日曾陪供奉班，流浪三千随百蛮。","海水接天看不足，却归万壑听潺湲。","累土成岳谅非艰，蚤服玄英勘大还。","金阙玉清名籍在，不应犹自恋人间。"]},{"t":"闽州歌","f":"曲","c":["闽州土俗户不分，生子数岁学绣文。","围绷坐肆杂男女，谁问小年曾识君。","古来夜行斯秉烛，今者衢路走纷纷。","那更诛求使者急，鞭箠一似鸡羊群。","古来闺阁佩箴管，今者女工徵六军。","虽复太平少征战，设有备豫将何云。","去年居作匠五千，耗费府藏犹烟云。","官胥掊克常十八，况以鸠敛夺耕耘。","祗今弃置半不用，民劳竟是谁欢忻？","岁岁条章省烦费，幸且不省无方殷。","唐虞在上俭且勤，后王犹复锦绣焚。","岂有夔龙让姚宋，不言忍使忧心熏。","观风自是使者职，作歌虽远天应闻。"]},{"t":"奉陪京城诸友游南城，寻丘尊师道场作","f":"楚辞体","c":["我本渔钓清江滨，三生自是华盖君。","往从竹浦拾明月，初向芝山寻白云。","闻有仙人姓丘者，旧庐正在燕城下。","杖藜随步蹑天梯，千尺云门净如洒。","门前水流清且深，朗如石镜开烦襟。","中有幅轮转浩劫，多见听者无知音。","高莫高兮嵩山之中岑，幽莫幽兮壶峤之云林。","万金买闲不易得，一到城市无归心。","尧舜之事俱寂寞，独留一人在丘壑。","问渠羽驾来仙坛，夜夜疏星迷皓鹤。","我为长春行，兴在碧草间。","白日又欲暮，浮云无时还。","十年住天都，尘土污客颜。","于此意不惬，泠然遂怀山。","更将携手上烟萝，曾是轩辕弓剑过。","我来正值五月半，青天渐少绿阴多。","每思东山公，兴来恣婆娑。","左持玉麈挥俗客，右引采扇遮天娥。","明时豪达尽如此，逝且不乐今如何！","我亦欲唤细腰舞，白马驮酒金叵罗。","诚恐道人嗔我慢，空遣弟子来相看。","上堂椎鼓日色晏，孤我青精白日饭。","黄金台前春已归，海榴花发乳燕飞。","同行佳人莫相违，相思更赠女萝衣。"]},{"t":"赠刘山人游湖南","f":"曲","c":["楚山高高楚水清，之子西还复远行。","手持空县宝月鉴，人中到处测公卿。","楚有羁臣面如削，千载奸谀胆惊落。","谁能早向太平年？","识得声名等光岳。","洞庭湖上莎草生，湘娥祠下鹧鸪鸣。","与人言必据忠孝，岂独卖卜严君平？","子言亦是蜀州士，家寄钱塘小江涘。","九野飞鸿逐便风，行色将我泛湖水。","湖水上，几时来？","自古生才须世用，试为今人青眼开。"]},{"t":"捣练图","f":"曲","c":["深宫佳人白日长，夜感蟋蟀鸣中房。","起视河汉心回皇，云鬓笼松分作行。","清水如天收素练，翠蛾带月杵玄霜。","辘轳无绳金井悄，边头不见梧桐黄。","裁缝熨帖坐在床，载玄载黄公子裳。","制成不远烦寄将，但见寒暑彫三光，身体甚适平时康。","君不见古来边庭士，雪压关河征战多，拆尽衣裘泪如水。"]},{"t":"题李白郎官湖","f":"曲","c":["当时郎官奉使出咸京，仙人千里来相迎。","画船吹笛弄《绿水》，何意芳洲遗旧名。","唐祠芜没知何代，惟有东流水长在。","黎侯独起梁栋之，彷佛云中昔轩盖。","南飞越鸟北飞鸿，今古悠悠去住同。","富贵何如一杯酒，愁来无地酹西风。","大别山高几千尺，隔城正与祠相值。","青猿夜抱月光啼，挂在东湖之石壁。","黎侯本在斗南家，枕戈犹自忆烟霞。","祇拟将身报天子，不负胸中书五车。","昨者相逢玉阙下，别来几日秋潇洒。","黄叶当头乱打人，门前系著青骢马。","君今归去钓晴湖，我亦明年辞帝都。","若过湖边定相见，为问仙人安稳无。"]},{"t":"王氏能远楼","f":"曲","c":["游莫羡天池鹏，归莫问辽东鹤。","人生万事须自为，跬步江山即寥廓。","请君得酒勿少留，为我痛酌王家能远之高楼。","醉捧勾吴匣中剑，斫断千秋万古愁。","沧溟朝旭射燕甸，桑枝正搭虚窗面。","昆崙池上碧桃花，舞尽东风千万片。","千万片，落谁家，愿倾海水溢流霞。","寄谢尊前望乡客，底须惆怅惜天涯。"]},{"t":"梁掾枉教冬菊之歌，仍韵答贶","f":"楚辞体","c":["中书省郎梁茂才，嗜好雅与时流乖。","休衙归来紧闭户，剥啄或为幽人开。","屋前枯杨千万树，屋后官槐傍官路。","别起新亭翼瓦间，昼阅黄花夜吟句。","自别仙城白兔公，采英泛菊九秋同。","江清木落寒雁远，我思古人烟浪中。","彼美人兮无此美，不见忧兮见之喜。","本是千岩万壑姿，如何肯落君家里？","昨夜遣诗儿过门，挑灯三诵月黄昏。","更酬迭唱未足报，要须共倒花前尊。","君不见长安富儿买歌笑，意掷千金惜年少。","桃李如今不似春，勖子含和保贞曜。"]},{"t":"钱舜举画马歌","f":"曲","c":["钱君画人胜画马，安得名骢妙天下。","青云隐约见龙纹，有意轩昂驶华夏。","圉官山立颀而髯，朱衣黑带高帽尖。","问渠掌握讵有此，牵控宁知人汝嫌。","君不见才士受束缚，往往因之纵寥廓。"]},{"t":"杏叶黄","f":"曲","c":["杏叶黄，天雨霜。","穹窿携日照八荒，回光照见白玉堂。","堂中美人双鸣珰，中宵抱被直西厢。","忠君爱亲两不忘，奈何零露沾衣裳。","清晓楼头见征雁，不如谢官归故乡。"]},{"t":"题姑苏丁氏一乐斋","f":"曲","c":["人生开口日几何？","一日所得亦已多。","请君为我酌美酒，我当为君歌乐歌。","堂上仙翁紫锦袍，堂中硕人冠嵯峨。","瑶池日迟眩五色，椿树春生交万柯。","借问彩衣行者谁？","丁家令绪如丝萝。","兄弟无故父母存，此语未必惭邹轲。","况昔知君在朝列，赞教国胄悬玱珂。","当时权幸悉故旧，青紫可拾不肯阿。","扁舟一去江海远，事寔由己非由他。","他人束缚我掉手，此又一乐信所过。","要当高名日益升，使廉如华分如河。","归掩茅斋坐清杳，松竹交荫花成窠。","丈夫所就类如此，剑绝即与浮云摩。","聊题长歌送君去，出门咥笑临鸥波。"]},{"t":"赠彭生","f":"曲","c":["自来西垣二月吉，品裁良士无虚日。","上感天子大圣明，下知朝政靡阙失。","耳闻目见心所然，莫此名郡彭君贤。","辞官归养终二亲，流水二十有四年。","古人作官计百世，今人动作晦朔计。","赤面持筹舞铨吏，哀哉贤愚同一致。","岂知彭生后时宠？","更二十年犹始至。","耕田足雨稻刺波，种树绕天花照地。","未知羲和多少事，但愿尧舜一万岁。","千钟有待亦人情，尺璧无瑕乃士贵。","四牡以之不为伤，蓼莪以之不为废。","王人若征雅道阙，清庙朱弦倚三二。","美哉彭生淑庆源，孝子亦在忠臣门。","几人叹嗟向穹昊？","下马指点铜台村。"]},{"t":"侏儒行","f":"曲","c":["君不见东方朔长九尺馀，不如侏儒长三尺。","朝捧一囊钱，夕竟饱死复何益。","死者不可作，饥者食有馀。","堂堂之躯天所命，生之短者续则悲。","嗟哉世之人，羡彼侏儒复何为。"]},{"t":"辘轳怨","f":"曲","c":["门前水扬声似雨，幽人当窗碧弦语。","东里征夫去不归，一双蛾眉镜中舞。","年年井上攀辘轳，劳心只恐秋葵枯。","他家种得长生草，梅花落尽青青好。"]},{"t":"田君写真","f":"楚辞体","c":["田君力斡成霜铁，一笔能开万豪杰。","总是人间敌海愁，但自不忘泓颍别。","我所思兮大江濆，欲往致之道路分。","安得烦君写作巫山与洛中？","有美人兮，泛波上之游鸿，行岩巅之素云。","呜呼此君不可见，独立乾坤泪如霰。"]},{"t":"赠郑元泽别","f":"曲","c":["燕城闭门百花节，郑郎骑驴索我别。","示我高人王右丞，辋川之图澹明灭。","一从辞山去吴越，寤寐乡关五情热。","偶逢此卷即欣然，人间何处无奇绝？","虞生教授司成馆，文字精神万人杰。","品题一百二十言，一言不作溪山说。","卿云亦有溪山趣，事与虞言当合辙。","赠朋与亲各有义，颇愧红尘驱蹇拙。","更欲相留度小春，夜深缟杏都成雪。","平旦何以答画图？","为解临江双佩玦。"]},{"t":"张月梅子昂竹石图歌","f":"曲","c":["近来海内写竹石，集贤学士有李衎。","吴兴翰林公更神，大抵不令石作板。","半幅萧萧烟雾枝，如卷中有千尺奇。","洞穴常起鬼神疑，嵩华衡岱狎童儿。","金溪处士清似鹤，携此随秋访幽壑。","我忆为公故僚吏，细抚遗书双泪落。","吁嗟翰林今世无，一笔犹可重江湖。","鸣凤之下出瑾瑜，高风况足励顽夫。"]},{"t":"西黎歌","f":"曲","c":["一十三县海之州，四城结带相绸缪。","中有群黎集百峒，耕凿不知尧舜忧。","手扶长弓架钩箭，白马白似雪花片。","此又外黎渐汉习，仇杀从前如旅劝。","春花满山禾满皋，妇馈壶浆夫血战。","曾不如深居不识礼教人，又谁使之郡若县？","黎雾山高裹白云，哀猿惊鹿夜深闻。","下濑戈船今已远，行人犹说路将军。"]},{"t":"掘冢歌","f":"曲","c":["昨日旧冢掘，今朝新冢成。","冢前两翁仲，送旧还迎新。","旧魂未出新魂入，旧魂还对新魂泣。","旧魂丁宁语新魂，好地不用多子孙。","子孙绵绵如不绝，曾孙不掘玄孙掘。","我今掘矣良可悲，不知君掘又何时。"]},{"t":"望瀛海一首送危太朴之四明兼简廉访邓使君翰林袁侍讲","f":"曲","c":["危君英妙年，独往志千载。","天马出名驹，空行见风采。","昨日衔书到空谷，甚欲留之不能待。","九月开帆指四明，要逐高秋望瀛海。","海水上接天漫漫，世人不知此别难。","当君夷犹碧屿日，是我对月永夕猿狖啼青峦。","江树叶飞天雨霜，江上吴歈思断肠。","窈窕徐家儿与女，却望蓬莱如故乡。","君行却向三山望，云雾轩窗六鳌上。","东方虽乐不可以久留，归献仙公白云唱。","西过钱塘遇顺风，为拜湖南持斧翁。","会稽学士卧云岛，朱弦流水鸣孤桐，道我寄语莫匆匆。","送君有情亦如海，海水有尽别意无终穷。"]},{"t":"重登兴真观小楼","f":"曲","c":["濒湖观户旧倒颠，新起小楼明且鲜。","道人不惯养白鹤，食豕却来堂下眠。","偶闻使者薄暮至，考鼓挝钟吟昊天。","春茶煮就且莫试，慷慨凭高询往年。"]},{"t":"至日行","f":"曲","c":["长安夜半通明光，群公冠佩列雁行。","泰坛三成乐万舞，布衣类得齐鸣珰。","小官需次祗自贱，当日再拜谢日长。","多少朱门围艳质，何当起视东方白。"]},{"t":"得黄太史重碧拈春酒、轻红擘荔枝十字扇面，以归友人","f":"曲","c":["豫章先生行孝友，作书往往心应手。","想当挥汗临风时，不在荔枝与春酒。","竹枝歌中喜鹊鸣，食莲感秋思弟兄。","素纨便面大如斗，送与君家作千寿。"]},{"t":"孟先生","f":"曲","c":["孟先生，爱青山，看山累月出不还。","蹇驴长笑天地间，杖头酒壶时取酌，身须饥病多容颜。","往时佳句动明主，富有声名无比数。","先生遇之亦不惊，去卧南山紫萝雨。","嗟吾岂是先生徒，朝朝饱饭谒禁庐。","暮归却向衡门趋，刻画造化论锱铢。","但有千载名众人，不知而已独信非其愚。","未知吾师先生，先生师吾孔子、不师周公，吾亦聊以自娱。","嗟哉先生独不得相与于同世，云龙上下游八区。"]},{"t":"七月一日，飓风后，奉和廉访使","f":"曲","c":["海上飓风久不来，一日示我破柱雷。","乘此便欲归蓬莱，炎州四时无落叶。","大木不效躯干折，怪事何止犬吠雪？","蓬门土锉虽足怜，日月昼夜行青天，借尔楚竹洗蛮烟。"]},{"t":"奉观许尊府遗墨","f":"曲","c":["奉常许君玉色立，手抱父书红锦袭。","纷茫蜀令九霄神，抉摘郢州千首湿。","钟张虽云世已远，任赵未可肩相及。","叶满天地雨声急，我纵览之重于邑。","却忆风雷昨夜颠，万壑起尽蛟龙蛰。","不然尺素寻常耳，何日萧萧百灵集。","草堂惊怪不敢留，至宝岂复能轻酬。","还君子孙世善收，扁舟归弄江湖秋。"]},{"t":"夜上乌岩","f":"曲","c":["扁舟夜傍乌岩宿，然火上岩寻古祠。","老巫辍睡启神户，牵幌请官窥汉仪。","汉家将军利于鹘，征行往往皆良奇。","当时光武皇帝圣，举以善驭皆周知。","将军再出定穷粤，忠义耿耿光精垂。","不然夷祀已千载，何定至今歌舞之。","高悬铜鼓五兽缺，以手摩拂增深悲。","蜈蚣宵行蛛网结，不识款书何岁时。","庭中蕉叶照石面，猛虎出谷灵风吹。","泽鱼导从吏扶掖，欲留颇复惧深危。","登临有客动必戒，况此星露景倭迟。","独立苍茫问横浦，明日江山劳梦思。"]},{"t":"朱炼师洪崖丹井歌","f":"曲","c":["城西山，相钩连，隔水照见蔚蓝天，中有芙蓉碧崭然。","真人手持绿玉杖，瀛洲一去茫无边。","谷岩历落挂飞斗，楼阁崔巍凌紫烟。","古松当道石作根，松下寒濑萦潺湲。","百花尽绕诸峰前，前有神龙藏九渊。","赤鳞蜿蜒过千尺，四海丰登长晏眠。","尧舜在上位，佐命皆惠宣。","岂如秦汉主，烧丹学飞仙。","白玉之牒黄金编，楼船美人去不旋。","穷极耳目欲，思比赤松肩。","焉知清静化，乃可与长年。"]},{"t":"古杉行","f":"曲","c":["丹陵观，有古杉，屹如双阙当云门。","云是钟君之手植，君去此树馀空村。","尾摇翡翠梢八表，根结蛇蛟行九原。","幽边岂无鬼神护，深处直形天地恩。","一方拆裂引穿溜，犹是百年烧火痕。","苍皮树里渐欲合，始知草木有道存。","或云下有丹火伏，四时地底皆春温。","神还复壮此其验，疑是自此无传喧。","平生政坐嗜奇古，来看适值寒冬昏。","长歌沈思绕其下，夜半月高松露繁。","飘飖叶县凫舄影，牢落丰城龙剑魂。","何当唤起博物者，共骑黄鹄凌昆崙。"]},{"t":"题皮野逸亭","f":"曲","c":["方丈新亭隐丛筱，下有长风荫清沼。","林间白日漏游丝，空外青烟送飞鸟。","人生百岁今半之，更百千岁将奚为。","麻姑自是好风骨，按行蓬岛归何时？"]},{"t":"钓台歌","f":"曲","c":["吾慕严子陵，隐居富春山。","故人乘六龙，身随鱼鸟闲。","羊裘大泽雪在须，忽来导从入皇都。","掉头不受谏大夫，高风逸节何代无？","慎勿沧浪轻钓徒。"]},{"t":"首阳山图","f":"楚辞体","c":["山漠漠兮谷逶迤，中有二士形容饥，问之不答告者谁？","在昔父死人致国，弟让兄辞俱去之。","一朝隐居北海北，去乱就治归人师。","遇世偶有战伐事，叩马垂血陈愧辞。","君王知名义臣直，直不退听将奚为？","见兵不果事乃定，耻食其粟隐于斯。","终然饥死兹山下，到今称诵犹当时。","白旄黄钺不可追，功业甚盛德甚衰。","救民水火事诚危，三纲一失谁扶持？","是以圣人表其怨，谓彼仁者良由兹。","首阳之坟高几尺，自古富贵埋没野草空累累。","我欲酹北斗，荐以黄金卮。","展图涕涟洏，此意画者宜不知。"]},{"t":"赠余相师","f":"曲","c":["幽人本自居丘壑，误上青天养黄鹤。","长敖四海不知归，几见珠玄杂花落？","厌原山下遇余君，语余世事徒纷纷。","书眼犹如牖中日，宦情正似岭头云。"]},{"t":"张明德经历松石图","f":"曲","c":["张君画手天下奇，往者京城曾见之。","济南参议最博雅，每为送酒题长诗。","深山大泽生乔松，缄封寄我章江湄。","问君安得致此本，吏椟政类麒麟羁。","又费临川百日假，不尔能事何能施。","涧阿无人白石烂，飞泉但见下涟漪。","老夫对此神惨恻，况近岁寒霜霰垂。","高斋展玩意未已，便欲共赴青云期。","搔首弦歌白驹操，悠悠四海将谁知。"]},{"t":"二韩诗，为韩吏部作","f":"曲","c":["太行青云城上头，城下乱水亦东流。","谁家烟中杨柳树，鸣鸟一似黄栗留。","是时东风荡瀛洲，瀛洲冠带集英游。","有客抱琴来海岳，罢弹为我夸韩侯。","韩侯家庆邘晋始，异代流风尚能耳。","九十丈人住丹丘，犹子类翁翁类子。","一门两世百八十，更问千年今有几？","余系生子子生孙，锦衣烂照晴空里。","我向瑶台听洞箫，灵风浩荡迷宫征。","桂枝翠弄月光寒，一时秋满芙蓉水。","神仙中人无俗贾，说似青天天为喜。","往年初识吏部君，吏部有子才绝群。","与我同僚内相府，给事朝夕均劳勤。","是则知君莫如我，作歌盛德况所欣。","皇都二月花纷纷，美酒斗倍钱万文。","把酒欲醉春日醺，为君却日呼流云，此歌此事今罕闻。"]},{"t":"怀旧游赠别杜君还益津","f":"曲","c":["往与羽人曾结沧洲期，醉骑鲸鱼跃天池。","北走幽都摩碣石，所历至今皆见之。","泽国波光秋潋滟，津亭月色晓参差。","山夹疏钟和雪度，楼栖断角引霜吹。","兰园坐送流莺乱，华观行闻住鹤悲。","别来几度斜阳里，平曲风烟劳梦思。","安得狂心化为浪，去随流水到天涯。","偶向燕城逢杜子，为我立马欢相持。","自言家在碣石西，石西易水清沦漪。","易州风帆日日至，佳人何事重来迟。","重来易迟去易远，便欲从君川路返。","岁年冉冉思无限，诗成雁过云涛晚。"]},{"t":"用韵酬镏茂才","f":"曲","c":["弱冠从游狎山水，三十余年屈伸指。","南随粤鸟北燕鸿，祇今甚矣吾衰矣。","学问无成不了事，况望清名照书史！","得归重赋茅屋春，青眼相看赖吾子。","丹铅曾近更生阁，但惜案头萤乱死。","世情浩荡何足云？","高人不厌席为门。","百丈山前秋屡过，九州外事忆重论。","昔伤萍梗流沧海，暂喜梅花侑翠尊。","制古直须追左契，声英必合绍前闻。","昨朝示我清江作，汹如垒壁瞻风云。","愧我徒当大敌怯，此陈何止摧千军？","流离天骥志远道，悲鸣往往思其群。"]},{"t":"留诸生","f":"曲","c":["凌晨风雨逾山树，把书对酒听鸣扈。","牡丹初茁柳新芽，复逐春光向何处？","元舅曾闻白水誓，妇翁更审清冰誉。","二家姻好信无匹，四海交游知有数。","我于卿门谊不薄，况此阻狭泥中路。","元宵只在数日间，天气未佳须少住。"]},{"t":"凌云篇","f":"曲","c":["往与凌云山人披虎豹、谒太清，是时东风满瑶京，绿杨三月听流莺。","君随挂席湘江行，予亦骑马趋承明。","手把宫袍厌缚身，却忆南溟有纵鳞。","四年辞海岳，一举上星辰。","逢君却向凌云下，心上经纶甚潇洒。","半夜清猿四合啼，长松古月照回溪。","桃花源上路，一去意都迷。","我本凌云峰畔客，何日相从卜其宅。","早服还丹生羽翼，共脱朝衣挂青壁。"]},{"t":"舟下龙舒望九华，有怀秋浦守集贤周使君","f":"曲","c":["长淮初四月，照见九华山。","不见秋浦人，使我心怡然。","昨者蓬莱峰下相周旋，白云冉冉招归船。","余亦泛海追群仙，未知成道何因缘？","可怜柁楼月，咫尺成吴越。","安得冯夷半席风，疾似南飞寄书雁，从君今夜过江东。"]},{"t":"小孤行","f":"曲","c":["小孤有石如虎蹲，西望屹作长江门。","洪涛万古就绳墨，虽有劲势不敢奔。","大哉禹功悉经理，何必有志今能存。","大者为纲小者纪，不徒百谷知王尊。","灵祠正在石壁下，我来适值秋风昏。","明朝东行吊碣石，更与寻河问九源。"]},{"t":"张吏部宅山水壁歌","f":"曲","c":["高堂秉烛见翠微，岩崖突兀当两扉。","庭前系马雾露集，老木倒挂藤萝衣。","问谁妙手能至此？","笔墨简古世所稀。","天官主人为我言，翰林供奉精天机。","忆我寻山客南粤，地暖四时皆芳菲。","眼中得此了不易，便觉宇宙扬清晖。","旅人独行歌采薇，沧洲茅屋何年归？","安得峰头置双鹤，相逐蓬莱顶上飞。"]},{"t":"赠李山人","f":"曲","c":["平生慕事华盖君，四海孤踪随白云。","峨眉山人住旴水，驻马重逢帝城里。","别来相问意悠悠，北走南飞又几秋。","昔向贵溪寻讲鼓，又从蓟郡揽征裘。","展图示我青山屋，山在旴城小江曲。","东风日日荡人归，明发行歌载黄鹄。","忆昔上帝敕游华子冈，中道勒回俗驾宾炎方。","是行傥或如私愿，华子冈头定相见。","麻姑应解索题诗，碧桃花发报人知。"]},{"t":"己未行","f":"曲","c":["二年六月己未朔，京城五更大地作。","卧者颠衣起若吹，起者环庭眩相愕。","室宇无波上下摇，乾坤有位东西却。","自我南来睹再震，初震依微不今若。","昨朝展席坐堂上，耽玩图书静无觉。","堂下群儿又惊报，方馔饔人丧杯勺。","栉者仓皇下床榻，门屋铿锵振铃铎。","祇今犹自腾妖讹，旦暮殊言共郛郭。","大家夜卧张穹庐，小家露坐瞻星落。","焉知怪变不可屡，安巢尽有南飞鹊。","昔闻上帝忧瀛洲，亲敕巨鳌十二头。","特为群臣举首戴，万古不与水东流。","岂其九州亦类此，此事或诞或有由。","上帝甚神吾甚愚，戴者勿动心优游。"]},{"t":"次韵赋吴尊师漱芳亭白、红梅花二首 其一","f":"曲","c":["梅仙之宫在何许，五尺青天隔风雨。","冰雪肌肤绰约人，铁石心肠软媚语。","行藏一粒粟中寄，品格百花头上数。","所以商廷和鼎功，大濩登之六代舞。","呜呼，安得东皇锡白社，胙以金陵为尔土。"]},{"t":"次韵赋吴尊师漱芳亭白、红梅花二首 其二","f":"曲","c":["惟梅本是群仙侣，别有芳姿照微雨。","人尝误作杏花看，我亦戏作莲花语。","即色非空还是色，遽数不终须悉数。","偷服丹砂抹玉唇，赭颜谪向春风舞。","呜呼，安得东皇锡赤社，胙以朱陵为尔土。"]},{"t":"赠陈兄","f":"曲","c":["侍御诸孙美绝俦，辞我远行游桂州。","道路炎暑正足畏，山水清凉须暂留。","昔我效官沧海上，归桌春前拂青嶂。","极知兹郡烟景乐，欲往终然背晴浪。","送君此去倍伤悲，梦寐梅花雪片诗。","故旧相逢凭问信，何时重与觅安期？"]},{"t":"奉酬段御史登岳阳楼之作时分理盗贼至海康","f":"曲","c":["谁能手铺湘水平，刬却君山看洞庭。","昔人已骑黄鹤去，楼前乱芷春兰青。","岂知绣衣后千载，远违凤阙来江城。","凭高吊古落日紫，领客置酒开云屏。","酒酣点笔赋新句，薄海传诵令人惊。","忆我初游白玉京，与君联步趋承明。","手宣皇猷敷帝绩，济济学士如登瀛。","一行竟堕万里外，回首沧浪思濯缨。","守官区区事无补，惟有白发欺人生。","䍧牱水外万竹底，四时鸟语烟边鸣。","忽忽此地复相见，恍如幽梦求仙灵。","中宵秣马不遑暇，君又北乡予南征。","如兹后会复何日，念之使我双涕零。","宫中圣人总四溟，所过海岳须澄清。","铁冠峨峨望天下，青霄快展皆修程。","由来豺虎伏仁兽，况有鹰隼当秋横。","明夜相思隔云岛，月落高台闻笛声。"]},{"t":"赠答杨显民四方采诗","f":"曲","c":["今人论学古人诗，事皆天者非人为。","文章由来贵尔雅，但顾有法何妨奇。","六经固已殊缓急，乐子飞腾自兹入。","国贾宁怀大宝疑，宫工肯效微绡泣。","志至言从意自足，何必王风系流俗？","观变时时到黍离，宗周思近西郊哭。","十道使者明如水，闾阎尽在冰壶里。","观风本是使之职，太息幽人为之起。","昨雨绿苔生晚阁，黄菊花前共秋酌。","采采芳英不盈掬，月落树声连万壑。","去去牛马汗如泉，既别勿计归来年。","治平之音断可传，无庸使我心烦悁。"]},{"t":"题冷架阁脩原图","f":"曲","c":["曾泛脩江入海昏，更数百里缘人村。","道至常州四晨夕，犹未遂得穷河源。","山人世世原上住，示我画图联秀句。","安得移家向碧峰？","钓矶长倚沙头树。"]},{"t":"萧炼师","f":"曲","c":["若有羽人吹洞箫，拂手不拾松门樵。","身披破褐笠一瓢，独携云雾通青霄。","幼曾逢人越岭椒，教袭造化为科条。","坐致雷雨不终朝，罔两不习持斧烧。","其徒夸者长哓哓，时夏汗流金石焦。","山川圭璧走乘轺，大巫结舌小巫娇。","但见空宇行肖翘，人谓萧师服神僚。","胡不试手须人邀？","师乃含思坐中宵。","谓患不御犹助妖，便以诚意答狎调。","至期发号从不骄，闭户赤脚飞招摇。","白鬣倏忽朱鳞超，赤日卷上青天潮。","四郊泠泠苏旱苗，列缺一去天迢遥。","喁噞曲士暂颜销，何须坎鼓更烦嚣？","争以俎豆相呼招，谁知玄功坐不要？","师方敛手归云寮，卧听流水鸣朱桥。","采诗观外给空谣，我负师约秋光凋。","昨莫败叶西风飘，相思无由警岑寥。","我作此诗比钩雕，谁其和者以报萧？"]},{"t":"登君堂，酌君酒，为张氏顺堂赋","f":"曲","c":["登君堂，酌君酒，愿君有亲千岁寿。","有蟠者木，嶷彼堂前。","越女能舞，秦女能弦。","羽觞流月，翠幕张天。","粲粲在侧，罗列庶鲜。","登君堂，酌君酒，愿君有亲千岁寿。","昔屈生去芰，君子贵之；","郑庄循爱，终悔其为。","先师遗言，戒尔从今。","至孝有道，岂不在敬？","酌君酒，登君堂，愿君有亲千岁寿，岁岁寿且康。"]},{"t":"赠别张清夫还吴","f":"曲","c":["新雨不作泥，钩辀树上啼。","征夫怀远路，家在太湖西。","别家今几度，杨柳江边树。","念乡车轮下，渐是中年路。","万事中年尚可期，人生且莫长别离。","长别离，向何方。","九江落花清浦香，王雎斑斑凫乳黄。","南望不见三高堂，奈何游子思故乡。","我家诸公济时早，功成身退合天道。","当时未必知者贤，挽不回之卧烟岛。","后来阅尽亏成事，始识从之去时好。","我不能赤手缚虹霓，又不能委身同草木。","生逢尧舜世，肯受泥涂辱。","昨者误奋龙门雷，蝘蜓嘲之自云足。","忧来举觞酹白日，唯有皇天照空谷。","张公子，吴江生，我有千载意，不羡身后名。","为君写作赠行曲，曲中铿戛难为明。","君行不听我意平，明日买船棹秋声。","亦欲东下窥蓬瀛，飘然此去白玉京，须卿禹穴来相迎。","相迎未见须相待，客行虽迟心未改。"]},{"t":"城南诸园观牡丹","f":"曲","c":["燕然牡丹绝世嘉，名园是处列如麻。","清晨步骑醉暮归，胸中消得一万花。","青云长衔若木日，绿水乱泛天台霞。","神功天巧奋心目，依稀半在侯王家。","欲持此花表众芳，斗大亦有欹与斜。","堂堂不动吾所敬，似者何得争豪奢？","我从年少过花下，虽有车马不敢哗。","未知时人作意否？","俛仰宇宙思深遐。"]},{"t":"奉和效古意醉歌","f":"曲","c":["忆我初年三四龄，当客唯对声令令。","夜诵汉赋一千字，朝来千字仍心冥。","自许英年逼华盖，岂信流光不相待？","祇今四十少二年，坐念立忘足悲慨。","我当赠君金叵罗，君当答我黄鹄歌。","吴南水远春似画，欲行未行可奈何！","莫使风雷寄鸣铗，莫叹羊裘堕烟雪。","人生万事如春花，璚花虽晚君须折。"]},{"t":"二月行","f":"曲","c":["二月欲半春风颠，对食废餐心黯然。","排沙荡沙忽到眼，须臾几席无光鲜。","昨者出门吹欲倒，乘黄不病不得前。","百围大木拔莫动，决折断干追乌鸢。","惊雷万车碾空过，倏忽卷地散百川。","未知何自蛟龙怒？","坐使老屋如流船。","先生老屋十五椽，寄住主人从昔年。","崩腾直为居者惜，过客东西何用怜。","幸自环堵无足乐，屋虽朴陋形制坚。","但念素衣发如漆，白黑变尽思归田。","勉焉守之勿易地，会且风止天清妍。","君不见列御寇，御之还得同飞仙。"]},{"t":"送萧二十兄","f":"曲","c":["东郊萧条生事微，快马日日趁朝归。","黑头游宦吐粱肉，青眼高人歌蕨薇。","侬家旅食强甘苦，何物俗流轻是非。","百岁乾坤消屐屦，三江风浪隔庭闱。","柳根腊雪春犹冻，沙上晴云煖更飞。","昔拟此时具吴榜，送行何故不沾衣。"]},{"t":"云林歌，为贡供奉作","f":"楚辞体","c":["朝望宣城，夕企云林。","扫花钓月，清我闲心。","城东之山倚天碧，手扪南斗近咫尺。","幽人筑堂面山坐，绝似谢公故时宅。","谢公今何在，苍苔剪行迹。","调笙诵新诗，流水照白石。","看水作明镜，年光静来往。","夜深敬亭雨，坐见南湖长。","清风被长阪，鸟度蒹葭响。","云之林兮不可攀，中有青猿白鹤相盘桓。","林之云兮不可缚，时来宿我青檐端。","昂藏老仙人，抱剑卧山侧。","忆在中华时，相逢发未白。","问之不笑亦不言，阿蒙中子瀛洲客。","却起遗我宝字书，依稀摄精炼魂魄。","相期后天无极年，共尔守之合自然，专气还得同飞仙。","未登云林堂，试作云林歌。","嗟我久客意衰迈，云林云林奈若何。"]},{"t":"芝山歌","f":"曲","c":["自公习隐华山园，公既未相清乾坤。","三光回明五秀閟，储灵肆启忠孝门。","昔在至元侍潜藩，出佐刺史窥江源。","二十年间蹑台辅，即复拂衣辞紫垣。","忆昔寻真度海岳，骑鲸相见芝山根。","手抛仙人绿玉杖，倾笑为之颜色温。","芝山嵯峨熊虎奔，屏风百叠翠波翻。","青天芙蓉剪秋水，高堂宴罢浮岚分。","醉陪藜杖陟山榭，桑麻被径松满原。","此时细属方外里，但觉泉石多深恩。","帝思旧臣振颓弊，下诏明言征吏烦。","使车日历林涧曲，复携白云朝至尊。","观公出处握至要，自许当有古道存。","方今明堂力更化，颇陋周汉追尧轩。","蛮夷来庭百辟享，圣心正欲严天元。","黄钟九奏乐万舞，庙荐无月无受膰。","大酺精神盖六合，民物自尔能丰蕃。","功成次第勒彝鼎，归去款委寻笙尊。","此是英雄千载事，慎勿轻与常人论。","只恐门墙少壮客，白头犹是芝山村。","且持此山为公寿，愿益公寿如昆仑。"]},{"t":"奉和李监丞醉赠羽人之作","f":"楚辞体","c":["自从堕地爱名山，五岳寻真去不还。","青山无津度日月，旦暮御风行其间。","九江西来赴海门，中有道路古来难。","笑谈解入蛟蜃腹，脱此命与松乔班。","吾尝左揖三茅君，右手直接高飞翰。","至今空濛偃翠盖，望云怀我双佩环。","君从茅山来，青衣白霓裳。","肝胆出古剑，剸裁光甚扬。","玄元皇帝云与仍，称世举德朝未央。","偶吹龙笛过九市，共君斟酌北斗傍。","浪传北斗不可挹，酹之昨以白玉觞。","百觞未已已复醉，援此织女天机章。","举头目送南飞鸿，我自滞留君远翔。","眇眇美人绛珠宫，弦白雪兮歌清风。","浮萍流水相遭逢，何独不在岐路中？","何独不在岐路中，相思昨夜春釭红。"]},{"t":"官河曲","f":"曲","c":["官河人，世居河水边。","严冬二月河冰坚，响厨待汲烹庶鲜。","朝朝投壶先众女，十指冻堕貂金蝉。","今日出门又苦早，行人争惜少夫怜。","凿冰难得水上堂，养姑欲姑喜□□。"]},{"t":"元城行","f":"曲","c":["元城郭使君，爱母不逮餐。","刻木貌慈母，去官西山濆。","上堂示甘旨，下堂候寒温。","人见使君孝，作书细讨论。","我论使君政，亦由孝所敦。","虞周虽已远，此道今幸存。","嗟乎！","使君天壤何茫茫，此道谁与期？","天虽高，孝心本自达天德；","地虽厚，孝心当有彻地时。","何必邦人子弟能化之，致之家国、天下皆尔为。","秋风吹庭树，树叶秋如雨。","秋树则有枯，乌生长顾雏。"]},{"t":"奉寄翰林邓善之侍讲学士","f":"曲","c":["曩承持节江之东，骑驴再上蓬莱宫。","蓬莱仙人歌白鹤，声落五湖烟雨中。","世间爵禄不易致，何独去就如飘风。","朝廷礼乐须制作，六经隐义资发蒙。","论思庙堂集耆硕，启沃宁让前诸公。","闭门读书古都市，四辈冠盖方隆隆。","我生生长在穷谷，那有文字争人雄。","谬蒙引誉百僚上，负禄府署惭无功。","一别十年还又五，昔者少壮今成翁。","谁知复客七闽下，隔二千里来诗筒。","羸躯顿醒瘴疠恶，赖以慰此心忡忡。","粤王城南浪自白，粤王城西花正红。"]},{"t":"望潮曲","f":"曲","c":["潮来直上青崖住，潮住却寻沧海去。","乌石山头望故乡，故乡更在云深处。","我生不如桥下水，消息春秋任流止。","又不如如水上船，去去来来年复年。","负禄旅孤二千里，上念慈亲下妻子。","子生未解别爷啼，睡恋阿婆怀抱里。","乌鸦日日傍人飞，喜鹊时时噪群西。","更有平安书字到，金壶约伴玉人携。"]},{"t":"题先天观图","f":"曲","c":["学仙之人，与仙为徒。","住在匡庐之奥、江湖之区。","张公炼丹作龙虎，丹成御气游太虚。","后来出者绝代无，何不学仙住玄都？","玄都之坛角井孤，上摩万里之黄鹄，下伏千尺之饥鼯。","阴森桧筠自太古，斩种力与开辟俱。","扶桑朝日挂绝壁，坐见楼观青馍糊。","擘崖控弦泻哀湍，春秋云露芝田腴。","我亦人间山泽臞，偶陪夔龙宾唐虞。","有时一醉黄公垆，振风三日撼不苏。","折花不得渡弱水，浑手始识仙凡殊。","玉堂学士危与吴，遗我兹山之画图。","寻窗数户久叹息，无因置我双樗蒲。","独行幽人不受呼，扫叶青涧听啼乌。","日暮萝径相萦纡，萦纡萦纡向何处？","明朝为借麻姑鹏，我亦骑之天上去。"]},{"t":"万竹亭","f":"曲","c":["谁能买山种万竹，残年请老住巴蜀。","结亭更在竹中间，四面云溪写山麓。","风敲最觉夜眠清，雨洗胜延秋望绿。","日吟不限三千字，日饮定须过百斛。","陇西仙翁持斧客，散马凉城行新菊。","为言令弟隐沧江，如此风流天下独。","乃家正在蚕茨野，束束琅玕绕茅屋。","方知白眼待时人，箕踞科头自为俗。","是邦子云剧博雅，闭门草玄食汉禄。","多缘未识此君心，往事微瑕伤白玉。","使君自是廊庙具，方驾前修讵为辱。","平生抱负劲直节，日暮天寒照空谷。","始我瞻望望不及，终我叹嗟嗟不足。","乞官傥或从西游，向子亭边祝黄鹄。"]},{"t":"蕲州城下晚泊与土人语及西方事平有喜而作","f":"曲","c":["野阔秋无际，天空夕始凉。","渔船下浦急，畬火入云长。","洲远怀鹦鹉，山危指凤凰。","戍人新敛甲，垂老幸时康。"]},{"t":"黄州道中","f":"曲","c":["径转山仍掩，沙移圃自成。","蒹葭连水白，杨柳荫门清。","无复论馀事，真堪了此生。","眼中陈仲子，九鼎一毫轻。"]},{"t":"赠孙秀才","f":"曲","c":["四海孙思邈，云礽复盛名。","白驹空谷远，黄鹤大江明。","子去何潇洒！","人知尽老成。","特来容贵近，次第取公卿。"]},{"t":"舍前龙骨树","f":"曲","c":["坞夷篱落见，谁种此江津？","结干多于叶，成阴迥不尘。","取材因恶刺，感事抚长身。","安得艰难际？","相从作四邻。"]},{"t":"百丈山中夜坐，闻谨思将还，忆甲寅入南中，正此日也。十二月二十三日六首 其一","f":"曲","c":["近得雷州信，遥闻弟侄来。","江山淹远望，天地保疏材。","乡为鱼羹起，今宁马豆猜。","残年有心事，未定著寒灰。"]},{"t":"百丈山中夜坐，闻谨思将还，忆甲寅入南中，正此日也。十二月二十三日六首 其二","f":"曲","c":["欲雪翻成雨，何天恰吝情。","似缘春在近，故与月争明。","谷树行行暝，川云冉冉轻。","往年当此夕，孤棹适南征。"]},{"t":"百丈山中夜坐，闻谨思将还，忆甲寅入南中，正此日也。十二月二十三日六首 其三","f":"曲","c":["岁月嗟匏系，乾坤信梗浮。","蹉跎逐越鸟，迂阔问吴牛。","正道曾无弊，旁观各有由。","圣人如可起，吾欲诘东周。"]},{"t":"百丈山中夜坐，闻谨思将还，忆甲寅入南中，正此日也。十二月二十三日六首 其四","f":"曲","c":["斜谷惊风合，空阶坠溜鸣。","灯昏时作晕，漏远不传更。","但得林间趣，何须谷口名。","是谁超物外，不用计浮生。"]},{"t":"百丈山中夜坐，闻谨思将还，忆甲寅入南中，正此日也。十二月二十三日六首 其五","f":"曲","c":["往备清华职，宁知濩落心？","槐街春日盛，杏省午烟深。","出试终何补？","还归敢自任。","祇惭山泽吏，空受二毛侵。"]},{"t":"百丈山中夜坐，闻谨思将还，忆甲寅入南中，正此日也。十二月二十三日六首 其六","f":"曲","c":["客行身万里，家在地中分。","爵命优臣子，江湖远圣君。","夜瞻龙凤气，岁出虎狼群。","旧故无消息，低回瘴海云。"]},{"t":"壬戌秋录囚晚行宁州道中追录","f":"曲","c":["晓发高平镇，前旌路未分。","小桥烟外过，流水月中闻。","虎豹宜多隐，豺狼不可群。","居人敌炎暑，报有竹连云。"]},{"t":"寄题严氏樊川别墅二首 其一","f":"曲","c":["先生天下士，小隐郭东村。","甃水缘开径，楹山对掩门。","士风宁近洛？","川姓不离樊。","樽俎心虽间，衣冠口已喧。"]},{"t":"寄题严氏樊川别墅二首 其二","f":"曲","c":["亦欲西流去，相寻素浐边。","多应百年术，少见一人传。","生事空芝术，心期托蕙荃。","明当询大药，畏子不论钱。"]},{"t":"数日跋涉泥淖，至北山，始霁，暮经鄱阳湖","f":"曲","c":["川路绕长林，岁穷千里心。","贾舟栖港迮，樵火出村深。","欲雪应消瘴，因风忽解阴。","转移足清景，难受客愁侵。"]},{"t":"寄谢董简卿","f":"曲","c":["高人北海下，遂与世情疏。","怅望九霄鹤，携持千里鱼。","风云今迩只，泉石后何如？","诏读须中秘，无疑未见书。"]},{"t":"步畦","f":"曲","c":["白发荣中将，清晨步菜畦。","祇言无所事，宁复有相携？","日静闻禽语，泥融散马蹄。","读书不解俗，犹自负幽栖。"]},{"t":"引儿湾晚泊","f":"曲","c":["席压波心正，舟移岸脚斜。","夕阳明细雾，秋树拥荒葭。","问道独如梦，怀京却胜家。","客愁不自整，更苦暮啼鸦。"]},{"t":"秋雨寓舍酬答夏编修四首 其一","f":"曲","c":["乱竹通邻舍，修梧限掖垣。","日长惟有雨，秋半祇如昏。","野色愁俱破，河流畏更浑。","惟应好僚友，孤寂义弥敦。"]},{"t":"秋雨寓舍酬答夏编修四首 其二","f":"曲","c":["左丞京下宅，大半贮蛩螀。","容曳栖乌地，低迷卧鹿场。","几时衣定暑？","昨夜酒生凉。","太息时人语，依稀不可忘。"]},{"t":"秋雨寓舍酬答夏编修四首 其三","f":"曲","c":["平生谈笑口，未是向人悭。","直以朋友内，难为伯仲间。","陈君元下榻，贺老自怀山。","见谓前修事，因之一破颜。"]},{"t":"秋雨寓舍酬答夏编修四首 其四","f":"曲","c":["倚岩推许逊，负水揖文箫。","万里初邻并，长年此寂寥。","不要麟阁画，虚累鹤书招。","同是西江客，君当结梦樵。"]},{"t":"九月十四日，过紫极宫熊道人房","f":"曲","c":["层轩俯江竹，欹枕对连山。","雨止烟霞集，洲回鸥鹭闲。","紫霄行有径，白日户无关。","但见空中侣，飘飘不可攀。"]},{"t":"九日诸生携酒至城东看菊","f":"曲","c":["楚楚临阶菊，重阳特地开。","慰人良有意，报汝愧无才。","巷杵闻鸡发，邻觞送蟹来。","采英吾欲寄，怅望倚江台。"]},{"t":"阅除，目仲渊宣慰、传之廉副俱出山南。暑夕，有怀，无由倾倒","f":"曲","c":["舍下初秋至，明月出云端。","清辉延细竹，爽气集幽兰。","江汉不容越，方舟逝良难。","瑶琴谁起坐？","中宵为我弹。"]},{"t":"题山居图","f":"曲","c":["平湖含白水，断岸见青林。","篱落初秋气，云山向夕阴。","养闲祇用拙，避俗更怀深。","为问舟中客，何如泽畔吟？"]},{"t":"社前七日作","f":"曲","c":["久旱春始雪，社寒犹未妨。","沉沉莺待木，语语燕归梁。","静想亲交绝，仪求旅处臧。","以身观万物，应系末辉光。"]},{"t":"奉讯浦编修","f":"曲","c":["闻君践马厄，诗赋日应多。","但倚文为命，焉知病是魔？","蒲萄深巷雨，菡萏远湖波。","未始无相忆，经过奈礼何！"]},{"t":"送谭殷卿归徽州","f":"曲","c":["送君从此发，何日到徽城？","已是夕萤乱，况堪秋雁鸣。","行藏无定策，仕养最关情。","见诵覃怀守，名家旧有声。"]},{"t":"题赠李右丞","f":"曲","c":["恂恂李右辖，行义古人期。","缓急仓公传，勤劳卫母诗。","沧波大地转，白首老天知。","莫写青田鹤，鸣皋重我思。"]},{"t":"晚过孔奉常舍下","f":"曲","c":["沧江一万里，书信近如何。","向暮客怀薄，及秋乡梦多。","故人相慰藉，并舍数经过。","但愿长无事，彤庭接佩珂。"]},{"t":"悼远，用友人韵","f":"曲","c":["采江莫采蘋，思食莫思莼。","间岁曾为客，经时独梦人。","林园花动夕，帷帐草留春。","万里燕山路，空怀涕泗频。"]},{"t":"酬孔太祝","f":"曲","c":["苏郎怀印绶，不计敝貂裘。","一去青山下，三年白露秋。","关心悲地隔，涉患见天游。","笳管深无那，晚来动戍楼。"]},{"t":"赠别朱生为南海医教，得问字","f":"曲","c":["拜命辞中阙，鸣箫下南郡。","天晴木叶空，江暖梅香近。","解铎风成阵，开堂月生晕。","欲酹扶胥碑，移船定相问。"]},{"t":"赠别李教授亭赴五羊先往馀饶觐省","f":"曲","c":["行色动西风，乡心去住同。","诸生五岭外，之子大江东。","且羡还家鹤，无愁度海鸿。","若逢天上使，书记莫匆匆。"]},{"t":"赠别徐教授之钦州二首 其一","f":"曲","c":["徐子雅好易，白头来上京。","如何怀远檄？","竟往教专城。","山近烟霞密，江澄瘴疠清。","朋游政事少，况在仰修名。"]},{"t":"赠别徐教授之钦州二首 其二","f":"曲","c":["冉冉岁月暮，悠悠关塞长。","歌钟凝旅宴，舞袖拂征艎。","到日梅花乱，来春蕙草芳。","南金自昔重，寄赠可能忘？"]},{"t":"移居东城","f":"曲","c":["移居古城裔，桑竹似村墟。","已谓丹霞近，无嫌白日疏。","天晴时见鹤，池浅尚通鱼。","赖有知心者，过门亦下车。"]},{"t":"十二月五日，雪，答傅渊道","f":"曲","c":["蓟门腊月雪，初似楚南寒。","祇悦年光盛，宁愁旅宿单？","濡毫思谢朓，掩户忆袁安。","昨暮瀛洲署，应当策马看。"]},{"t":"王继学晚过舍下翌日惠诗两章用韵答贶","f":"曲","c":["平生病太史，浅陋愧曹邦。","自足封函谷，聊须垒受降。","黄钟知和寡，白璧动成双。","天外谁招得，清风满八窗。"]},{"t":"王继学晚过舍下，翌日，惠诗两章，用韵答贶 其二","f":"曲","c":["客居惟所适，不是远时人。","闻喜池台僻，来依第宅新。","月涵钟警夕，风引酿生春。","颇得过从乐，相看莫厌频。"]},{"t":"和二章已而徵者适至戏用韵为再叠云","f":"曲","c":["久客岁云暮，悠悠念异邦。","病因诗暂愈，愁为酒先降。","屋隐疏篁半，城依老树双。","晨朝有好鸟，命我隔东窗。"]},{"t":"和二章已，而征者适至，戏用韵为再叠云 其二","f":"曲","c":["颇怪君家使，征求太迫人。","从知心匠苦，况复物华新。","辍梦天开夜，思归水墅春。","纵无青玉案，寄赠莫辞频。"]},{"t":"用韵报李宗明二首 其一","f":"曲","c":["李侯持重器，隐若一雄邦。","敌至婴城守，威行走传降。","薰弦须和五，古剑肯埋双。","见说研朱地，车声绕碧窗。"]},{"t":"用韵报李宗明二首 其二","f":"曲","c":["古来辇毂下，不畜隐沦人。","况有龙门旧，宁无兽锦新？","江山政如画，松柏自宜春。","可是东城曲？","过从步屧频。"]},{"t":"送张月梅","f":"曲","c":["卧病空山里，君来起素秋。","叩门惊远字，扶杖揖清流。","潦倒炊粱客，从容树橘侯。","偶同萤夜语，行李又何州？"]},{"t":"三月二十三日，雨中示诸生","f":"曲","c":["后园僧寺里，闻有蜀葵花。","好趁今朝雨，移来向我家。","编篱虽待菊，引蔓盍藏瓜？","总在经营力，秋成莫浪夸。"]},{"t":"赠别李太祝还广平省亲","f":"曲","c":["六祝周遗礼，千官汉盛仪。","声名无此达，少壮任君为。","孤戍程虽迫，萱堂拜恐迟。","都门四月别，愁杀万黄鹂。"]},{"t":"赠答吴二奉礼","f":"曲","c":["新诗走风雨，感谢老兵来。","药圃昏长树，柴门静古苔。","妒晴鸠狎唤，怯冷燕频回。","解说销愁事，何由断酒杯？"]},{"t":"登南城楼","f":"曲","c":["楼倚晴空外，登临延赏心。","微风孤雁过，落日万蝉吟。","客路侵齐树，乡愁接楚砧。","为询宫外筑，流水似哀琴。"]},{"t":"寒食后百丈山夜坐","f":"曲","c":["已新寒食火，更近暮天钟。","花片随风减，柴扉带月重。","以閒酬宦达，将病抵心慵。","本不从耕稼，临江愧老农。"]},{"t":"月出","f":"曲","c":["清枫起夕阴，明月出高岑。","达识衰荣理，深齐去住心。","夏虫先振砌，昏鹤未休林。","不有询奇字，应谁载酒寻？"]},{"t":"山寿生日","f":"曲","c":["见尔开三岁，堪余谢一官。","常怜为子重，更念报君难。","曷曰胜裘马？","于天学凤鸾。","终当慰老眼，空阔万人看。"]},{"t":"九月二十八日，济上作","f":"曲","c":["昨日立冬雨，内河中夜雷。","晨兴犹未定，震惧忽如摧。","衰柳并寒在，早梅何处开？","饥年方禁酿，不饮称无才。"]},{"t":"快阁延望","f":"曲","c":["快阁延江望，清尊息坐弹。","风鸡犹戒曙，云雁每辞寒。","莫使晨歌废，聊思饱食安。","百年会有故，终不愧儒冠。"]},{"t":"题秋山图","f":"曲","c":["我爱秋景好，自缘秋气清。","江空石露骨，木落风无声。","偶向画中见，犹如云外行。","祗疑豺与虎，无地得纵横。"]},{"t":"正月三日，大雪","f":"曲","c":["大雪生何处，飞来应早春。","清寒微着物，光霁亦宜人。","日月双吟鬓，乾坤独病身。","浊醪差可近，祇为有天真。"]},{"t":"康大监善庆堂","f":"曲","c":["大府声名旧，京华有此堂。","栋梁深尽制，花竹净分行。","世美尤当济，身名赖必扬。","自公常退食，把易细焚香。"]},{"t":"九日，和危太朴见贻","f":"曲","c":["年年江海上，饮菊对重阳。","又复兹辰至，都无少日狂。","遥峰栖户碧，败叶拥池黄。","只有长生事，于今堕渺茫。"]},{"t":"九日，简危太朴","f":"曲","c":["疾风吹细雨，忽忽过阴崖。","久喜江山静，新增节序佳。","秋声连迥野，暝色起高斋。","自得论文侣，中年有好怀。"]},{"t":"夏夜，登后亭","f":"曲","c":["县酌群山置，亭因古堞安。","幸无多检校，于以小盘桓。","潦倒渊明酿，凄凉子贱弹。","杖藜听夜鹤，世虑苦无端。"]},{"t":"湖上值雪","f":"曲","c":["农事伤下泽，官曹限穷年。","崎岖尽所历，缱绻何由宣？","窗明变松雪，室冷延山烟。","少岁守恬淡，未敢轻弃捐。"]},{"t":"贵州","f":"曲","c":["离思久不惬，幽情晚旋添。","天宜明月独，山与宿云兼。","蛩语通支柱，蛛丝映卷帘。","若无光霁在，何以破朱炎。"]},{"t":"发横浦之永淳县","f":"曲","c":["急桨开晨涨，孤尊已夕阳。","水光排峡静，洲势背城长。","太史才无敌，将军义不忘。","感伤今岁月，淹泊愧沧浪。"]},{"t":"寄刘传之","f":"曲","c":["故人去南海，已度百花时。","万事须重到，孤舟何太迟！","云迷帝子渚，月过伏波祠。","幕府文书省，来须慰我思。"]},{"t":"晚至沙塘","f":"曲","c":["风雨病屡涉，烟山知几重？","平湖番近服，大邑艾遗封。","受粟常惭吏，看花正闵农。","周原已遍度，明旦复何从？"]},{"t":"三月十一日，遣家人还舍奉侍，值雨。十四日，值晴作","f":"曲","c":["具船闻解缆，想象系朝昏。","到日初收雨，沿流定达村。","初生南涧藻，好近北堂萱。","载感飘零意，清江是故园。"]},{"t":"古木","f":"曲","c":["谁擘苍烟破，依稀露老龙。","偶违风雨会，遂感雪霜踪。","飞动关元气，沉潜见物宗。","何阶韦偃伎，千岁此相逢。"]},{"t":"赠别韩德卿归安西，因候萧司成","f":"曲","c":["十年关陇道，文学老貂裘。","久别重相见，相看更自愁。","早膺朱绂宠，暂为白云留。","寄谢萧夫子，岩栖向几秋？"]},{"t":"寄宿维扬驿，寄怀王仪伯","f":"曲","c":["水墅见明月，适随归桌圆。","故人在郡国，今夜隔风烟。","何日征河内？","常时诵颍川。","经过因念此，书信赖流传。"]},{"t":"题靖节征士归来图","f":"曲","c":["维公楚杞梓，作令晋衣冠。","得志但恐暮，济时非所难。","古今弦韵寡，岁月酒杯宽。","渺渺山中去，深深画里看。"]},{"t":"题吴生雨吟图还寄清江皮野","f":"曲","c":["江雨四时昏，故人家远村。","如何一见面，还又两忘言。","老树经鲛泪，空花断雁魂。","由来前日画，妙手出吴门。"]},{"t":"东斋秋雨后花药具有生意","f":"曲","c":["田园虽尚远，未肯效凄凉。","药就篱成蔓，花因径作行。","岂惟延晚趣，自足信年芳。","颇敬邻人妇，驱鸡不过墙。"]},{"t":"病中","f":"曲","c":["世故只如此，予生今若何？","不忧新食少，但喜好诗多。","野鹤来濠上，山猿落涧阿。","平时朝夕者，经岁不吾过。"]},{"t":"哀文集贤，时奉使南海道弃","f":"曲","c":["瘴海距天关，道逾千万山。","空传灵雨送，不见使星还。","旌旆青枫暗，楼台白水闲。","郡人惟我最，远客泪潺潺。"]},{"t":"赠葛推官","f":"曲","c":["五罚从容至，群生阨塞多。","但无为已甚，勿问达如何。","早读于公戒，终传召父歌。","故人风雨节，为我数经过。"]},{"t":"张别驾山居产玉芝","f":"曲","c":["高秋别驾宅，异草吐奇芬。","为尔掇白雪，服之乘紫云。","但恐仙灵物，长遮虎豹群。","待弃人间事，先报赤松君。"]},{"t":"赠别李仝","f":"曲","c":["士以才名重，君犹梗概先。","间关百年道，浩荡九春天。","不为歌弹铗，还寻与酒钱。","古来自如此，相问涧西田。"]},{"t":"奉寄高邮李使君","f":"曲","c":["题诗报使君，春远楚江濆。","剩水鼋鼍窟，低空雁鹜群。","朱幡临野日，翠袖绕山云。","早晚金鸾召，风流许细分。"]},{"t":"晚兴","f":"曲","c":["古寺山重掩，平田县对门。","鹧鸪藏白昼，蟋蟀破黄昏。","贝贾多通市，藷偷每近村。","殷勤省风俗，慷慨动心魂。"]},{"t":"澄迈县，有苏内翰所题通潮阁，在海上","f":"曲","c":["候馆驻征骑，西风独夜清。","开门闻叶落，倚杖看潮生。","有礼齐蛮俗，无歌学楚声。","凄凉苏季子，行处足高名。"]},{"t":"将行值暴涨","f":"曲","c":["雨发蛮山涨，来从五指原。","风桥初没马，到县已侵门。","甚欲乘槎去，还思弃佩言。","轻身犯南斗，信有北溟鲲。"]},{"t":"咏荔子","f":"曲","c":["思归江路永，荔子几时丹？","祇念违亲久，何愁待尔难？","园林有专美，霜雪莫留寒。","记得珠崖道，长吟立马看。"]},{"t":"细雨","f":"曲","c":["细雨沾墙竹，轻风发槛桃。","幕分流水静，楼抗远山高。","但长琴书癖，宁知案牍劳？","趋朝未觉懒，兴味属吾曹。"]},{"t":"和谢梁内舍过访","f":"曲","c":["承闻招隐处，独占万山清。","乍见心如醉，多忧眼遽明。","荐遗唐四岳，道付鲁诸生。","欲理寻幽事，惟妨夜鹤鸣。"]},{"t":"河口","f":"曲","c":["神女大河口，逸人阴洞中。","船鸣谷雨浪，门掩荔枝风。","鹤鹳行相背，乌鸦宿自同。","为于百年内，试问鹿皮翁。"]},{"t":"晨至西郭池亭，见新荷，有感时物而作","f":"曲","c":["虚亭结构美，驿路带垣斜。","山芗含晚翠，池响集春蛙。","官荷已偃盖，僧蔬欲架花。","俯仰宾从役，孰与测幽遐？"]},{"t":"三山对月，怀山寿","f":"曲","c":["豫章千里月，渐解向天高。","安得山儿慧？","能知海客劳。","榕城咽韵鼓，竹馆净香醪。","何日书帷下？","清辉映凤毛。"]},{"t":"晚上南山观烧","f":"曲","c":["渡口向寥阒，夕晖生翠屏。","随风初绕电，翳雾忽如星。","鸟兽蒸宜遁，柴扉照不扃。","闽都春始过，雨洗合重青。"]},{"t":"庭草","f":"曲","c":["为爱庭中草，经春坐不除。","澄心皆净域，履道即安居。","海气含楼阁，年光映簿书。","昔人伤废事，作吏竟何如？"]},{"t":"昨游","f":"曲","c":["昨游居士涧，春入羽人丘。","面面山相引，年年水自流。","乾坤双蜡屐，江海一渔舟。","知我能来否？","啼莺去复留。"]},{"t":"雪观雨后对薜老峰","f":"曲","c":["高阁飞雨过，新凉连海隅。","竹溪鱼板集，松寺鹤巢孤。","吏隐非兼得，登临适自娱。","盛名苏季子，犹是老征夫。"]},{"t":"京下思归","f":"曲","c":["黄落蓟门秋，飘飘在远游。","不眠闻戍鼓，多病忆归舟。","甘雨从昏过，繁星达曙流。","乡逢徐孺子，万口薄南州。"]},{"t":"延平西峡","f":"曲","c":["巨浪劈山倾，孤舟与浪争。","逆飞天地肃，捷出鬼神惊。","至险追前载，终身愿太平。","不然忠孝理，值此各何情？"]},{"t":"次韵曾五判官","f":"曲","c":["磊落将军石，周游太史迁。","世人宁见尔？","我辈故超然。","胆急投豺地，神销过鹄天。","祇今谁可语？","壮志必同年。"]},{"t":"赠颠叟僧别二首 其一","f":"曲","c":["问子家何在，名山越树春。","来游万里道，去作五台宾。","乞食宁忘禄？","行歌若有神。","曾逢陆脩静，招入社中人。"]},{"t":"赠颠叟僧别二首 其二","f":"曲","c":["未是真颠者，能颠故有余。","试留吴郡草，为报揭阳书。","带日辞铜马，投云听木鱼。","南归定何日？","白象守林庐。"]},{"t":"送施处士还东溪","f":"曲","c":["东溪子故物，归去一身轻。","树晓雏莺坐，沙晴乳鹿行。","乘舟不尽兴，罢钓忽忘名。","忆我南山下，蘼芜绕舍生。"]},{"t":"期出东郊不果却率便河闸桥诣张道人庵寻故旧作","f":"曲","c":["却欲东郊去，还寻北渚来。","江翻垂木动，风过杂花回。","馗道迷朱毂，虚空见紫台。","世氛浑不奈，忆得是蓬莱。"]},{"t":"阅友人壁间咏，有怀旧游","f":"曲","c":["漫说经行处，云边第二春。","石林投倦客，画壁跋高人。","迹与风鹏转，心兼野鹤亲。","平生许玄度，自比白头新。"]},{"t":"和李溉之园居杂咏八首 其一","f":"曲","c":["书剑上青霄，乡关雨雪遥。","年华侵水竹，客思堕山苗。","会想商岩绮，将从郑里桥。","文词诚小伎，祗比俗情饶。"]},{"t":"和李溉之园居杂咏八首 其二","f":"曲","c":["岂是幽栖地，飞腾亦未量。","城根分鼠壤，池面合鱼梁。","名久喧郎署，歌时感女桑。","畏卿音调苦，畴复贵相忘。"]},{"t":"和李溉之园居杂咏八首 其三","f":"曲","c":["圃色依帘障，天光切户庭。","草生连夜雨，花落遍池星。","未遂翔寥廓，真堪托晦冥。","逢时须紫燕，得意拂青萍。"]},{"t":"和李溉之园居杂咏八首 其四","f":"曲","c":["亦欲依家耳，衡门斗极边。","乡心征化鹤，宦径跕飞鸢。","白日抛书送，青山拂槛延。","风流自无已，忆上五湖船。"]},{"t":"和李溉之园居杂咏八首 其五","f":"曲","c":["都无京国意，满眼旧生涯。","壁隐崆峒木，毡蒙婀娜花。","善邻垣故辟，爱客酒能赊。","皦皦荒途子，音期只尔遐。"]},{"t":"和李溉之园居杂咏八首 其六","f":"曲","c":["偶从耕凿事，便有古人风。","井泻千畦碧，林然独杏红。","世情何近远？","宦秩自卑崇。","任道流行意，雩坛或与同。"]},{"t":"和李溉之园居杂咏八首 其七","f":"曲","c":["磊落人间士，名成定不虚。","愿陈元有策，交荐可无书？","莫遣从师苦，因将作吏疏。","吾徒岂念此？","愧尽马相如。"]},{"t":"和李溉之园居杂咏八首 其八","f":"曲","c":["丹柰花初结，朱樱子半成。","寝兴因物变，筋力与年增。","燕拂承尘去，蜂随曳杖行。","玉泉几千仞，好在翠如倾。"]},{"t":"重过太傅忠宪王园林","f":"曲","c":["一代王章宠，于今胜地非。","野池花自发，春日燕争飞。","坐送笙歌密，衙迎剑佩稀。","颇萦游子骑，脩景澹忘归。"]},{"t":"登觉山寺","f":"曲","c":["远见浮图顶，逡巡及寺门。","此行如有待，何地更无喧？","山背斜阳恶，泉侵落叶浑。","沉沉委台殿，多是赐金幡。"]},{"t":"种瓠二首 其一","f":"曲","c":["岂是阶庭物，支离亦自奇。","已殊凡草蔓，缀得好花枝。","带雨宁无实，凌霄必有为。","啾啾群鸟雀，从汝踏多时。"]},{"t":"种瓠二首 其二","f":"曲","c":["嘉瓠吾所爱，孤高更可人。","不虚种植意，终系发生神。","有叶诚藏用，无容岂识真。","明年应见汝，众子亦轮囷。"]},{"t":"六月菊","f":"曲","c":["萧然故可爱，况在五侯家。","未到三秋节，先开万点花。","风霜宁未熟？","岁月自云赊。","惭愧青松干，昂藏照岛沙。"]},{"t":"戏简孔太祝","f":"曲","c":["人间最好日，祇在菊花前。","颇怪来今雨，相看语后天。","门阶销俗客，冠佩切飞仙。","愿约秋风住，长年泛酒船。"]},{"t":"送刘修撰赴湖南提举任","f":"曲","c":["久淹词馆寄，新奉玺书还。","白发临漳水，青云动楚山。","文称一道重，政类百司闲。","设有湘南骑，因之解别颜。"]},{"t":"寄李彦谦御史","f":"曲","c":["古燕城下路，柳树落西枝。","每到重来处，长怜欲别时。","鹘飞平照急，鸥集远烟迟。","此去秦州什，应须寄我知。"]},{"t":"寒斋对雨书怀","f":"曲","c":["冬暖久不雪，天分雨破颜。","依稀才洒户，惨淡欲连山。","垣屋重重密，壶尊独独悭。","焉知魏阙士？","隐与吏相关。"]},{"t":"客至","f":"曲","c":["客至冠缨好，殊非旧友生。","晓晴霜太重，冬暖日偏明。","觉我肌肤弱，兴言感慨并。","子云工赋述，切莫论公卿。"]},{"t":"咏梅，和陈城南","f":"曲","c":["我亦吴头客，年年念远梅。","孤根元自植，冷蕊为谁开？","因睹城南咏，深思岭表来。","北人盆里看，应不近苍苔。"]},{"t":"守岁咏怀，次韵","f":"曲","c":["大年在今夕，旅爵记前除。","时序无闲事，江湖少定居。","烛花分坐委，漏箭落城疏。","底复穷庐叹，人生各有初。"]},{"t":"送贡仲实还江西","f":"曲","c":["送行何太频，日日见行人。","又复风霜节，相违旅病身。","浮名非甚急，远意独难信。","念子关劳苦，题诗莫待春。"]},{"t":"题友人山居","f":"曲","c":["游居展静好，尽日有高情。","竹下流泉过，花间时鸟鸣。","因人问药裹，要我罢琴迎。","本自无知者，山林颇近名。"]},{"t":"林尊师招不果，就别","f":"曲","c":["甚欲抠衣去，仍烦折简呼。","竟孤林下约，还想市间壶。","野馆侵浓树，春波乱嫩芜。","看云解榻意，秋露近玄都。"]},{"t":"野望","f":"曲","c":["思远卑栖地，凭高独望辰。","峡云低度晚，野水净含春。","语鹤关梁迥，归鸿岁月新。","不堪回首处，横笛倍伤神。"]},{"t":"游招提","f":"曲","c":["胜地相从日，应无俗客踪。","春花浓夹骑，昼树静藏钟。","妙理端深得，佳游亦漫逢。","怜渠丝与竹，舫上见西峰。"]},{"t":"送白湛作尉金溪","f":"曲","c":["离思已无极，尊前况夕昏。","闭门六月雨，行李万重云。","远禄年虽壮，名家代不群。","县人迎主簿，应似大浮君。"]},{"t":"卢师东谷怀城中诸友","f":"曲","c":["契阔遽如许，淹留空复情。","天遥一鹤上，山合百虫鸣。","异俗嗟何适，冥栖得此生。","平居二三子，今夜隔重城。"]},{"t":"送邓庆长衍从宦吴中","f":"曲","c":["闻说吴中郡，青山万叠开。","云霞通井邑，水木映楼台。","子去嗟何恨！","吾生念却回。","辛勤官下养，书记合频来。"]},{"t":"正月三日，海子泛舟","f":"曲","c":["晓日明如茜，春波凝不流。","浴凫浮断梗，过雁折危楼。","颇敬吴儿狎，何伤楚客囚？","沙边萦小楫，初慰玉京游。"]},{"t":"送云知事赴余杭","f":"曲","c":["一舸发春濑，涓涓沙鹭明。","官烦南郡佐，礼重北城迎。","海浦潮声暗，山城日气清。","宗卿怀故掾，蚤晚荐高名。"]},{"t":"暑夕","f":"曲","c":["烦暑不能寐，望乡忆宵征。","开门海月白，高枕林风清。","不饮畏投辖，将歌思濯缨。","谁家横短笛？","吹尽楚关情。"]},{"t":"七夕词","f":"曲","c":["天上新秋节，人间巧夕祠。","不成儿女笑，空负岁时悲。","璧月当轩堕，银河带阙垂。","低头愧乌鹊，宁为绕南枝？"]},{"t":"和巽初得子","f":"曲","c":["喜事平安使，家书远见贻。","正愁行路子，新得称家儿。","白璧无劳羡，青云日与期。","庭阶人事意，眼冷念含饴。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其一","f":"曲","c":["盛君江海士，直气轧霄峥。","翻为诗书苦，焉知印绶荣？","度辽曾万里，走越更千城。","便是来难得，乡关近慰情。"]},{"t":"离席合赋赠南剑教授盛复之之官","f":"曲","c":["首路向朱夏，出关犹到官。","麦收风涨暑，梅熟雨留寒。","气候随方异，才名自古难。","岂容贤若尔，教授老江干。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其三","f":"曲","c":["江浦见黄鹂，石榴花满枝。","欲攀犹屡惜，已去复何疑？","蚤畏红英乱，还当绛帐移。","驿程动易隔，留待寄相思。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其四","f":"曲","c":["娟娟沙尾鹤，毛羽映江鲜。","去住长如此，飞鸣岂偶然？","仙家应汗漫，侯判莫留连。","忆得东门事，须君正壮年。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其五","f":"曲","c":["闽南荔子熟，问客倘能来。","暂为诸生屈，宁伤独茂才？","云飞绝寒落，雨过行平台。","赋就新诗别，扁舟且莫催。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其六","f":"曲","c":["昔向辽东郡，长歌觅管宁。","此行无赠策，故事有谈经。","豆实登朱荔，虹光照紫萍。","龟山文物在，未用叹凋零。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其七","f":"曲","c":["跃马问入郭，解龟听报衙。","江沙侵细竹，墙蔓覆疏花。","政不离书阁，吟应上钓槎。","有怀当皓月，玉署听啼鸦。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其八","f":"曲","c":["碧草津头郡，虽偏是胜游。","野人频识剑，稚子亦能舟。","稍定传衣怪，聊资宦秩周。","南来说风物，有待细询求。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其九","f":"曲","c":["杯酒莫停手，路长思八闽。","精灵深狎客，瘴雾簿侵人。","海近渔船集，山空鸟道邻。","来京书一束，赖尔老随身。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首 其十","f":"曲","c":["黄帽催晨发，邮签报旅程。","溯风斜帽举，虚日乱弦鸣。","异俗从谁变？","真才不自成。","倘于高第内，岁久得欧生。"]},{"t":"奉寄淮东宪孔知事二首 其一","f":"曲","c":["日有乌台使，因君问合肥。","熊章官下食，虎略幕中威。","易政听时报，交深念日迟。","知音偕上列，须假绣为衣。"]},{"t":"奉寄淮东宪孔知事二首 其二","f":"曲","c":["昔在东门别，相离数岁星。","一官何委折？","万里独飘零。","楚树春频落，燕云晚自停。","几时淮浦月？","仍与共扬舲。"]},{"t":"遣怀","f":"曲","c":["柳影侵门暗，桃枝亚竹高。","年深诗并进，春在酒争豪。","吏隐嗟何择，行藏信所遭。","斯文如未丧，端合付吾曹。"]},{"t":"过西芹","f":"曲","c":["路隐岩崖迥，桥通屋舍重。","鸟啼黄叶寺，泉注白云峰。","市贩赊柑柿，畲耕间竹松。","行人报山郡，失喜问萍踪。"]},{"t":"延平江阁","f":"曲","c":["山势包平险，津流合众源。","讵知从事剑？","不类大夫魂。","光彩潜犹见，精忠死尚存。","幽灵如可问，吾意岂忘言？"]},{"t":"奉同廉访使君洎寮友游爱同寺","f":"曲","c":["闽粤古城东，千岩半梵宫。","冒寒寻水石，尽日倚虚空。","钟鼓何须急？","壶觞亦有终。","翩翩北海寺，碑版翠无穷。"]},{"t":"寄武夷杜征君","f":"曲","c":["洞居清隐士，时接武夷君。","旆影岩前见，山香石上闻。","不为圭组累，焉有市朝分？","暂得同麋鹿，终朝试与群。"]},{"t":"正月节日，上宝历寺行礼，退述事","f":"曲","c":["朝参不见承明庐，梦想三更尚是初。","窅窅重山遮列炬，泠泠流水逐行车。","柴关响接群僧磬，草泽心驰上帝居。","圣寿延长天广大，固应涵养及樵渔。"]},{"t":"晚经皮使君江居不见，赋简二首 其一","f":"曲","c":["使君直节更无双，又拜浓恩出海邦。","绝域朱幡兼皂盖，名园碧树倚清江。","山明残雪当松坞，岸断斜晖射石矼。","愧杀会稽王子敬，过门未遂此心降。"]},{"t":"晚经皮使君江居不见，赋简二首 其二","f":"曲","c":["忆得去年寻药圃，甚怜此日负花时。","拿舟况说看灯及，叩阁应烦把酒思。","浩浩古今奚我独？","悠悠江海是吾师。","西墙倘遂残年愿，来往风流或可期。"]},{"t":"松湖渡亭子夕眺，怀西山朱炼师","f":"曲","c":["不解无愁祇遣愁，凭高试看水东流。","一天鹭影摩仙阙，两岸蝉声送客舟。","肯信先生居锦里，不将夫子敬丹丘。","如闻旧按蓬莱节，松下时时省钓游。"]},{"t":"题阮茂材诗卷","f":"曲","c":["炳炳人间阮嗣宗，能诗飞动每愁侬。","九霄丽日开鸣凤，六月深渊起卧龙。","前辈文章工祖述，后生师友系遭逢。","一编欲返明珠寄，宝匣看君不敢封。"]},{"t":"赠熊处士还山房","f":"曲","c":["尚书旧隐在匡庐，乱后传闻宅已墟。","祠宇祇今谁荐鞠，鬼神犹自护遗书。","石泉宛宛输池细，川树茫茫映日疏。","不识海昏熊处士，冥栖消息近何如。"]},{"t":"赠傅汝砺北游","f":"曲","c":["十年身不到瀛洲，江上逢君又素秋。","行李祇今何处在？","看花须及俊年游。","沧波远去浮三坞，白日高悬照九州。","大旱若将敷说命，贤良记取旧弓裘。"]},{"t":"赠熊文学","f":"曲","c":["江东阀阅冠群伦，多士如君复几人？","庠序弦歌时雨润，庙堂俎豆德风淳。","尝因矫举思鸿鹄，何幸升平睹凤麟？","黄叶蓟门寒色早，伫看天上紫泥新。"]},{"t":"送马掾迁湖南","f":"曲","c":["闻君暂与故交违，去逐西风落叶飞。","看剑未成今夕会，拿舟定复几时归。","云开帝子黄陵庙，月过将军赤壁矶。","事业还须各努力，收名即用绣为衣。"]},{"t":"八月二十日晚，试院得雨，次时作","f":"曲","c":["彤廷下诏简贤良，大府新开艺战场。","一道风雷严号令，九霄星斗焕文章。","求材正合隆天爵，发策应当急岁荒。","昨夜雨声传数点，争烧银烛待新凉。"]},{"t":"赠李宣使","f":"曲","c":["故园云卧四三年，府署依然念子贤。","莫为驰驱伤远道，但将忠孝感皇天。","湖南政誉闻争荐，日下丝纶伫近传。","为报津头黄菊蕊，明当照我上江船。"]},{"t":"大明殿退朝","f":"曲","c":["晓星寥落动晴霄，双阙香烟近眼飘。","警跸西来天影近，衣冠北上海光摇。","间因正笏知春漏，忽报箫声押昼朝。","忝后词人虽寡陋，极知圣主体轩尧。"]},{"t":"清宴奉教","f":"曲","c":["日上高城烟雾多，玉箫前路散鸣珂。","开筵迥出清川上，对酒其如绿树何！","南极有星朝玉阙，中天佳气掖銮坡。","长年不负经纶寄，愿及昌时养太和。"]},{"t":"四月十六日诣东华门奉迎香舆","f":"曲","c":["天香晓报出宫城，已办隅头合乐迎。","黄鸟低斜冲队过，紫骝疏荡著班行。","百王盛祀无遗典，万乘深居有至情。","失喜快传汤沐赐，礼官识姓未知名。"]},{"t":"礼成，还斋宫","f":"曲","c":["九重雅有舜仪刑，犹遣精神接杳冥。","朱户瞻星扶帝座，清天分月下斋庭。","周旋宛若羹墙见，荐祼遥闻黍稷馨。","归舍何人发新咏？","郤兼鸣佩两边听。"]},{"t":"至夏庄怀平坡旧游","f":"曲","c":["平坡谷前桃杏花，年时著屐到君家。","祇今可买惟村酒，无复能来试石茶。","帘幕高高通紫燕，溪流款款伏青蛇。","同游昨有虞公子，却为卢郎得浪誇。"]},{"t":"赠王主事如上都","f":"曲","c":["天官幕府盛诸卿，又从皇舆赴上京。","邂逅同为远道客，比邻犹有故乡情。","秋风响近弹琴峡，夜月悬当直斗城。","须记今年上马日，菖蒲杯里试长生。"]},{"t":"长春瓢，奉同夏、杨二编修为九宫道人作","f":"曲","c":["妙绝新亭九宫下，似杯非杓异山罍。","昔从树杪泠风去，今向天边洒雨来。","芥子量应容宇宙，黍珠境不外楼台。","从师斟酌行藏事，小阅冥灵一万回。"]},{"t":"送梁知事之婺州","f":"曲","c":["皓月青云若个边，送行恨不共吴船。","新官浙下皆名郡，旧宅山东有赐田。","礼乐固应张盛代，簿书勿用叹流年。","经时不见曹员外，今日因君重惘然。"]},{"t":"追和卢修撰张平章园亭观花饮","f":"曲","c":["白藕花边香已秋，西郊风物野亭幽。","未须短杖扶持病，且遣孤尊断送愁。","紫气近连飞凤阙，青山遥隔钓鱼舟。","胜游纵在招要外，犹解因诗颂醉侯。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其一","f":"曲","c":["古蓟城边白露零，秋声不任旅人听。","差差乳燕朝辞舍，呖呖高鸿暮过庭。","以病酬閒翻自恶，将愁抵醉祇难醒。","何人解拟匡庐赋，千仞冈头瀑泻瓴。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其二","f":"曲","c":["将身跳出市间壶，美贾由来不用沽。","大地骑鹏须共化，中宵上鸐倩谁扶？","庶几未老投簪去，尚可长生折简呼。","此辈终非尘土物，明朝种橘学诸苏。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其三","f":"曲","c":["生也无涯死有涯，抛书几拟问南华。","要知立志非多事，但使成言自一家。","寒树接天霜映鹘，湿芜满地雨生蛙。","相过傥遂携尊酒，检按墙东野菊花。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其四","f":"曲","c":["迥无江左管夷吾，谁复能称晋宋书。","运本关天聊尔耳，力能盖世复奚欤。","百年草草云龙地，四海悠悠法象庐。","曾向钟山酹芳草，至今心死及菑畬。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其五","f":"曲","c":["流落移家白帝都，低头愧尽马相如。","题桥一字终何益，卖赋千金竟或无。","风月长留前辈咏，尘沙满载古人书。","此身泛寄空江上，已异当时旧鬓须。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其六","f":"曲","c":["浮世有由虚尺寸，明时无伎答涓埃。","偶随青琐须高步，欲缀丹书甚寡才。","断壁云过溪笛逝，虚林雨映寺钟来。","几年闲却持螯手？","强为清秋送酒杯。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其七","f":"曲","c":["潘公墙角树连庭，曾是笙簧昼夜听。","门巷祇今埋粪壤，轮蹄自昔走雷霆。","长因午睡思茶灶，却为朝吟款竹扃。","若续济南名士录，莫令憔悴鹊湖亭。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其八","f":"曲","c":["李侯高朗若空晴，议论诗书满腹撑。","期接仙舟应少便，偶分宫砚亦多情。","蛮荒异俗中年历，河汉频秋向夕倾。","此去暂烦南郡守，旗旄勿用野人惊。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其九","f":"曲","c":["浦君高价本璠玙，多幸蒹葭得所于。","学道初轻千里骥，收功直到九州鱼。","诗探饭颗尤难测，赋拟兰陵定不虚。","月月西垣更夜直，还应共我惜居诸。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首 其十","f":"曲","c":["秋入江山锦绣开，白云红叶尽诗才。","句成底用三年得，槎在应须八月回。","自是每为浮客累，非关不受故人催。","凭将寄语词林老，风雨重阳又近来。"]},{"t":"送白无咎太守之郡","f":"曲","c":["潇洒中书旧省郎，排云曾揽舜衣裳。","一麾况复守名郡，万事不如归故乡。","马首渐违燕阙雨，雁声欲度晋城霜。","汉廷择相皆良吏，早奉潘舆谒建章。"]},{"t":"奉同陈应奉访友人不遇","f":"曲","c":["翰林小暇出西城，京国馀秋晚更明。","鸥度折矶心已熟，马逢危石眼偏生。","疾风稍定楼台色，微照犹含鼓角声。","会合何因得惆怅，潜夫祇愧未潜名。"]},{"t":"夜坐，有怀舍弟在江右，别来凡阅九冬至矣","f":"曲","c":["天边此夜逢冬至，江表频年望客还。","谬戴词林深雨露，却怜棣萼远河山。","周流本已违长策，趋走那堪益厚颜？","何日求田归计定？","一尊松下咏间关。"]},{"t":"寄别倪大同","f":"曲","c":["知君久住玉真坛，日与飞仙弄紫环。","从此便令行地缩，逢谁不说上天难。","鹤边红日浮觞送，马首青山抱檄看。","相好何因不相别，寄诗应到暮云端。"]},{"t":"将赴雷阳送罗提举之任广东","f":"曲","c":["松滋暂泊蓟门船，复指番阳路几千。","茉莉香深和酒露，桄榔叶暗煮盐烟。","齐人旧算无遗策，汉史新藏有剩钱。","莫为遐荒心力怠，珠崖更在海南边。"]},{"t":"休日出郊三首 其一","f":"曲","c":["上方钟鼓昼依稀，出定诸僧绾法衣。","迎客犹能下殿走，访人更有待寻归。","秃鹙近水行仍啄，危燕当梁乳更飞。","自古旅怀烦慰藉，并游万事莫相违。"]},{"t":"休日出郊三首 其二","f":"曲","c":["丞相祠西椰子园，新开湖馆见遥村。","风含碎羽珊珊过，浪涌长干剡剡翻。","止息幸然无鹤爵，去来应或有鹏鹍。","江边柳树晴相倚，祇为行人作断魂。"]},{"t":"休日出郊","f":"曲","c":["歇马高林烟雾开，感今怀古独登台。","迁臣逐客皆前辈，幕长郎官尽上才。","放浪已闻穷九域，飞腾终合近三台。","谢公自有青云屐，且与从容步紫苔。"]},{"t":"寄友人","f":"曲","c":["绣衣行部直南州，幕府英名早岁收。","如此一台兼二妙，令人万里破千愁。","桄榔叶暗潮声暮，薜荔花悬岳影秋。","此去三湘宁久住，近天须应玺书求。"]},{"t":"题燕山佥事彩绣堂","f":"曲","c":["海康城下白云飞，南部观风使者归。","督郡须持直指斧，历阶尚挂老莱衣。","高堂见月思丹檄，远路逢春忆翠微。","赖有胜流词翰在，定随华榜照林扉。"]},{"t":"赠余使君致仕还江东","f":"曲","c":["九华山下女萝丛，使者旌旗发粤中。","昔至本膺丹诏重，今归惟颂白头公。","百年自喜行藏定，千里何当语笑同？","门口侍船应有待，大江西即大江东。"]},{"t":"楚楼镇志曰：汉大将焚船处也，今为文昌县。怀古，奉简邑文学","f":"曲","c":["龙节迢迢去不归，汉家将军建国威。","当时曾见楼橹集，异代空闻尘土飞。","风压春潮吞乱屿，岸分古木转斜晖。","旁人犹解祠神女，何故功臣庙貌稀？"]},{"t":"立春日","f":"曲","c":["今辰春节喜新晴，况是山堂此日成。","畦菜拨余传叶美，径桃留在着花明。","云开葛井蛟龙动，雪尽萧岩鹳鹤鸣。","失喜浪传京邑信，未闻邻舍识高情。"]},{"t":"寄题何处士竹阁","f":"曲","c":["吴汉仙翁丹井西，君家高阁俯清溪。","泠泠修竹莺时到，井井空烟鹳昼啼。","解带欲围苍雪远，敲门待看绿阴齐。","何当试答登临愿？","系马宅前杨柳枝。"]},{"t":"屈原庙前观雨，雨止，渡口观鱼","f":"曲","c":["乍来倏去峰前雨，半落未开沙际花。","春远客怀淹燕雀，年荒民命假鱼虾。","徒闻黄霸能为郡，岂识张骞苦泛槎。","早谓仙人无世虑，山深往往饭胡麻。"]},{"t":"送毛炼师奉祠礼成还京","f":"曲","c":["仙官持节下青冥，海渎严祠卫百灵。","行为治平循禹服，礼从禋祀想虞廷。","东风到处随神雨，南极归来奏寿星。","致福要当宣室问，鹤书先报白云扃。"]},{"t":"鼋潭墋","f":"曲","c":["征夫鱼贯涉秋唇，树底照见石磷磷。","攀缘惟有千古意，摇落独如三月春。","天清过涧猿饮子，日宴噪林鸡警人。","七曲棹歌谁按得？","他年重问墋头津。"]},{"t":"题黄隐君秋江钓月图","f":"曲","c":["旧识先生隐者流，偶因图画想沧洲。","断云满路碧窗晚，明月何年青嶂秋。","世故风尘双短屐，生涯天地一扁舟。","何由白石空矶畔，招得人间万户侯。"]},{"t":"寄上甘肃吴右丞三首 其一","f":"曲","c":["要使唐虞化远覃，玉门关下屈征骖。","多忧总为民心苦，有喜惟闻郡姓甘。","日晚边沙黄浼浼，天晴陇树碧毵毵。","国风不系秦州外，自此西人识召南。"]},{"t":"寄上甘肃吴右丞三首 其二","f":"曲","c":["历数先朝辅弼贤，如公孰可语同年？","二童一马临荒镇，百感千忧倚上天。","深厚已闻鸾诏趣，平安不用雁书传。","别来濯濯春城柳，谁信秋风慰目前？"]},{"t":"寄上甘肃吴右丞","f":"曲","c":["塞上孤鹰白雪毛，塞门风物静萧骚。","黄河西去从天下，泰华东来拔地高。","枸杞莫将如薏苡，醍醐足饮胜蒲萄。","遥瞻圭衮还朝日，正属江湖心绪劳。"]},{"t":"郭茂才要饮舍下，忽报董中丞灵柩自上都至，出城迎之，遂负此约，戏题奉谢","f":"曲","c":["相期把酒对秋晖，忽报中丞旅榇归。","遂逐城东朝骑发，遥怜江口夕鸿飞。","陶潜宅隐波吞石，谢傅山寒雨打扉。","人事虽殊风物在，笑谈岂可眼中稀？"]},{"t":"九月十九日京东门与董右军诸公别至通州还寄在京朋游","f":"曲","c":["临分强颜作笑言，上马恸哭投烟村。","十年总仗旧交力，万里独怀明主恩。","南极下头星象少，东风近便柳梅繁。","时人祗怪丹砂令，曾以虚名细讨论。"]},{"t":"山斋","f":"曲","c":["山斋朝雨竹光匀，茶灶催添石火新。","对语黄鹂真不俗，飞来白鹭净无邻。","辞荣岂敢要时论，赏静犹应愧古人。","报道林河春涨起，少须重理旧丝纶。"]},{"t":"山斋二首 其二","f":"曲","c":["幽栖自是少经过，药裹书囊奈癖何！","仙井朝来云气重，洞房夜尽雨声多。","江湖耆旧深思忆，台馆风威尚琢磨。","自尔索居增固陋，负苓谁问首阳阿？"]},{"t":"送陈从事归江东二首 其一","f":"曲","c":["长年京下送人归，初及扁舟指翠微。","岂意遂闻鸿鹄操？","却须同制芰荷衣。","清江碧树重重见，紫燕黄鹂处处飞。","如此交游二三辈，何因中岁每相违？"]},{"t":"送陈从事归江东二首 其二","f":"曲","c":["吴侬呼剑每通神，铸作由来极苦辛。","天下纵无增价士，夜中须有识光人。","即今况蹑青云地，何日重翻紫陌尘？","令弟两街清显甚，定应携手接星辰。"]},{"t":"傅之经历谒告还湘中，未语别而宵征。翌日，与僚友追送生居亭中二首 其一","f":"曲","c":["美人归思落沧波，昨者论心肯重过。","寒尽极知春意在，夜深无奈月明何。","海隅虽暂违霜幕，天上应须接玉珂。","如此才贤移病去，瘴烟端的为谁多。"]},{"t":"傅之经历谒告还湘中，未语别而宵征。翌日，与僚友追送生居亭中二首 其二","f":"曲","c":["北风尽日破南溟，行路经年倚寿星。","子自全家依翠岳，我犹万里隔青冥。","山田鹿下投书去，水馆猿啼却坐听。","王事驰驱知有素，何由重见此邮亭。"]},{"t":"十月九日诣天光门上进三朝实录","f":"曲","c":["仪鸾簇仗满云端，玉钥初开众乐攒。","三后龙光周典册，群臣鹄立汉衣冠。","炉香著日浮晴霭，宫树斑霜试晓寒。","千骑前头都不避，祇传学士拜金銮。"]},{"t":"画马","f":"曲","c":["一自房星下渥洼，龙媒多在玉皇家。","赤毛洒血微生汗，黑晕团云整作花。","不待老能知失道，固应来是涉流沙。","如今岂少真神骏，犹有丹青纸上誇。"]},{"t":"石氏寿母","f":"曲","c":["鹤发西风尚健身，彩衣天上四麒麟。","尔门皆可二千石，此母何妨五百春？","露下齐山红树晓，雨生滦浦绿波匀。","胜筵偶睹诸贤咏，尽敬东州学士醇。"]},{"t":"归来","f":"曲","c":["十载归来问草堂，入门喜见葛山苍。","慈亲已慰占乌鹊，稚子行堪咏凤凰。","新理园池几创物，小移松柏且分行。","卜居未是居难卜，为恐傍人议楚狂。"]},{"t":"和柳提学赠危太朴","f":"曲","c":["伐木丁丁秋满山，诗筒忽到与开颜。","当时有客谙花洞，此地经年上竹关。","绝域尚怀身倚剑，深居曾梦手持环。","文章政类龙多变，识察能通豹几斑？"]},{"t":"题新喻吴氏浩然堂遗事","f":"曲","c":["钓矶西畔问宜州，回首空山又数秋？","曾见龙蛇飞败壁，每疑鱼鸟逐扁舟。","风云一变衣冠地，城郭重来水石幽。","传得眉山遗记在，吴家子弟更风流。"]},{"t":"过邻人园林","f":"曲","c":["隐者园林昼不哗，冠山楼阁护青霞。","平安日上琅玕竹，富贵春行锦绣花。","高鸟时排朱槛过，远溪正带白云斜。","江城只解听丝管，何处能来玉女车？"]},{"t":"金凤","f":"曲","c":["金凤阶前只漫生，移栽行列甚方平。","新来两本当轩出，各吐幽花照眼明。","夏雨要将苏众槁，朝阳端已瑞先鸣。","勿云小草精神短，每论韶箫记尔名。"]},{"t":"赠杨茂才","f":"曲","c":["西风淅淅风雨生，南塘萧萧楼观清。","玄蝉抱树一时息，老鹤怀山终夜鸣。","放形海岳等云水，托好音书犹弟兄。","未知此别会何日？","为子商歌无限情。"]},{"t":"赠王文学","f":"曲","c":["法乐洞天曾一游，君家闻在水西头。","石潭密映藤萝月，山叶深藏虎豹秋。","岂意吴城祠下路？","共寻扬子岸边舟。","胸中富有天官学，莫为东南久滞留。"]},{"t":"到京之七日，亲祀礼成，闻喜有作，简曹奉常","f":"曲","c":["南征被命过柴荆，瘴土归来湿病婴。","行拨烟霞归上界，卧听风雪打长更。","侍祠想重鸣珂密，出次知先警鼓清。","拂晓斋宫闻好语：谁人不贺泰阶平？"]},{"t":"辛酉岁元日","f":"曲","c":["西山千仞郁崔嵬，山下楼台紫翠开。","玉帛会同来万国，玑衡悬运属三台。","尝闻海客谈金鼎，更见祠官进玉杯。","惭愧词臣今白首，久无赋颂献蓬莱。"]},{"t":"次韵送人之五羊","f":"曲","c":["豫章远接五羊城，白鸟飞还道路明。","昔我乘桴游汗漫，今君揽辔度峥嵘。","湖堧夕下潮声转，斗角寒深宝气横。","总为观风扬职业，有诗才不负兹行。"]},{"t":"七月一日，度毛竹山","f":"曲","c":["毛竹山高风物幽，夜宿白云新雨收。","沿溪而上钟鼓导，自昔以来仙圣游。","久知地迥飞猿黠，新喜天空鸣鸟稠。","折险萦危尽吾力，此行聊不负司秋。"]},{"t":"曾教授赴韶州","f":"曲","c":["荔子红边五月初，广文去住定何如？","报恩岂恋将军马，治盗聊迂太守车。","多近藤萝安吏舍，少凭椒葛附音书。","到官定有佳声荐，瘴雨蛮烟细祓除。"]},{"t":"获鹿西郊，在樵舍下十里。鹿脱阱走山麓，余驱骑者踣之，以缚自随。时藩兵方燎原，靡得观者传讶","f":"曲","c":["猎人大火布江矶，准备平章旦出闱。","麀鹿齐看赤手获，鸷鹰犹傍碧云飞。","呦呦尚想山居纵，麌麌宁忘野食肥？","天上神仙不得力，心安束缚从吾归。"]},{"t":"靖海县","f":"曲","c":["海县春深沙气暄，居人生事不离村。","上梯取斧料桑尾，抽橛移舟系柳根。","已过清明违帝里，不妨红白遍江园。","持杯试与酬风物，深愧樊迟学圃言。"]},{"t":"百丈春日纪怀三首 其一","f":"曲","c":["江墅群芳手自栽，春前相次斸苍苔。","邻僧昨许山兰送，社妪新分圃药来。","本为圣情思共济，更饶生事得相催。","粤王溪畔韶光好，谁想经年逝不回？"]},{"t":"百丈春日纪怀","f":"曲","c":["东风久不到新堂，生意虽微未卒荒。","草上葫荽偏挺特，花间芦菔故高长。","时来岂尽栽培力，物化须知长养方。","葵藿有心终莫夺，每闻支笏照沧浪。"]},{"t":"百丈春日纪怀三首 其三","f":"曲","c":["飞飞燕子守绳枢，爱尔由来似凤雏。","肯谓撩人嗔坐对，向曾去我忆巢孤。","涂泥须责经营苦，爪觜无供啄哺娱。","春社风光时有再，天生品汇各悬殊。"]},{"t":"太朴缄至君静清诗，读之慰快。斯文凋敝之余，安得见此杰然者？敬叹敬叹。一诗寄谢并简君瑞，要知于二贤倾倒之至也","f":"曲","c":["元丰宗匠是吾师，幽梦江湖每见之。","在昔才名真盖代，祇今子弟好能诗。","六经更待黄麻拟，双剑终因紫气知。","衰疾连秋犹长物，扁舟未到谢相思。"]},{"t":"吊张炼师","f":"曲","c":["名家接武依丹陛，壮岁招魂入翠微。","遂使老聃成自吊，不知丁令竟何归？","蛇蝉岂恋寻山蜕？","鸡犬曾闻挟日飞。","独有皇恩无以报，昨传天语慰松扉。"]},{"t":"李原李翁","f":"曲","c":["鲁国先生九十余，百年消息定何如？","世情看作东流水，天地留恩下泽车。","陇西供奉岂无酒？","河上丈人空有书。","见说乡邻问何事？","扣门语及莫钟初。"]},{"t":"寄题集贤周司直悠然阁","f":"曲","c":["番阳东下万山围，魁阁峥嵘面翠微。","云接大荒回古色，波涵落木动晴晖。","宦情静与游鱼逝，诗思长随夕鸟飞。","久待倚阑成独酌，痴儿了事各须归。"]},{"t":"徐闻县怀京下旧游","f":"曲","c":["平生不识张廷尉，中岁方逢马伏波。","昨见山川皆胆落，稍侵霜露始心和。","皇恩远荷优隆至，旅况深惭慨惜多。","天上故人安好在，西风迟暮意如何？"]},{"t":"泰定二年丙寅岁元日","f":"曲","c":["闽藩杰构入青云，箫鼓声高万壑闻。","瓯粤谁存封建业？","唐虞真是圣明君。","蓬莱瑞气皇居正，太液恩波御席分。","身远祇怀归委佩，丝纶阁近最缤纷。"]},{"t":"自戎府出还珠门，晚归廨舍","f":"曲","c":["光迎署府千花树，秀入河桥万柳梢。","春日楼台围翠巘，夜晴灯火接青郊。","升平旧俗今犹在，浩荡流年又过交。","董奉接官何处宅？","相依愿与结衡茅。"]},{"t":"闽山神光寺西崖上观唐李阳冰篆，篆为山僧架屋所坏，存者始二十二字云","f":"曲","c":["城西有寺忽如林，伏地卬霄苔藓侵。","古人题字看欲遍，今我杖藜来相寻。","潜蛟在壑不多见，飞鸟过岩时一吟。","斫破荒祠山鬼怪，祇饶游览重千金。"]},{"t":"游南涧寺，寺乃唐节度使王审知所建","f":"曲","c":["闽山东面启松门，梯石层层见梵尊。","题表尚存唐节镇，地图浑似洛林园。","亭因聚远开幽径，栈至临危出小轩。","最是跻攀宜健步，病身无羽亦飞鶱。"]},{"t":"伏睹中书以内郡饥遍行拯救新令，感激有作","f":"曲","c":["江南往岁旱连州，河北今年水逆流。","恭体朝廷宽大意，少纾田里散离忧。","表章有道诚长策，衣食无功本拙谋。","国制由来重农亩，太平政不在他求。"]},{"t":"宪司双榕轮囷数十围，其庇数亩，雨止，观白鹭","f":"曲","c":["榕树庭中翠欲昏，飞来白鹭动如云。","每当弹射思伤物，忽到徘徊感离群。","护子乌鸦来辟易，附人鹳鹊漫缤纷。","要知得失都何与？","含育无由报圣君。"]},{"t":"归思","f":"曲","c":["陶公归思定如何，山郭春风长薜萝。","直道当官惟任拙，庸才负禄祗惭多。","江山实自辞家隔，日月虚随闭户过。","点点飞鸿向天末，忧端不类泽中歌。"]},{"t":"到官","f":"曲","c":["陶公到官八十日，今我到官逾半期。","劝农省俗了无补，暖衣饱食将何为？","常思在山深虎豹，几曾当道假狐狸？","英雄见义犹饥渴，可使文人有愧辞？"]},{"t":"风止闻鹊","f":"曲","c":["荒山远水放轻舠，顿雨颠风戒弊袍。","五六月馀乡问绝，二千里外客心劳。","树间乌鹊声频好，天上麒麟格自高。","独有武夷看未了，野人寄语压香醪。"]},{"t":"奉和吴宗师退朝","f":"曲","c":["柳外朝冠古进贤，云间观户旧通仙。","蓬莱岂隔三千里？","华颂宜过一万年。","香并衮龙浮瑞日，声随箫凤下晴天。","文臣不愿金茎赐，但想黄封到竹边。"]},{"t":"奉观郊庙礼成，简曹礼部元用","f":"曲","c":["西山半壁影钩陈，晴雪新销路马尘。","两岁通行三大礼，千官中称一闲身。","伊皋事业何当下？","管乐才名不用真。","遥忆南宫旧词伯，退歌清庙属生民。"]},{"t":"和马贡士元夕同观灯之作","f":"曲","c":["已戒金吾夜不哗，西山又被雪微遮。","饥年禁酿知谁力？","到处看灯似我家。","旅梦比尝经赤甲，病身尤欲恋黄芽。","云端此日烟霏暖，遥想仙人立露华。"]},{"t":"答李泂","f":"曲","c":["客居离索感芳晨，颇耐物色恼诗人。","花心尽逐阳和动，柳眼宜于故旧新。","万里清江家共远，九春皓月梦兼频。","鹿门自有庞夫子，长往烟林秋复春。"]},{"t":"调马君","f":"曲","c":["平时有酒不解醉，愁至方知酒道尊。","一万里程兼雪霰，三千年事隔朝昏。","何因洗盏花间屿？","更与停鞭柳下墩。","寄语东邻马贡士，今晨琴筑好温存。"]},{"t":"独立","f":"曲","c":["能诗不得静中师，又是天涯独立时。","高阁夕阳人影乱，曲河新水棹声迟。","一身慷慨家仍远，十口凄凉岁荐饥。","偶尔凭阑感风物，临流先被白鸥知。"]},{"t":"张留公母","f":"曲","c":["山风遥引紫云车，楼阁春深阿母家。","更五十周重甲子，后三千岁一桃华。","彩衣故绾封留印，白璧新随使蜀查。","见说麻姑旧行处，至今源上有丹砂。"]},{"t":"奉和王继学怀济南旧游四首 其一","f":"曲","c":["前辈风流逐断澌，济南旧录故人诗。","遥知灵运初游日，正是元方后载时。","青社寥寥成异物，丹丘皛皛属遐思。","壮年易动离居感，缱绻花前金屈卮。"]},{"t":"奉和王继学怀济南旧游四首 其二","f":"曲","c":["楼上看山翠黛浮，楼前沽酒锦缠头。","登临试与询湖雁，豪杰亲曾侣海鸥。","沙岭晓晴云散出，野亭春尽水交流。","意中故旧那能得，强拟偷生赋远游。"]},{"t":"奉和王继学怀济南旧游四首 其三","f":"曲","c":["每愁大手不如燕，多见公侯胜昔年。","计拙欲求千户等，心劳政类十洲仙。","几回见月思归去，暂到临风复惘然。","剪尽绿杨三万树，多因无处著啼鹃。"]},{"t":"奉和王继学怀济南旧游四首 其四","f":"曲","c":["手接新词绝底清，一双白眼为君青。","寰区政待新年谷，江汉徒传赤日萍。","断雨潜蛟虚水榭，远波回鹭实云汀。","此情可在齐州外，不解无人问独醒。"]},{"t":"和田师孟郎中寒夕西曹即事","f":"曲","c":["正是西曹遣翰初，落花寒食柳微舒。","每因作者留心苦，多恨时人守法疏。","诗思偶关绵上史，刑修正在腹中书。","平生万卷苏居士，皓首东坡雪不如。"]},{"t":"上真应寺观寺后龙湫，湫在厓上，盖由寺北下马，并高数十折得之。又数步许，得巨石，有僧龛，其中云即唐卢叟所隐成道处。时日斜，方焚香诵经，闻客至，乃辍诵相迎作茶云","f":"曲","c":["凭高窈窕辨精蓝，濯佩还思访古潭。","字扁孟家题处碣，洞留卢叟去时龛。","近人野鸟如曾识，问客山精不敢谈。","闻说平坡犹在上，登临虽倦且停骖。"]},{"t":"雨后坐郝大参亭子","f":"曲","c":["每见人来问草堂，偶从燕坐忆沧浪。","地形远竞朝霞爽，林气清分宿雨香。","移石旋成行药径，障泉思引钓鱼航。","他年紫绶归黄阁，几杖苔生尽不妨。"]},{"t":"雨后过王长史","f":"曲","c":["省郎近佐三公府，想得深怀似故山。","风急游丝当院静，雨余芳草闭门闲。","未离尘土长思蜕，已近江湖不论还。","自尔相看慰岑寂，不闻朝署有新班。"]},{"t":"挽刘提举","f":"曲","c":["逝川无力可能攀，又送先生葬碧山。","化鹤不归华表上，鸣鸡倘在白云间。","空歌楚水巫阳些，不见蓬洲使福还。","毕竟修文阴有待，玉楼何许泪潸潸？"]},{"t":"和谢伯雨见惠之作","f":"曲","c":["骚灵逝矣不堪呼，几欲南游讯楚巫。","城郭烟涛垂白帝，星河风露浥黄姑。","幽人往恨九关豹，佳士今犹千里驹。","久客资君相慰藉，可能无意谢飞凫。"]},{"t":"送黄中庸归吟","f":"曲","c":["法乐洞前曾一游，君家闻处洞西头。","石潭正照猿猱月，山药曾经虎豹秋。","岂意吴城祠下路？","共寻扬子岸头舟。","胸中富有天官学，莫为周南久滞留。"]},{"t":"莲房","f":"曲","c":["忆得花神一笑欢，六郎家住小江干。","佳人怨等秋风近，稚子眠听浦雨寒。","强为折来开户牖，谁将镕出拟杯盘。","少年太守思兄弟，戢戢青头莫漫看。"]},{"t":"桂子","f":"曲","c":["尽输金粟三千斛，换得琼枝数点秋。","定是月中嘉种失，却从世上异香浮。","石岩夜见呼猿摘，药臼晴敲伴兔秋。","十月天台谁得见？","西风吹梦落山头。"]},{"t":"送夏兰同知会昌","f":"曲","c":["承闻吉日上江船，佐命分符落雁边。","野馆溪头三晋雪，山城留下七闽烟。","庭春花气迷铜墨，市瞑溪声学管弦。","何日周庐寻夜直？","倍知报政九重天。"]},{"t":"赠广居查尊师远游","f":"曲","c":["查君学道恋名山，庐结东南紫翠间。","更忆皇州春色好，却辞仙馆曙光闲。","千年城郭逐人去，八月星河奉使还。","莫为昆仑无觅处，早将诗赋动江关。"]},{"t":"至怀安县，又入福州","f":"曲","c":["山城列障驻余霞，水与长空远映沙。","芍药省中人望幸，荔枝林外客思家。","遥遥徐韨三神棹，渺渺张骞八月槎。","蚤岁学游今白发，不应犹恋枣如瓜。"]},{"t":"平台晚怀","f":"曲","c":["落日微风生晚凉，平台西上万山苍。","佳人独不生同世，乐土那知是异方？","海岳云霞千古意，乡关道路九回肠。","丹青不写归田赋，犹以虚名累霍光。"]},{"t":"送李秘书泂","f":"曲","c":["秘书出自蓬莱苑，流落东吴又一春。","见月定怀骑鹤侣，闻秋肯让鲙鲈人。","吾曹事业徒温饱，子等居诸异隐沦。","海表何由携手再，相怜同是老词臣。"]},{"t":"送别周仪之推官赴钱塘并简李四秘书","f":"曲","c":["武帝龙飞第一春，京华相送各沾巾。","讵知邂逅文身地，总是栖迟皓首人。","山驿蛟眠星满洞，水乡雁起月迷津。","若逢李泂南天竺，为说前书感谢频。"]},{"t":"开岁","f":"曲","c":["自违北极向南辰，重见东皇似故人。","合席管弦方殿岁，殊乡花柳觉先春。","水归楚泽鱼俱化，土覆周郊兽亦仁。","薄宦于时无补报，且须康济百年身。"]},{"t":"草堂","f":"曲","c":["草堂不在万山峰，时有幽人步往踪。","雨压墙烟笼薜荔，石行渠水鉴芙蓉。","清名岂让陶贞白，共住犹强陆士龙。","忽忆雁行天外去，归来期在粤城中。"]},{"t":"题张果老骑驴图","f":"曲","c":["细柳官桥路，骑驴不用鞭。","先生诚有道，此去亦千年。"]},{"t":"题竹树图","f":"曲","c":["老树半垂叶，疏篁斜露根。","若无烟雾隔，应见石西村。"]},{"t":"秋江","f":"曲","c":["秋生洲渚静，露下蒲荷晚。","忽忆钓鱼时，人家楚乡远。"]},{"t":"建昌小湖望庐阜二首 其一","f":"曲","c":["青云覆叠巘，白鸟度平湖。","钓屿夜来雨，山深知有无？"]},{"t":"建昌小湖望庐阜二首 其二","f":"曲","c":["我怀贞炼士，多在岩谷阴。","惟有高林月，长知望远心。"]},{"t":"题二仙图","f":"曲","c":["明月万山空，溪桥暗路通。","不知何洞府？","终夕坐松风。"]},{"t":"绝句六首 其一","f":"曲","c":["障拥芙蓉竞，灯随榉柳移。","繁星临迥野，疏雨过高池。"]},{"t":"绝句六首 其二","f":"曲","c":["江上打鱼船，有头那无尾。","与卿相见时，不望如鱼水。"]},{"t":"绝句六首 其三","f":"曲","c":["乡路西州是，延平那向东。","片帆侬会使，祇是怕随风。"]},{"t":"绝句六首 其四","f":"曲","c":["水清滩自急，荡桨直须人。","劝卿休恨水，多为不知津。"]},{"t":"绝句六首 其五","f":"曲","c":["水如青铜镜，山色绿芙蓉。","中天明月上，此处好相逢。"]},{"t":"绝句六首 其六","f":"曲","c":["日净芙蓉远，春明芍药长。","谁怜玉蝴蝶？","正似锦鸳鸯。"]},{"t":"看东亭新笋","f":"曲","c":["问竹何年有，亲曾共岁寒。","昨传新笋发，扶杖绕林看。"]},{"t":"送别","f":"曲","c":["为君垂别泪，更向杨花侧。","斗酒问离鸿：几时归故国？"]},{"t":"烛夜","f":"曲","c":["烛影夜侵墙，松桂成行列。","鼓绝草虫鸣，四山露华结。"]},{"t":"秋江图","f":"曲","c":["云里衡阳雁，网下武昌鱼。","石门秋共远，江树雨余疏。"]},{"t":"芙蓉","f":"曲","c":["芙蓉生石壁，云锦映青松。","那忆南州路？","归船处处逢。"]},{"t":"东署","f":"曲","c":["习静天常见，居深路近通。","阴阶垂叶露，空院长春风。"]},{"t":"怀小柏","f":"曲","c":["手种庭前小柏树，分枝散叶总天成。","涉旬不见长相忆，况是经年别友生。"]},{"t":"枫林雨止","f":"曲","c":["篱角枫林露鹊巢，春深翠叶未全交。","山家老屋浑相似，千里行人识把茅。"]},{"t":"题黎氏家山图","f":"曲","c":["漠漠家山在白云，石桥流水路斜分。","状元坊里重来日，还有新阡表陆君。"]},{"t":"社日","f":"曲","c":["丘邻雨止散青烟，白叟相违已隔年。","忽遣大儿三角结，打门来觅社神钱。"]},{"t":"赠卓秀才还澧州","f":"曲","c":["不说从师学道难，一身千里暮云端。","是行若拜庭闱罢，有使题诗祇寄兰。"]},{"t":"五月二十六夜宿松林兰若","f":"曲","c":["白沙寨下接飞霞，行至招提日已斜。","睡觉忽闻山寨语，不知今夕离吾家。"]},{"t":"瑞州城东水边松下，遇老翁稚子，萧然有桃源想","f":"曲","c":["花墙竹栅护长松，云去柴门昼启封。","不是武陵州县古，秦人那得晋人逢？"]},{"t":"登高风亭（亭在三刘祠后，今西涧书院刘凝之书，高安人子道原、孙义仲）","f":"曲","c":["罢官本自亦由君，直节高风世世闻。","天下布衣能致禄，多应无传附青云。"]},{"t":"桑落洲","f":"曲","c":["桑落洲前秋兴孤，白云远见近还无。","传闻酒吏经年罢，美酿家家得纵沽。"]},{"t":"发湖口","f":"曲","c":["已过匡庐却向西，片帆犹逐暮云迷。","路长正是思亲节，取次惊猿莫浪啼。"]},{"t":"浔阳","f":"曲","c":["露下天高滩月明，行人西指武昌城。","扁舟未到心先到，卧听浔阳谯鼓声。"]},{"t":"题山水图","f":"曲","c":["烟崖窅窅树栾栾，三两渔舟戏碧澜。","不解买山头已白，今朝又得画图看。"]},{"t":"十月白牡丹，郢中孙氏家植也","f":"曲","c":["霜槛枝头结素云，分明便有绣成裀。","紫皇为爱春风早，特向瑶台折赠君。"]},{"t":"八骏图","f":"曲","c":["天上房星照九垓，翩翩西域画龙媒。","昆仑一去无消息，空见人间八骏来。"]},{"t":"试院中，戏题姚检校山水图","f":"曲","c":["故园不涉已经秋，何日径辞黄鹤楼？","却借仙人绿拄杖，乘风散上碧峰头。"]},{"t":"以琼扇一握奉致黄明府","f":"曲","c":["拾得炎州月一团，殷勤持赠比琅玕。","情知已是秋风后，留作明年九夏寒。"]},{"t":"咏鹿","f":"曲","c":["野性难驯不称家，呦呦如怨复如嗟。","何如送汝归山去？","许令台前卧落花。"]},{"t":"钟陵夜宿闻钟","f":"曲","c":["中年江海梦灵皇，夜半闻钟似上阳。","一百八声犹未已，更兼云外雁啼霜。"]},{"t":"宿村庄，见高进士留题，戏作","f":"曲","c":["三水桥边望翠篁，行人驻马立昏黄。","因何秉烛来投宿？","州判题诗在草堂。"]},{"t":"午憩村落竹溪上","f":"曲","c":["竹连流水水缘村，上有青山荫苎园。","此处不容居士住，短墙午暑特侵门。"]},{"t":"日晏","f":"曲","c":["昨日相期早出村，今朝日晏未开门。","可人一夜东风雨，绿遍天街旧草痕。"]},{"t":"四月三日，蚤作，访夏编修","f":"曲","c":["晓穿甲仗抵晴沙，桥角垂杨乱映花。","春色于人元不薄，将诗勾引到君家。"]},{"t":"答赠晚春","f":"曲","c":["懒向佳人说翠微，长安陌上见春晖。","谁家门巷花狼藉？","吹作漫天白雪飞。"]},{"t":"初六日，在院中，僚友无人至","f":"曲","c":["乘舆闻喜达皇都，自此玉堂宣锁无。","闲杀幕中挥翰手，日长独坐数花须。"]},{"t":"因杜右父编修赠痔医","f":"曲","c":["舐痔曾闻获乘车，王卿妙艺复何如？","祇应杜老波澜笔，绝似齐人治验书。"]},{"t":"院中夜直","f":"曲","c":["此身只似到南州，莎草寒鸡一片秋。","后夜玉堂谁上直？","料应少睡更多愁。"]},{"t":"赠黄道士别","f":"曲","c":["二十四岩烟雾幽，轻舟横笛戏清流。","万人举手风尘下，怪杀仙人学远游。"]},{"t":"邻灯","f":"曲","c":["星星远映孤村外，炯炯微穿落木间。","知有邻姬思远道，绩麻应待夜深还。"]},{"t":"休日","f":"曲","c":["暂解晨参不出关，有时持酒忆南山。","无端却被诗牵引，断送先生此日闲。"]},{"t":"十一月十六夜","f":"曲","c":["本是圆时半不明，非缘掩冗复何情！","更无云表真消息，钟鼓盆罂乱自鸣。"]},{"t":"戏题二牛","f":"曲","c":["燕山丈人年九十，戏笔扫此双犁牛。","江南夜半春雨作，老农惊起为君愁。"]},{"t":"离扬州","f":"曲","c":["孤篷如磨绕汀沙，叶满平湖藕未花。","回首竹西亭渐远，一江烟雨酒旗斜。"]},{"t":"赠裴氏二子","f":"曲","c":["有后深知晋国贤，伤心不为海南边。","相逢莫笑无多赠，犹是词垣旧俸钱。"]},{"t":"过三合驿","f":"曲","c":["一春归计又蹉跎，穷粤风光奈病何。","总有青山千万叠，行人长少鹧鸪多。"]},{"t":"江阁雨望图","f":"曲","c":["高阁秋风树半枯，连山更带雨馍糊。","幽人把钓空江上，纵有扁舟不受呼。"]},{"t":"见观西人家石榴","f":"曲","c":["石榴始华实已红，橘柚照日青玲珑。","自来南州感风物，赖得邻人生意同。"]},{"t":"十月十一夜，东署闻雁","f":"曲","c":["久别云林旧草亭，南江都邑岁雕零。","可怜此夜长空雁，正在青松树底听。"]},{"t":"诘朝，进书西宫，问卢九修撰借马戏奉绝句","f":"曲","c":["作书太史具有喜，徒步拾遗方可忧。","明日待朝天上去，何由赠我紫骅骝？"]},{"t":"高斋","f":"曲","c":["俗客过门应有数，祇言浑似野人家。","小斋高接万林杪，坐见城南城北花。"]},{"t":"候孔校书","f":"曲","c":["承闻舟楫向河干，久别深思再见难。","已具一尊林下酌，好来共慰百华寒。"]},{"t":"悼节","f":"曲","c":["百华高下拥晴天，竹屋方床兴悄然。","忽忆逝人泉下冷，学烧楮火作新烟。"]},{"t":"清明后，闻邻庄牡丹尽发，馆中独迟。雨晴，忽开一枝，咏以志赏","f":"曲","c":["千山飒飒雨无风，憔悴群芳二月中。","整待人家春事过，小亭特放状元红。"]},{"t":"题杨补之墨梅","f":"曲","c":["学到逃禅自一家，洗空尘墨印江沙。","笔端不有兰亭骨，莫写园林雪后花。"]},{"t":"江东晚泊","f":"曲","c":["云间列岫映朱楼，江水东来打石头。","不是行人惜光景，人心旧有帝王州。"]},{"t":"江上古祠","f":"曲","c":["老树昂藏倚岸隈，祠灵经岁锁苍苔。","豚蹄卮酒能多少，便有群鸦旦暮来。"]},{"t":"重感","f":"曲","c":["曾谒聊城太守归，吏扶残醉踏斜晖。","重来柳下停船处，太息人间万事非。"]},{"t":"湖面","f":"曲","c":["湖面春深煖气匀，青芜未陨已知春。","沙湾散驻张鱼客，苇室时惊射雁人。"]},{"t":"玉隆宫","f":"曲","c":["东晋真人尚典刑，石函故在药飘零。","阁前正是升仙处，云路笙歌少得听。"]},{"t":"经梅仙坛下","f":"曲","c":["懒慢辞朝梅子真，空山祠庙已千春。","自从上疏东都后，不见江湖有直臣。"]},{"t":"北山谷中老父","f":"曲","c":["无多林屋冠青山，长子成孙鬓未斑。","问我乡原何处是？","半生江海未知还。"]},{"t":"题万竹秋声","f":"曲","c":["山人爱竹手自种，万个直临江水边。","长吟浪被秋风觉，散作宫商声满天。"]},{"t":"钱生幽禽图","f":"曲","c":["谁人剪下碧梧枝，误落西风粉墨池。","立断小禽飞不去，朝阳何事凤鸣迟？"]},{"t":"封州作","f":"曲","c":["魏阙迢迢隔彩霞，别来几岁客天涯？","春风二月崖州道，时见棠梨一树花。"]},{"t":"渡端州峡","f":"曲","c":["棹郎得便溯清流，忽报舟前晓雾收。","蛮语酬人翻自苦，好山不敢问何州。"]},{"t":"正月二十四日至宝圭驿是北流县自此遵陆指郁林矣","f":"曲","c":["远辞京阙碧云端，溯尽夷江未到官。","回雁峰南更千里，是行谁为报平安。"]},{"t":"登沓磊驿楼，自此度海","f":"曲","c":["半生长以客为家，罢直初来瀚海槎。","始信人间行不尽，天涯更复有天涯。"]},{"t":"谒海神庙","f":"曲","c":["南州未识异州苹，初向沙头问水神。","料得行藏无用卜，乘桴人是北来人。"]},{"t":"得樟树镇便寄家书","f":"曲","c":["商船夜说指江西，欲托音书未忍题。","收拾乡心都在纸，两声杜宇傍人啼。"]},{"t":"琼州出郭","f":"曲","c":["自出琼州古郭门，更无平衍似中原。","重重叶暗桄桹雨，知是黎人第几村？"]},{"t":"临高阻雨","f":"曲","c":["恐倾南海成秋雨，急唤西风作晚凉。","净扫黎山须见骨，莫令楚客屡回肠。"]},{"t":"槟榔寨","f":"曲","c":["秋入黎山风雨多，长江不定驻惊波。","翠榕叶底闻鹦鹉，自此无如客思何！"]},{"t":"安定县","f":"曲","c":["岛上晴云灭复生，谁家吹笛海天明？","县堂晓起西风急，半是深黎夜雨声。"]},{"t":"至富屯","f":"曲","c":["承恩千里出江乡，转历三关道路长。","黄叶雾开山市集，见人凫雁忆横塘。"]},{"t":"西楼","f":"曲","c":["童子出舂亲掩关，春来芳树伴人闲。","别家五月不得信，独上西楼思远山。"]},{"t":"元夕","f":"曲","c":["危楼向暮倚层空，故岁今年不得同。","记取合沙元夕节，满街箫鼓雨兼风。"]},{"t":"正月十六夜，双门观灯，时闽、粤阃官吏皆集","f":"曲","c":["双门此夜启崇台，次第东山好月来。","自古金吾元不禁，少留大将与衔杯。"]},{"t":"二十六夜，得舍弟书，及知熊敬舆茂才消息。期旦夕有会，并知便，良足快慰也","f":"曲","c":["故人天阙腾新荐，舍弟云溪守敝庐。","未省东归何日见？","挑灯细读寄来书。"]},{"t":"南涧志见","f":"曲","c":["繁桃只称倚红扉，腊酒吹香着舞衣。","楼底谁家吹玉笛？","一双白鹭上云飞。"]},{"t":"池馆夜坐听雨","f":"曲","c":["更声随雨动谯门，颇似听泉宿楚原。","客里青灯如骨肉，独能相待向黄昏。"]},{"t":"怀京下亲友","f":"曲","c":["海上经年思杀人，绝怜京国旧交亲。","过江唯有传柑使，寄得书回是暮春。"]},{"t":"池上晚步","f":"曲","c":["清池斜步竹烟微，莺啭重门锁夕晖。","退食幸堪无趋谒，见人惭道听公非。"]},{"t":"不寐","f":"曲","c":["鼓角连天月满城，芭蕉叶上露华生。","思乡不寐占潮信，说是中旬夜半平。"]},{"t":"夜坐池上馆","f":"曲","c":["沉沉画戟隐高牙，月满闽都十万家。","竹外小曹人睡稳，杖藜独立听鸣蛙。"]},{"t":"建安馆夜坐听流水","f":"曲","c":["平生慕爱武夷君，及此名山阻白云。","九曲水声流过郡，夜深犹得世人闻。"]},{"t":"路傍树","f":"曲","c":["路傍古木是谁栽，更有山棠次第开。","东海神仙求不得，何因百岁客重来？"]},{"t":"临觞","f":"曲","c":["几见春钟度上阳，偶因寒尽强临觞。","故乡只在车轮下，自是青云路每长。"]},{"t":"闻笳","f":"曲","c":["何处闻笳最是悲，京门独立晚晴时。","鹂庚一去荒郊远，借问春光有底迟？"]},{"t":"夜诵赋瓶花","f":"曲","c":["胆瓶折得树头花，初是东园一片霞。","西涧读书过夜漏，忽随灯影上窗纱。"]},{"t":"寓书","f":"曲","c":["欲写乡书寄故园，行人已远意空存。","举头却见南来雁，个个随春度塞门。"]},{"t":"山僧养犬","f":"曲","c":["不见岩扉净业君，山僧养犬漫成群。","人知自此来看少，祇向山中吠白云。"]},{"t":"忆得","f":"曲","c":["忆得佳人《白纻》词，几将天外数归期。","自从落尽庭前树，夜夜秋声总不知。"]},{"t":"赠郭判官","f":"曲","c":["慈乌夜夜向人啼，几度纱窗兔魄低。","自有平安三百字，无因却寄大江西。"]},{"t":"种树","f":"曲","c":["种树江头不记春，年来年去祇伤神。","今朝忽向江头见，稍有清阴芘路人。"]},{"t":"沟上","f":"曲","c":["御沟新绿动朱阑，沟上垂杨尽可看。","惟有西山九千仞，朝朝阙角倚晴寒。"]},{"t":"卧病","f":"曲","c":["朝来忽见树藏霞，碧草村边径路斜。","佳客不来春雨尽，山禽啄遍小桃花。"]},{"t":"灵应宫","f":"曲","c":["万花如绣拥青红，梯石棱层见梵宫。","一十二时春百刻，日长半在鸟声中。"]},{"t":"清明日留西山","f":"曲","c":["离家六度见清明，知是何时出帝京。","今日登临倍惆怅，好山多似豫章城。"]},{"t":"逢芳草","f":"曲","c":["忽逢芳草思绵绵，绿遍郊原翠满川。","不是王孙归未得，尽缘春色有今年。"]},{"t":"西谷访人不遇","f":"曲","c":["出郭幽人晚未归，青天咫尺见何稀。","一年祇有春晴好，多事杨花学雪飞。"]},{"t":"题闺人望远图","f":"曲","c":["郎行不用苦悲辛，久别心知万事亲。","看取江边垂柳树，最先零落最多春。"]},{"t":"酬友人月夜见寄","f":"曲","c":["舍北舍南流舫通，高荷万柄倚微风。","不识此时明月夜，共谁谈笑水烟中？"]},{"t":"题沈、李二山人谈道图","f":"曲","c":["白云流水两无情，一段忘言画不成。","昨夜天坛明月满，野风四壁候虫鸣。"]},{"t":"春日上平坡寺","f":"曲","c":["萝径阴阴近百层，金舆记是昔人登。","山僧苦避寻诗者，牢闭柴门唤不应。"]},{"t":"省灾，初至新建山谷山家","f":"曲","c":["恤灾犹自恼渔樵，太息无时缓赋徭。","日暮解鞍仍秉烛，强颜聚吏戒科条。"]},{"t":"山下","f":"曲","c":["楼外风江集米船，楼中光景月流天。","空洲此际无鸣雁，犹比山深少夜眠。"]},{"t":"章义门送人还南城观台","f":"曲","c":["郊原平晚绿萋萋，独上高台意转迷。","古树鸣蝉城下路，送人长忆向安西。"]},{"t":"怀临江寓居","f":"曲","c":["石霜峰北淦西头，寄住林塘数亩幽。","比及到家犹是客，对人强自说乡愁。"]},{"t":"清明日","f":"曲","c":["旅庖欲禁自无烟，酒里中原熟食天。","不分小桃红似火，为人儿女照鞦韆。"]},{"t":"西垣感春","f":"曲","c":["帘幕沉沉燕子归，牡丹带露浥春晖。","依然画省风光妙，少问去年人是非。"]},{"t":"杨花","f":"曲","c":["穿空透户本无因，若便随风恼杀人。","我似杨花花似我，年年飞尽玉堂春。"]},{"t":"挽西蜀□先生","f":"曲","c":["八十犹传隐者名，乾坤未是负先生。","无端白帝城边水，欲载哀歌上玉京。"]},{"t":"归自馆中闻莺","f":"曲","c":["春来羁思不堪论，日日瞻星谒禁垣。","昨夜归来津口听，娇莺啼断内城园。"]},{"t":"友人壁间寒山图","f":"曲","c":["行尽天涯不见秋，君家庭院冷飕飕。","太平欲选风霜吏，画史当居第一流。"]},{"t":"东郊","f":"曲","c":["东郊芳草绿萋萋，欲到浑如恋马蹄。","总是都门好春色，随人直到大江西。"]},{"t":"绝句","f":"曲","c":["幽人不出户长开，看尽春风长绿苔。","多谢有情双燕子，暂时飞去又飞来。"]},{"t":"怀南省海棠，感新事作","f":"曲","c":["海棠花发醉题诗，犹记西垣下直时。","今日岂无歌舞地？","一尊先被外人知。"]},{"t":"赠聊城施生","f":"曲","c":["京国相逢意若何，向人平谳路人歌。","皋陶此去为廷尉，似子宁疑一掾多？"]},{"t":"赠盛复之之官宣德","f":"曲","c":["帝城谷雨见黄鹂，关外风光大较迟。","想得牡丹花落后，先生初是到官时。"]},{"t":"戏题张平章所赠洪生书后","f":"曲","c":["一翁二季向皇都，未必遭逢事太殊。","祇惜翰林欧学士，当时书让蔡君谟。"]},{"t":"赠水鉴道人写真","f":"曲","c":["鉴尽公卿写尽真，此心澄彻故通神。","世间未用论沧海，何日河流照得人？"]},{"t":"十二月十九日，候进贤，该吏不至，看野人家道书","f":"曲","c":["社农家近白鸥沙，再系停骖候蚤霞。","闲启古囊看法箓，此身如到玉清家。"]},{"t":"送萨佥宪至岩头渡","f":"曲","c":["石头渡口风烟古，洗盏开樽对浅沙。","却唤掾曹无觅处，移船幽寺看黄花。"]},{"t":"小年日，仍宿北山","f":"曲","c":["腊日才过又小年，那堪泽国雨连天！","儿童把酒传明烛，远想慈亲尚未眠。"]},{"t":"题秋林图","f":"曲","c":["霜树前头欲下禽，远行逢有慕归心。","佳人昨日天际去，红蓼作花秋正深。"]},{"t":"孝友堂","f":"曲","c":["堂前多种紫荆枝，堂上能啼白发儿。","但恨后来风雅废，南陔不似古人诗。"]},{"t":"戏题奉寄行营董佥事","f":"曲","c":["五月沙山铁骑罗，将军无那太平何！","帐前养得堂人鹿，祇爱行营芳草多。"]},{"t":"和揭曼硕茂才，揭尝过临不遇，留题墙壁","f":"曲","c":["麻姑蚤解鬓成霜，况说山中海与桑。","久别南城坛近客，西风残照忆题墙。"]},{"t":"题烟雨图","f":"曲","c":["似有江南布谷声，乱流触石野桥平。","何由招得鱼竿客？","共上西峰看晚晴。"]},{"t":"题稚川芦雁图","f":"曲","c":["不见罗生心惘然，画图河朔尽流传。","沧洲旧隐无人识，正似寒芦落雁边。"]},{"t":"伊孝子","f":"曲","c":["是州宁有古藤君，子弟班班行义闻。","又说水村烟郭外，伊家水树抹青云。"]},{"t":"题松雪图","f":"曲","c":["傍人不识岁寒松，怜杀深山大雪封。","待得化为东海水，青天白日睡苍龙。"]},{"t":"桃花原是渐岭对江","f":"曲","c":["雪晴寻路入华原，绝爱清江抱远村。","行处祇贪幽树好，不疑山谷易黄昏。"]},{"t":"题广居家藏东坡竹","f":"曲","c":["古藤尺五霜烟交，不见长身见墨梢。","千载高风犹一日，莫妨儋耳住无茅。"]},{"t":"经石门镇","f":"曲","c":["摇落石门秋水清，残僧楼宇映沙明。","买船欲上旴江去，路转峰南闻雁声。"]},{"t":"春日西郊","f":"曲","c":["东风千里福州城，绿水青山老送迎。","惟有垂杨偏待客，数株残雨带流莺。"]},{"t":"春日西郊四首 其二","f":"曲","c":["佳人不让海棠娇，喜见天晴挹露饶。","若使有诗宁费日？","便令无酒亦终朝。"]},{"t":"春日西郊四首 其三","f":"曲","c":["江上登台望眼迷，西禅更在石岩西。","寻常楚峤看花日，此处新苗绿已齐。"]},{"t":"春日西郊四首 其四","f":"曲","c":["南涧清晨不易得，有无更似此时春。","朱桃皓李都随世，紫蝶玄蜂故趁人。"]},{"t":"闻东郊夜歌","f":"曲","c":["促拍繁歌沸不停，月高弦语转明星。","莫令知有西邻客，独坐挑灯看六经。"]},{"t":"乐会县","f":"曲","c":["早发端赵村，莫投乐会县。","县阻道路长，但见水葱茜。","轻风掠溪麋，好月触石面。","前行日已分，后从气犹昡。","役者向我言，前年土豪变。","黄旗伐画鼓，樵屋拟牙殿。","居民绝烟爨，搬并入淮甸。","却又遭劫杀，流动靡安奠。","群夷尽蜂起，尽用血洗箭。","公然肆浡暴，请与官军战。","官军幸努力，摧落得深便。","虽获覆其巢，奸愚不胜谴。","于今郊原间，芳草白骨遍。","我行适夜分，听此毛发旋。","前冈明炬火，叫应欣蹂践。","官吏候我来，始与人相见。","沿河岛沚深，问路山田转。","啾啾乌鸟鸣，靡靡鞍马倦。","一从违京国，几度梦霜霰。","何所非异乡，开怀谢身健。"]},{"t":"即事","f":"曲","c":["随地居能胜，因人景倍饶。","折风疏菡萏，移雨近芭蕉。","放浪明高蹈，留连近久要。","虚心待世虑，已任过云飘。"]},{"t":"苏李会合图","f":"曲","c":["未识沙场苦，空曾奉使来。","讵知羝乳约，不抵雁书回。","汉节风霜古，胡笳旦暮哀。","谁怜太史令，心为故人摧。"]},{"t":"六月初十夜雨止玩月有感","f":"曲","c":["雨歇青林迥，虚斋生夕凉。","帘帷方度月，枕簟已怀霜。","地角家何在，云端路转长。","慈帏近安否，归觐不能忘。"]},{"t":"王武子相马图","f":"曲","c":["偶然来厩吏，唤作九方皋。","毁誉依名立，周旋逐物劳。","神驰风电足，眼冷雪霜毛。","事有遭逢者，骐驎固自高。"]},{"t":"八月十五夜","f":"曲","c":["城上初闻柝，天边独倚楼。","可怜今夜月，还照异乡秋。","烛暗频移席，帘虚不上钩。","回文锦机字，写得大刀头。"]},{"t":"风雨","f":"曲","c":["风雨忽如此，空山方昼眠。","故应为计拙，可复要人怜。","灯火乡村路，桑麻杜曲田。","悠悠今视昔，把卷一茫然。"]},{"t":"赠别南剑李使君三十韵","f":"曲","c":["北户群山表，南云九域西。","君今行欲遍，此意别都迷。","妙句人谁识，前年手自题。","绝崖钩象译，悬径摘乌栖。","炎隩通冠冕，边陲重璧圭。","礼新尊玺节，名故籍金闺。","劳有恩言切，归无宠数跻。","宸心端外见，庙谊肯中稽。","望誉腾青琐，辉光拂紫泥。","旌麾深假借，民社载扶携。","猛气排苍鹄，幽思启碧鸡。","动应多惬会，行岂强扳提。","皂盖喧童稚，黄堂拜耄倪。","天机驯虎兕，帝力及凫鹥。","越厉冬深少，闽烟晚向凄。","野人封水竹，郡吏接山溪。","汊碧荷香弱，坡红木实齐。","九秋鹏鹗翮，万里骕骦蹄。","导从罗弓矢，登临按鼓鼙。","少须《青玉案》，与报《白铜鞮》。","忠信先蛮貊，文章协壁奎。","孰云当近服，不遂慰烝黎。","执手关河早，论交岁月暌。","物华盈眼乱，春色傍人低。","谢豹空洲隐，王鸠远树啼。","国容方整整，旅病转悽悽。","谬忝词垣密，微能官秩卑。","从班窥遂霸，浪漫笑山嵇。","何日同樽酒，因风独杖藜。","延平宝剑气，旦旦候虹霓。"]},{"t":"寄甄氏访山亭二十二韵","f":"曲","c":["青子亭何许，滹沱旧水头。","谷陵千载异，风物四时幽。","城郭长无事，琴尊或此游。","窗摅平野秀，户接乱泉流。","猿鸟相宾送，渔樵互献酬。","太行晴日近，碣石晚烟稠。","莽莽青天外，离离碧海陬。","都将神迹化，只可笑谈求。","大槛花周映，虚阶叶竟抽。","岂容黄壤污，祇为白云留。","更就诸峰老，宁须万户侯。","心知嗜好酷，势肯去来休。","予亦寻山者，人疑避世俦。","偶然依紫阙，不是谢丹丘。","薄与江湖远，频嗟岁月周。","梦尝经五岳，思屡绕三洲。","室宇凭谁寄，园林誓自收。","把书消旦暮，种药引春秋。","地僻澄官冗，天空扫旅愁。","几时携古剑，万里觅扁舟。","剩想高人趣，空怀贱子羞。","犹胜徐市俗，瀛岛计悠悠。"]},{"t":"晓山谣赠别金陵陈处士","f":"曲","c":["昔我望天岳，于时春正深。","鸡鸣九州陌，鹤警万花林。","旭日腾重海，宵霞映别岑。","露条承嶪巀，雪涧泻嵚崟。","马足无由定，莺声不可寻。","畏钟牵逸览，挂笏系虚襟。","每想丘中趣，如悬空外音。","十秋伤逝水，千壑记扪参。","晚遇陈夫子，高谈契夙心。","天形疏造化，月眼识浮沈。","宦路悲怀玉，君门惜和琴。","岂因平旦气，薄示暮年箴。","但恐丹崖失，何愁素发侵。","会当期绝巘，与尔鍊黄金。"]},{"t":"赠裴秀才","f":"曲","c":["江边见立春，花老问征人。","物色随乡异，风光逐候新。","朝廷方贵士，经术足谋身。","举世皆腾踏，如君独隐沦。","鸣山应鸑鷟，在野决麒麟。","已用遗经试，宁辞累牍陈。","飘飖行李别，缱绻酒杯频。","四海多英俊，诸公自等伦。","云霄开大道，溟涨接通津。","百啭仓庚近，双飞蛱蝶匀。","款留俱酝藉，归到莫逡巡。","肯薄传家赋，犹堪博钓纶。"]},{"t":"赠别邓修撰归杭州","f":"曲","c":["东风二月禁门莺，天上佳人有远行。","惜路频瞻霞上日，望家直到海边城。","休须满假辞三径，定约重来赋《二京》。","回首津亭万家柳，初非憔悴独关情。"]},{"t":"谢冷架阁春日东麓见怀","f":"曲","c":["空谷白驹消息迟，东风杨柳万烟丝。","佩环忆为同心赠，书榜传看俊手施。","曾以陋居追往昔，却因嘉遁感今兹。","相思恐涉山灵怪，不遇仙人不记诗。"]},{"t":"寄题龚氏山园","f":"曲","c":["居士名园何处求，无有是中风物幽。","岩花故解分藤缀，涧水新能合竹流。","绿幕黄帘围玉树，青天白日映朱楼。","醉吟自尔人难识，况是心轻万户侯。"]},{"t":"五月二十日发雷州过徐文次驿候役者不至留二日","f":"曲","c":["久约归吴弄钓舟，海天羁思复悠悠。","谁知树底春生月，独坐人间地尽头。","粉壁旧题分藓读，瓦罂新酒接花篘。","边鸿固是南来绝，绝为雷城信滞留。"]},{"t":"送元经历赴广东","f":"曲","c":["番禺直北望长沙，元帅持戈镇海涯。","万里送君归幕府，几时为我寄梅花。","云蒸巨浪鱼吹岸，柳压荒山獠阵牙。","欲托乡书妨枉骑，湄湘西上是吾家。"]},{"t":"寿宫","f":"曲","c":["武帝初行祀灶方，祠官宫女俨分行。","石阑井井通金殿，金盖童童出画墙。","但见扰龙呼作相，未闻骑鹤拜为郎。","祇今松柏缘原庙，时接云軿下大荒。"]},{"t":"赠陈提举","f":"曲","c":["便令回首绾青银，已负南宫第一人。","文武既兴殷士贡，申辕犹比汉儒真。","离鸿苦事风霜急，伏骥深心道路亲。","若遇清溪寻旧隐，洗觞犹及艾陵春。"]},{"t":"公堂暇日","f":"曲","c":["新起危楼接大荒，海天奇观压殊方。","周墙恨未高千尺，犹见他家竹短长。"]},{"t":"将如靖安徐文学自新拿舟来候良有古意以诗留别","f":"曲","c":["西风危栈逼青云，稍下临江细路分。","问县尚须穷日到，棹歌无计得留君。"]},{"t":"怀京城诸公书崖州驿四首 其一","f":"曲","c":["甚忆清河元侍讲，送行犹有玉堂诗。","只今夜夜陇头月，照见征人有所思。"]},{"t":"怀京城诸公书崖州驿四首 其二","f":"曲","c":["复忆济南张吏部，作诗文气压诸公。","佳儿亦是门生辈，尚想他年似若翁。"]},{"t":"怀京城诸公书崖州驿四首 其三","f":"曲","c":["绣衣御史果能文，蜀道新来有李君。","记得京城黄菊烂，为余来觅董将军。"]},{"t":"怀京城诸公书崖州驿四首 其四","f":"曲","c":["妙为文字吾雄甲，精切于今孰与俦。","说著奉常虞博士，恨渠犹不见崖州。"]},{"t":"县下凿池种树成聚晨起视水深五寸而草树承夜雨后苍翠郁然可爱戏题厅柱","f":"曲","c":["槟榔池上芭蕉雨，更种垂杨十六株。","中有玉堂萧散吏，检书正对《辋川图》。"]},{"t":"至乌石邸舍二首 其一","f":"曲","c":["不见居人只见村，离家茅屋又黄昏。","面前沧海来无际，闻说占城对县门。"]},{"t":"至乌石邸舍二首 其二","f":"曲","c":["苦竹丛西石色乌，来时依旧驿亭孤。","自从历遍崖州路，不敢弯弓射鹧鸪。"]},{"t":"福州杂诗三首 其一","f":"曲","c":["前日题诗自侯官，计程今日到云端。","家人定得平安字，最念痴儿不解看。"]},{"t":"福州杂诗三首 其二","f":"曲","c":["海隅霜熟蛎房肥，狮子桥东望翠微。","安得建阳一斗酒，少随甘旨到柴扉。"]},{"t":"福州杂诗三首 其三","f":"曲","c":["虎豹几曾惊石鼓，鱼龙独解隐金沙。","遮藏翠荔馀千刹，掩映朱霞倚万家。"]},{"t":"至海口","f":"曲","c":["曾随仙仗集灵台，流落于今岂不材。","但比麻姑休狡狯，两行持节过蓬莱。"]},{"t":"二月二十四日自琼州出白沙驿阻风二日不得渡海是日有幕客送寒衣却出赋诗","f":"曲","c":["盲风怪雨一时清，又阻扁舟两日程。","天意似将留客住，明朝浮海看清明。"]},{"t":"郁林次韵寄怀王天辅知事","f":"曲","c":["乍喜连山瘴雾收，黛眉更自锁乡愁。","自从行李违沧海，九日初逢第二州。"]},{"t":"斋居即事用敖徵君韵二首 其一","f":"曲","c":["故人不见意何如，流水孤村处士庐。","犹记去年霜橘熟，分甘曾得寄来书。"]},{"t":"斋居即事用敖徵君韵二首 其二","f":"曲","c":["桑溪竹圃路团团，门巷都非少日看。","送客棹船频借问，向来江面是阑干。"]},{"t":"赵佥宪旧居","f":"曲","c":["閒门付与东风扫，独客残春思远道。","日午不见蝴蝶飞，细看儿童弄芳草。"]},{"t":"春日次韵友生绝句二首 其一","f":"曲","c":["马颊河阳近北辰，去来犹尔恨通津。","陌头总是春风树，自笑杨花只恋人。"]},{"t":"春日次韵友生绝句二首 其二","f":"曲","c":["旅食京华日欲晡，家园迢递隔天隅。","妻孥预识羁怀苦，解事新来一字无。"]},{"t":"西轩即事","f":"曲","c":["行厨晚食坐萧条，欲买锵鱼待早潮。","鼓绝山城门未掩，梦和疏雨度西桥。"]},{"t":"闻角","f":"曲","c":["西风袅袅拂弓旌，千里来看晓角声。","纵复凄凉归未忍，炎州此外更无城。"]},{"t":"句","f":"曲","c":["黄河西去从天下，华岳东来拔地高。"]},{"t":"百丈山中夜坐，闻谨思将还，忆甲寅入南中，正此日也。十二月二十三日六首","f":"曲","c":["近得雷州信，遥闻弟侄来。","江山淹远望，天地保疏材。","乡为鱼羹起，今宁马豆猜。","残年有心事，未定著寒灰。","欲雪翻成雨，何天恰吝情。","似缘春在近，故与月争明。","谷树行行暝，川云冉冉轻。","往年当此夕，孤棹适南征。","岁月嗟匏系，乾坤信梗浮。","蹉跎逐越鸟，迂阔问吴牛。","正道曾无弊，旁观各有由。","圣人如可起，吾欲诘东周。","斜谷惊风合，空阶坠溜鸣。","灯昏时作晕，漏远不传更。","但得林间趣，何须谷口名。","是谁超物外，不用计浮生。","往备清华职，宁知濩落心？","槐街春日盛，杏省午烟深。","出试终何补？","还归敢自任。","祇惭山泽吏，空受二毛侵。","客行身万里，家在地中分。","爵命优臣子，江湖远圣君。","夜瞻龙凤气，岁出虎狼群。","旧故无消息，低回瘴海云。"]},{"t":"寄题严氏樊川别墅二首","f":"曲","c":["先生天下士，小隐郭东村。","甃水缘开径，楹山对掩门。","士风宁近洛？","川姓不离樊。","樽俎心虽间，衣冠口已喧。","亦欲西流去，相寻素浐边。","多应百年术，少见一人传。","生事空芝术，心期托蕙荃。","明当询大药，畏子不论钱。"]},{"t":"秋雨寓舍酬答夏编修四首","f":"曲","c":["乱竹通邻舍，修梧限掖垣。","日长惟有雨，秋半祇如昏。","野色愁俱破，河流畏更浑。","惟应好僚友，孤寂义弥敦。","左丞京下宅，大半贮蛩螀。","容曳栖乌地，低迷卧鹿场。","几时衣定暑？","昨夜酒生凉。","太息时人语，依稀不可忘。","平生谈笑口，未是向人悭。","直以朋友内，难为伯仲间。","陈君元下榻，贺老自怀山。","见谓前修事，因之一破颜。","倚岩推许逊，负水揖文箫。","万里初邻并，长年此寂寥。","不要麟阁画，虚累鹤书招。","同是西江客，君当结梦樵。"]},{"t":"赠别徐教授之钦州二首","f":"曲","c":["徐子雅好易，白头来上京。","如何怀远檄？","竟往教专城。","山近烟霞密，江澄瘴疠清。","朋游政事少，况在仰修名。","冉冉岁月暮，悠悠关塞长。","歌钟凝旅宴，舞袖拂征艎。","到日梅花乱，来春蕙草芳。","南金自昔重，寄赠可能忘？"]},{"t":"用韵报李宗明二首","f":"曲","c":["李侯持重器，隐若一雄邦。","敌至婴城守，威行走传降。","薰弦须和五，古剑肯埋双。","见说研朱地，车声绕碧窗。","古来辇毂下，不畜隐沦人。","况有龙门旧，宁无兽锦新？","江山政如画，松柏自宜春。","可是东城曲？","过从步屧频。"]},{"t":"赠颠叟僧别二首","f":"曲","c":["问子家何在，名山越树春。","来游万里道，去作五台宾。","乞食宁忘禄？","行歌若有神。","曾逢陆脩静，招入社中人。","未是真颠者，能颠故有余。","试留吴郡草，为报揭阳书。","带日辞铜马，投云听木鱼。","南归定何日？","白象守林庐。"]},{"t":"和李溉之园居杂咏八首","f":"曲","c":["书剑上青霄，乡关雨雪遥。","年华侵水竹，客思堕山苗。","会想商岩绮，将从郑里桥。","文词诚小伎，祗比俗情饶。","岂是幽栖地，飞腾亦未量。","城根分鼠壤，池面合鱼梁。","名久喧郎署，歌时感女桑。","畏卿音调苦，畴复贵相忘。","圃色依帘障，天光切户庭。","草生连夜雨，花落遍池星。","未遂翔寥廓，真堪托晦冥。","逢时须紫燕，得意拂青萍。","亦欲依家耳，衡门斗极边。","乡心征化鹤，宦径跕飞鸢。","白日抛书送，青山拂槛延。","风流自无已，忆上五湖船。","都无京国意，满眼旧生涯。","壁隐崆峒木，毡蒙婀娜花。","善邻垣故辟，爱客酒能赊。","皦皦荒途子，音期只尔遐。","偶从耕凿事，便有古人风。","井泻千畦碧，林然独杏红。","世情何近远？","宦秩自卑崇。","任道流行意，雩坛或与同。","磊落人间士，名成定不虚。","愿陈元有策，交荐可无书？","莫遣从师苦，因将作吏疏。","吾徒岂念此？","愧尽马相如。","丹柰花初结，朱樱子半成。","寝兴因物变，筋力与年增。","燕拂承尘去，蜂随曳杖行。","玉泉几千仞，好在翠如倾。"]},{"t":"种瓠二首","f":"曲","c":["岂是阶庭物，支离亦自奇。","已殊凡草蔓，缀得好花枝。","带雨宁无实，凌霄必有为。","啾啾群鸟雀，从汝踏多时。","嘉瓠吾所爱，孤高更可人。","不虚种植意，终系发生神。","有叶诚藏用，无容岂识真。","明年应见汝，众子亦轮囷。"]},{"t":"离席合赋赠南剑教授盛复之之官，凡十首","f":"曲","c":["盛君江海士，直气轧霄峥。","翻为诗书苦，焉知印绶荣？","度辽曾万里，走越更千城。","便是来难得，乡关近慰情。","首路向朱夏，出关犹到官。","麦收风涨暑，梅熟雨留寒。","气候随方异，才名自古难。","岂容贤若尔，教授老江干。","江浦见黄鹂，石榴花满枝。","欲攀犹屡惜，已去复何疑？","蚤畏红英乱，还当绛帐移。","驿程动易隔，留待寄相思。","娟娟沙尾鹤，毛羽映江鲜。","去住长如此，飞鸣岂偶然？","仙家应汗漫，侯判莫留连。","忆得东门事，须君正壮年。","闽南荔子熟，问客倘能来。","暂为诸生屈，宁伤独茂才？","云飞绝寒落，雨过行平台。","赋就新诗别，扁舟且莫催。","昔向辽东郡，长歌觅管宁。","此行无赠策，故事有谈经。","豆实登朱荔，虹光照紫萍。","龟山文物在，未用叹凋零。","跃马问入郭，解龟听报衙。","江沙侵细竹，墙蔓覆疏花。","政不离书阁，吟应上钓槎。","有怀当皓月，玉署听啼鸦。","碧草津头郡，虽偏是胜游。","野人频识剑，稚子亦能舟。","稍定传衣怪，聊资宦秩周。","南来说风物，有待细询求。","杯酒莫停手，路长思八闽。","精灵深狎客，瘴雾簿侵人。","海近渔船集，山空鸟道邻。","来京书一束，赖尔老随身。","黄帽催晨发，邮签报旅程。","溯风斜帽举，虚日乱弦鸣。","异俗从谁变？","真才不自成。","倘于高第内，岁久得欧生。"]},{"t":"奉寄淮东宪孔知事二首","f":"曲","c":["日有乌台使，因君问合肥。","熊章官下食，虎略幕中威。","易政听时报，交深念日迟。","知音偕上列，须假绣为衣。","昔在东门别，相离数岁星。","一官何委折？","万里独飘零。","楚树春频落，燕云晚自停。","几时淮浦月？","仍与共扬舲。"]},{"t":"晚经皮使君江居不见，赋简二首","f":"曲","c":["使君直节更无双，又拜浓恩出海邦。","绝域朱幡兼皂盖，名园碧树倚清江。","山明残雪当松坞，岸断斜晖射石矼。","愧杀会稽王子敬，过门未遂此心降。","忆得去年寻药圃，甚怜此日负花时。","拿舟况说看灯及，叩阁应烦把酒思。","浩浩古今奚我独？","悠悠江海是吾师。","西墙倘遂残年愿，来往风流或可期。"]},{"t":"秋日集咏奉和潘李二使君浦编修诸公十首","f":"曲","c":["古蓟城边白露零，秋声不任旅人听。","差差乳燕朝辞舍，呖呖高鸿暮过庭。","以病酬閒翻自恶，将愁抵醉祇难醒。","何人解拟匡庐赋，千仞冈头瀑泻瓴。","将身跳出市间壶，美贾由来不用沽。","大地骑鹏须共化，中宵上鸐倩谁扶？","庶几未老投簪去，尚可长生折简呼。","此辈终非尘土物，明朝种橘学诸苏。","生也无涯死有涯，抛书几拟问南华。","要知立志非多事，但使成言自一家。","寒树接天霜映鹘，湿芜满地雨生蛙。","相过傥遂携尊酒，检按墙东野菊花。","迥无江左管夷吾，谁复能称晋宋书。","运本关天聊尔耳，力能盖世复奚欤。","百年草草云龙地，四海悠悠法象庐。","曾向钟山酹芳草，至今心死及菑畬。","流落移家白帝都，低头愧尽马相如。","题桥一字终何益，卖赋千金竟或无。","风月长留前辈咏，尘沙满载古人书。","此身泛寄空江上，已异当时旧鬓须。","浮世有由虚尺寸，明时无伎答涓埃。","偶随青琐须高步，欲缀丹书甚寡才。","断壁云过溪笛逝，虚林雨映寺钟来。","几年闲却持螯手？","强为清秋送酒杯。","潘公墙角树连庭，曾是笙簧昼夜听。","门巷祇今埋粪壤，轮蹄自昔走雷霆。","长因午睡思茶灶，却为朝吟款竹扃。","若续济南名士录，莫令憔悴鹊湖亭。","李侯高朗若空晴，议论诗书满腹撑。","期接仙舟应少便，偶分宫砚亦多情。","蛮荒异俗中年历，河汉频秋向夕倾。","此去暂烦南郡守，旗旄勿用野人惊。","浦君高价本璠玙，多幸蒹葭得所于。","学道初轻千里骥，收功直到九州鱼。","诗探饭颗尤难测，赋拟兰陵定不虚。","月月西垣更夜直，还应共我惜居诸。","秋入江山锦绣开，白云红叶尽诗才。","句成底用三年得，槎在应须八月回。","自是每为浮客累，非关不受故人催。","凭将寄语词林老，风雨重阳又近来。"]},{"t":"休日出郊三首","f":"曲","c":["上方钟鼓昼依稀，出定诸僧绾法衣。","迎客犹能下殿走，访人更有待寻归。","秃鹙近水行仍啄，危燕当梁乳更飞。","自古旅怀烦慰藉，并游万事莫相违。","丞相祠西椰子园，新开湖馆见遥村。","风含碎羽珊珊过，浪涌长干剡剡翻。","止息幸然无鹤爵，去来应或有鹏鹍。","江边柳树晴相倚，祇为行人作断魂。","歇马高林烟雾开，感今怀古独登台。","迁臣逐客皆前辈，幕长郎官尽上才。","放浪已闻穷九域，飞腾终合近三台。","谢公自有青云屐，且与从容步紫苔。"]},{"t":"寄上甘肃吴右丞三首","f":"曲","c":["要使唐虞化远覃，玉门关下屈征骖。","多忧总为民心苦，有喜惟闻郡姓甘。","日晚边沙黄浼浼，天晴陇树碧毵毵。","国风不系秦州外，自此西人识召南。","历数先朝辅弼贤，如公孰可语同年？","二童一马临荒镇，百感千忧倚上天。","深厚已闻鸾诏趣，平安不用雁书传。","别来濯濯春城柳，谁信秋风慰目前？","塞上孤鹰白雪毛，塞门风物静萧骚。","黄河西去从天下，泰华东来拔地高。","枸杞莫将如薏苡，醍醐足饮胜蒲萄。","遥瞻圭衮还朝日，正属江湖心绪劳。"]},{"t":"送陈从事归江东二首","f":"曲","c":["长年京下送人归，初及扁舟指翠微。","岂意遂闻鸿鹄操？","却须同制芰荷衣。","清江碧树重重见，紫燕黄鹂处处飞。","如此交游二三辈，何因中岁每相违？","吴侬呼剑每通神，铸作由来极苦辛。","天下纵无增价士，夜中须有识光人。","即今况蹑青云地，何日重翻紫陌尘？","令弟两街清显甚，定应携手接星辰。"]},{"t":"傅之经历谒告还湘中，未语别而宵征。翌日，与僚友追送生居亭中二首","f":"曲","c":["美人归思落沧波，昨者论心肯重过。","寒尽极知春意在，夜深无奈月明何。","海隅虽暂违霜幕，天上应须接玉珂。","如此才贤移病去，瘴烟端的为谁多。","北风尽日破南溟，行路经年倚寿星。","子自全家依翠岳，我犹万里隔青冥。","山田鹿下投书去，水馆猿啼却坐听。","王事驰驱知有素，何由重见此邮亭。"]},{"t":"百丈春日纪怀三首","f":"曲","c":["江墅群芳手自栽，春前相次斸苍苔。","邻僧昨许山兰送，社妪新分圃药来。","本为圣情思共济，更饶生事得相催。","粤王溪畔韶光好，谁想经年逝不回？","东风久不到新堂，生意虽微未卒荒。","草上葫荽偏挺特，花间芦菔故高长。","时来岂尽栽培力，物化须知长养方。","葵藿有心终莫夺，每闻支笏照沧浪。","飞飞燕子守绳枢，爱尔由来似凤雏。","肯谓撩人嗔坐对，向曾去我忆巢孤。","涂泥须责经营苦，爪觜无供啄哺娱。","春社风光时有再，天生品汇各悬殊。"]},{"t":"奉和王继学怀济南旧游四首","f":"曲","c":["前辈风流逐断澌，济南旧录故人诗。","遥知灵运初游日，正是元方后载时。","青社寥寥成异物，丹丘皛皛属遐思。","壮年易动离居感，缱绻花前金屈卮。","楼上看山翠黛浮，楼前沽酒锦缠头。","登临试与询湖雁，豪杰亲曾侣海鸥。","沙岭晓晴云散出，野亭春尽水交流。","意中故旧那能得，强拟偷生赋远游。","每愁大手不如燕，多见公侯胜昔年。","计拙欲求千户等，心劳政类十洲仙。","几回见月思归去，暂到临风复惘然。","剪尽绿杨三万树，多因无处著啼鹃。","手接新词绝底清，一双白眼为君青。","寰区政待新年谷，江汉徒传赤日萍。","断雨潜蛟虚水榭，远波回鹭实云汀。","此情可在齐州外，不解无人问独醒。"]},{"t":"建昌小湖望庐阜二首","f":"曲","c":["青云覆叠巘，白鸟度平湖。","钓屿夜来雨，山深知有无？","我怀贞炼士，多在岩谷阴。","惟有高林月，长知望远心。"]},{"t":"绝句六首","f":"曲","c":["障拥芙蓉竞，灯随榉柳移。","繁星临迥野，疏雨过高池。","江上打鱼船，有头那无尾。","与卿相见时，不望如鱼水。","乡路西州是，延平那向东。","片帆侬会使，祇是怕随风。","水清滩自急，荡桨直须人。","劝卿休恨水，多为不知津。","水如青铜镜，山色绿芙蓉。","中天明月上，此处好相逢。","日净芙蓉远，春明芍药长。","谁怜玉蝴蝶？","正似锦鸳鸯。"]},{"t":"怀京城诸公书崖州驿四首","f":"曲","c":["甚忆清河元侍讲，送行犹有玉堂诗。","只今夜夜陇头月，照见征人有所思。","复忆济南张吏部，作诗文气压诸公。","佳儿亦是门生辈，尚想他年似若翁。","绣衣御史果能文，蜀道新来有李君。","记得京城黄菊烂，为余来觅董将军。","妙为文字吾雄甲，精切于今孰与俦。","说著奉常虞博士，恨渠犹不见崖州。"]},{"t":"至乌石邸舍二首","f":"曲","c":["不见居人只见村，离家茅屋又黄昏。","面前沧海来无际，闻说占城对县门。","苦竹丛西石色乌，来时依旧驿亭孤。","自从历遍崖州路，不敢弯弓射鹧鸪。"]},{"t":"福州杂诗三首","f":"曲","c":["前日题诗自侯官，计程今日到云端。","家人定得平安字，最念痴儿不解看。","海隅霜熟蛎房肥，狮子桥东望翠微。","安得建阳一斗酒，少随甘旨到柴扉。","虎豹几曾惊石鼓，鱼龙独解隐金沙。","遮藏翠荔馀千刹，掩映朱霞倚万家。"]},{"t":"斋居即事用敖徵君韵二首","f":"曲","c":["故人不见意何如，流水孤村处士庐。","犹记去年霜橘熟，分甘曾得寄来书。","桑溪竹圃路团团，门巷都非少日看。","送客棹船频借问，向来江面是阑干。"]},{"t":"春日次韵友生绝句二首","f":"曲","c":["马颊河阳近北辰，去来犹尔恨通津。","陌头总是春风树，自笑杨花只恋人。","旅食京华日欲晡，家园迢递隔天隅。","妻孥预识羁怀苦，解事新来一字无。"]},{"t":"次韵古体二首","f":"曲","c":["偶为淳朴语，即有希夷风。","在世能勿忤，聊以古为同。","大巧三代人，所拙辨伪工。","曲哉末学士，妄拟述作功。","至性苟能尽，焉得推盛隆？","先师予狂狷，盖愤失所中。","于时得依归，敢叹吾道穷？","圣道缺已久，文不充其资。","自从夏殷来，因革当从谁？","中更鸣鸟闻，载叹德之衰。","寥寥大师乐，复得存那猗。","大音苟有托，不必稽其辞。","设有盈樽酒，日夕斟酌之。","乐杯当在手，自今不复疑。","胡为不复疑？","贤者当明知。"]},{"t":"奉同陈应举月夜斋宿玉堂有赋五首","f":"曲","c":["崇馆肃玄閟，虚扉敞彤碧。","词林何苍苍！","国器皆奕奕。","顾惟朴樕材，谬忝文字役。","尝僚负简陋，祇事深踧踖。","于焉严明享，况复在今夕。","奉礼惭明信，敛诚资宴歇。","风露洒九天，星辰逼双阙。","屏听非效聪，规行殊改刖。","春容启华萼，宵影动林樾。","思君空中云，惠我席间月。","幅员施广图，轮魄昭晬像。","三后犹照临，万代极瞻仰。","宝之在禁密，本以肃灵爽。","岂伊呈苾芬？","遂尔通肸蚃。","洞洞乎其忠，洋洋如在上。","塞直慕南董，良明宪夔皋。","孰为非我事？","相命须其曹。","被褐骞寒素，奉璋参俊髦。","王戡载简册，臣职放牲牢。","忠敬道无二，笑谈谊弥高。","烛暗曙钟远，诗成春漏沉。","古苔见隐约，幽桧响萧森。","白雪留寒色，青云延夙心。","在阙谅当补，唯贤庶可钦。","愿逐西蟾影，长栖丹凤林。"]},{"t":"七月初二夜，洪州对月，怀伯丈亲舍","f":"曲","c":["居止简物竞，颇受岁月侵。","诚愿输昆仑，遐举遗浮沉。","时冬万物敛，野迥景载阴。","雉鸣穑在场，烟火村巷深。","儿女戏我前，有酒聊自斟。","自斟何足贵？","得饮胜千金。","圣哲去已远，六籍传其心。","受生敢不爱？","发愤摅长吟。","念世居难终，忘世亦易度。","今旦庭树落，空明见飞雨。","沉痾从谁解？","采草时自炷。","万里无一归，愿得妙者悟。","寥寥宇宙间，舍此复奚慕？"]},{"t":"观钱塘上人墨兰二首","f":"曲","c":["兰以比君子，所贵者幽深。","黯然空谷中，远为人所钦。","志士秉美德，如玉复如金。","笃实而辉光，芳搴出乔林。","偶然为时出，节义凛森森。","下惬烝庶望，上当君王心。","功成无所累，宿好在云岑。","翰墨者谁子？","妙年出江关。","剪须事浮屠，游戏在云山。","时将骚臣意，写入尺素间。","嗟彼为形士，长往不知还。","其心犹有慕，岂不薄茅菅？","学古宁为人？","诚念修已艰。","圣哲虽异代，讵云不可攀？"]},{"t":"次韵赋吴尊师漱芳亭白、红梅花二首","f":"曲","c":["梅仙之宫在何许，五尺青天隔风雨。","冰雪肌肤绰约人，铁石心肠软媚语。","行藏一粒粟中寄，品格百花头上数。","所以商廷和鼎功，大濩登之六代舞。","呜呼，安得东皇锡白社，胙以金陵为尔土。","惟梅本是群仙侣，别有芳姿照微雨。","人尝误作杏花看，我亦戏作莲花语。","即色非空还是色，遽数不终须悉数。","偷服丹砂抹玉唇，赭颜谪向春风舞。","呜呼，安得东皇锡赤社，胙以朱陵为尔土。"]}]};